	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"INCLUSION CRITERIA",inclu_disease}', 'definition', 'This refers to any suspected or confirmed infection(s).', NULL, 91374),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"INCLUSION CRITERIA",inclu_disease}', 'completionGuide', 'If more than one infection is suspected, select the most likely and complete the PATHOGEN TESTING section with laboratory confirmation.', NULL, 91375),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"INCLUSION CRITERIA",inclu_reason}', 'question', 'Is the suspected or confirmed infection the reason for hospital admission?', '{Yes,No,Unknown}', 91376),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"INCLUSION CRITERIA",inclu_reason}', 'definition', 'This refers to whether suspected or confirmed infection with the pathogen of interest if the reason (indication) for the hospital admission.', NULL, 91377),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"INCLUSION CRITERIA",inclu_reason}', 'completionGuide', 'Indicate ''Yes'' if suspected or confirmed infection with the pathogen of interest if the reason (indication) for the hospital admission. Indicate ''No'' if the suspected or confirmed infection with the pathogen of interest is not the reason (indication) for hospital admission.', NULL, 91378),
	('2026-03-18 11:00:12.956231+00', NULL, 'answerOption', 'Yes', NULL, 91379),
