	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"CO-MORBIDITIES AND RISK FACTORS: Existing prior to this current illness and is ongoing",comor_hba1c_pcnt}', 'completionGuide', 'Enter the numerical value for HbA1C level expressed as a percentage %.', NULL, 91927),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"CO-MORBIDITIES AND RISK FACTORS: Existing prior to this current illness and is ongoing",comor_smoking}', 'question', 'Ever smoked', '{Yes,No,Unknown}', 91928),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"CO-MORBIDITIES AND RISK FACTORS: Existing prior to this current illness and is ongoing",comor_smoking}', 'definition', 'This refers to smoking cigarettes, cigars, pipes or equivalent. Never smoker is defined as a person who has never smoked at the time of the assessment or has smoked less than 100 of the above items in their life. Do not include smoke-free tobacco products such as chewed tobacco or electronic nicotine delivery devices. ', NULL, 91929),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"CO-MORBIDITIES AND RISK FACTORS: Existing prior to this current illness and is ongoing",comor_smoking}', 'completionGuide', 'Indicate ''Yes'', if this is condition existed prior to admission with this current illness and remains an active medical condition. Indicate ''No'' if the patient has never smoked (defined as a person who has never smoked at the time of the assessment or has smoked less than 1 of the above items in their life).', NULL, 91930),
