	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral}', 'question', 'Antiviral', '{Yes,No,Unknown}', 92045),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral}', 'definition', 'An antiviral agent refers to any agent(s) prescribed to treat or prevent viral infections by interfering with the viral replication cycle. Examples of neuraminidase inhibitors include oseltamivir, ribavirin, acyclovir and lopinavir/ritonavir. Topical preparations are not included.', NULL, 92046),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral}', 'completionGuide', 'Indicate ''Yes'', if the patient has taken an antiviral in the 14 days prior to this most recent admission / presentation', NULL, 92047),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral_type}', 'question', 'Antiviral', NULL, 92048),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral_type}', 'definition', 'An antiviral agent refers to any agent(s) prescribed to treat or prevent viral infections by interfering with the viral replication cycle. Examples of neuraminidase inhibitors include oseltamivir, ribavirin, acyclovir and lopinavir/ritonavir. Topical preparations are not included.', NULL, 92049),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral_type}', 'completionGuide', 'Select the antiviral(s) prescribed or taken by the patient in the 14 days prior to this most recent admission / presentation', NULL, 92050),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral_route}', 'question', 'Antiviral administration route', '{Oral,Inhaled,IV,Topical,Unknown}', 92051),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral_route}', 'definition', 'This refers to the part of the body through which or into which, or the way in which, the medicinal product (drug) is introduced. Oral refers to administering by mouth. Inhaled refers to administration through the respiratory route (insufflation into the respiratory tract). IV (intravenous) refers to administering into bloodstream through injection into a vein. Topical refers to administration by application of drug preparations to the surfaces of the body, especially the skin or mucous membranes.', NULL, 92052),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviral_route}', 'completionGuide', 'Indicate the route of administration for the antiviral agent.', NULL, 92053),
	('2026-03-18 11:00:12.956231+00', NULL, 'answerOption', 'Oral', NULL, 92054),
	('2026-03-18 11:00:12.956231+00', NULL, 'answerOption', 'Inhaled', NULL, 92055),
	('2026-03-18 11:00:12.956231+00', NULL, 'answerOption', 'IV', NULL, 92056),
	('2026-03-18 11:00:12.956231+00', NULL, 'answerOption', 'Topical', NULL, 92057),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviraldate}', 'question', 'Antiviral start date', NULL, 92058),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviraldate}', 'definition', 'This refers to the date the medication was started / first dose was administered. ', NULL, 92059),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviraldate}', 'completionGuide', 'Enter the date when the medication was started / first dose was given. If the precise date is unknown, enter an estimate. (Use the format DD/MM/YYYY)', NULL, 92060),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_antiviralday}', 'question', 'Number of days antivirals taken', NULL, 92061),
