	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_immunusupp}', 'question', 'Immunosuppressant agents (not corticosteroids)', '{Yes,No,Unknown}', 92082),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_immunusupp}', 'definition', 'This refers to a patient who is known to have taken prescribed medications that are known to have an immunosuppressing effect (excluding steroids/corticosteroids). Topical preparations should not be recorded.', NULL, 92083),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_immunusupp}', 'completionGuide', 'Indicate ''Yes'', if the patient has taken an immunosuppressant agent in the 14 days prior to this most recent admission / presentation', NULL, 92084),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"MEDICATION PRIOR TO THIS ADMISSION / PRESENTATION",drug14_immunusupp_type}', 'question', 'Immunosuppressant agents (not corticosteroids)', NULL, 92085),
