	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"PREGNANCY DETAILS",preg_geswek}', 'question', 'Gestational weeks at presentation', NULL, 92839),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"PREGNANCY DETAILS",preg_geswek}', 'definition', 'This refers to the gestational age of the foetus (written in weeks). It can be calculated from the woman''s last menstrual period (LMP) or calculated using the best obstetrical estimated due date (EDD) based on the following formula: Gestational Age = (280 - (EDD - Reference Date)). The reference date is the date in which you are trying to determine the gestational age.', NULL, 92840),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"PREGNANCY DETAILS",preg_geswek}', 'completionGuide', 'Indicate the estimated gestational age of the foetus (in weeks).', NULL, 92841),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"PREGNANCY DETAILS",preg_postpartum}', 'question', 'Post-partum (within 6 weeks of delivery)', '{Yes,No,Unknown}', 92842),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"PREGNANCY DETAILS",preg_postpartum}', 'definition', 'This refers to the temporal period relating to mother from completion of labour until six weeks post-delivery.', NULL, 92843),
	('2026-03-18 11:00:12.956231+00', '{ARC,presentation,"PREGNANCY DETAILS",preg_postpartum}', 'completionGuide', 'Indicate ''Yes'', if the patient is in post-partum period (within 6 weeks of delivery).', NULL, 92844),
