	('2026-03-18 11:00:12.956231+00', '{ARC,daily,"VITAL SIGNS & ASSESSMENTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",vital_highesttem_c}', 'definition', 'Refers to the highest peripheral body temperature (rectal if <3 months) in degrees Celsius (°C) between 00:00 and 24:00 on day of assessment.', NULL, 92918),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,"VITAL SIGNS & ASSESSMENTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",vital_highesttem_c}', 'completionGuide', 'Enter the highest peripheral body temperature (°C) recorded between 00:00 and 24:00 on day of assessment.', NULL, 92919),
