	('2026-03-18 11:00:12.956231+00', '{ARC,daily,"VITAL SIGNS & ASSESSMENTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",vital_o2supp_spo2}', 'question', 'Oxygen saturation with supplemental oxygen (%)', NULL, 92958),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,"VITAL SIGNS & ASSESSMENTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",vital_o2supp_spo2}', 'definition', 'This refers to the oxygen saturation, that may be measured by pulse oximetry or by arterial blood gas analysis. It is irrespective of ventilation or supplemental oxygen requirement.', NULL, 92959),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,"VITAL SIGNS & ASSESSMENTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",vital_o2supp_spo2}', 'completionGuide', 'Enter the percentage oxygen saturation. Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.', NULL, 92960),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,"VITAL SIGNS & ASSESSMENTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",vital_o2supp_spo2how}', 'question', 'How was oxygen saturation with supplemental oxygen measured?', '{"Pulse Oximetry","Arterial blood gas measurement",Other,Unknown}', 92961),
