	('2026-03-18 11:00:12.956231+00', '{ARC,daily,IMAGING,imagi_dailydata}', 'definition', 'This refers only to those imaging or radiological test(s) that were performed at the time that the patient stayed in the clinical facility (hospital) and collected on the date of assessment.', NULL, 94205),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,IMAGING,imagi_dailydata}', 'completionGuide', 'Indicate ''Yes'', if imaging or radiological test(s) were performed at the time that the patient stayed in the clinical facility (hospital) and collected on the date of assessment.', NULL, 94206),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,IMAGING,imagi_xray}', 'question', 'Chest X-ray performed', '{Yes,No,Unknown}', 94207),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,IMAGING,imagi_xray}', 'definition', 'This refers to any chest x-ray that was performed at the time the patient stayed in the clinical facility (hospital) and collected on the date of assessment. Chest x-ray refers to radiological visualization of the chest and organs of the thoracic cavity; not restricted to visualization of the lungs, using x-rays.', NULL, 94208),
	('2026-03-18 11:00:12.956231+00', '{ARC,daily,IMAGING,imagi_xray}', 'completionGuide', 'Indicate ''Yes'', if any chest x-ray was performed at the time the patient stayed in the clinical facility (hospital) and collected on the date of assessment. ', NULL, 94209),
