	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_neurological}', 'question', 'Neurological complications', NULL, 94556),
	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_neurological}', 'definition', 'Defined as any complications of the nervous system', NULL, 94557),
