	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_eschar}', 'question', 'Skin tissue loss or eschar', '{Yes,No,Unknown}', 94759),
	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_eschar}', 'definition', 'Eschar is defined as a dry, dark scab or falling away of dead skin, typically caused by a burn, an insect bite (e.g. some rickettsial infections), or infection with anthrax.', NULL, 94760),
	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_eschar}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this at any time during hospitalisation.', NULL, 94761),
	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_scar}', 'question', 'Skin scarring', '{Yes,No,Unknown}', 94762),
	('2026-03-18 11:00:12.956231+00', '{ARC,outcome,"COMPLICATIONS: Experienced at any time from day of presentation to day of discharge / outcome.",compl_scar}', 'definition', 'This refers to a permanent mark left on the skin in the process of wound healing.', NULL, 94763),
