	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_feedingdiff}', 'question', 'Feeding difficulty', '{Yes,No,Unknown}', 97243),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_feedingdiff}', 'definition', 'Defined as impaired ability to eat related to problems gathering food and getting ready to suck, chew, or swallow it.', NULL, 97244),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_feedingdiff}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 97245),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag}', 'question', 'Bleeding / haemorrhage', '{Yes,No,Unknown}', 97246),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_sev}', 'question', 'Severe bleeding / haemorrhage (requires intervention)', '{Yes,No,Unknown}', 97247),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site}', 'question', 'Specify bleeding / haemorrhage site(s)', '{Skin,Petechiae,Nose,Gums,"GI tract","Urinary tract",Vagina,Unknown,Other(s)}', 97248),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site_oth}', 'question', 'Specify other bleeding / haemorrhage site(s)', NULL, 97249),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site_oth}', 'definition', 'This refers to the location of bleeding/haemorrhage site(s).', NULL, 97250),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site_oth}', 'completionGuide', 'If ''Other'', write the location of bleeding/haemorrhage site(s).', NULL, 97251),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_dailydata}', 'definition', 'This refers to signs recorded o this date.', NULL, 97252),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_dailydata}', 'completionGuide', 'Indicate ''Yes'', if you want to record signs data for this day of assessment. ', NULL, 97253),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_sys}', 'definition', 'This refers to systemic / general / non-specific signs', NULL, 97254),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_hypotonia}', 'question', 'Decreased tone / hypotonia', '{Yes,No,Unknown}', 97255),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_hypotonia}', 'definition', 'This refers to generalized muscular hypotonia (abnormally low muscle tone).', NULL, 97256),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_hypotonia}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 97257),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_ftt}', 'question', 'Failure to thrive', '{Yes,No,Unknown}', 97258),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_ftt}', 'definition', 'This refers to less than normal weight gain in an infant or child, which may include poor linear and head growth.', NULL, 97259),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_ftt}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this at any time during the date of assessment.', NULL, 97260),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_resp}', 'definition', 'This refers to signs relating to the respiratory system.', NULL, 97261),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_nasalflar}', 'question', 'Nasal flaring', '{Yes,No,Unknown}', 97262),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_nasalflar}', 'definition', 'Defined as an enlargement of the nostrils during breathing; although there are many possible causes, it can be a sign of respiratory distress in young infants.', NULL, 97263),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_nasalflar}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 97264),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_grunt}', 'question', 'Grunting', '{Yes,No,Unknown}', 97265),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_grunt}', 'definition', 'Defined as a noisy breathing sound that occurs when a person exhales, and is a sign of respiratory distress', NULL, 97266),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_grunt}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 97267),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_parot}', 'question', 'Parotitis', '{Yes,No,Unknown}', 97268),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_parot}', 'definition', 'This refers to inflammation of the parotid glands.', NULL, 97269),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_parot}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced between 00:00 to 24:00 on day of assessment.', NULL, 97270),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_cvs}', 'definition', 'This refers to signs relating to the cardiovascular system.', NULL, 97271),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_tachycardia}', 'question', 'Rapid heart beat / pulse (tachycardia)', '{Yes,No,Unknown}', 97272),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_tachycardia}', 'definition', 'Refers to a rapid heartrate that exceeds the range of the normal resting heartrate for age. ', NULL, 97273),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_git}', 'definition', 'This refers to signs relating to the gastrointestinal system.', NULL, 97274),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_melaena}', 'question', 'Melaena (blood in faeces)', '{Yes,No,Unknown}', 97275),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_haematochezia}', 'question', 'Haematochezia (fresh blood in stools)', '{Yes,No,Unknown}', 97276),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_heme}', 'definition', 'This refers to signs relating to the haematological system.', NULL, 97277),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_cns}', 'definition', 'This refers to signs relating to the neurological system.', NULL, 97278),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_bulgefont}', 'question', 'Bulging fontanelle', '{Yes,No,Unknown}', 97279),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_bulgefont}', 'definition', 'This refers to the membranous areas between cranial bones in a newborn that appear elevated or full.', NULL, 97280),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_bulgefont}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 97281),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_eye}', 'definition', 'This refers to signs relating to the eye.', NULL, 97282),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_conjunhemor}', 'question', 'Conjunctival haemorrhage', '{Yes,No,Unknown}', 97283),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_ocularoth}', 'definition', 'This refers to other signs relating to the eye, not specified above.', NULL, 97284),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_ocularoth_spec}', 'definition', 'This refers to other signs relating to the eye, not specified above.', NULL, 97285),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"SIGNS: Record the clinical findings observed between 00:00 and 24:00 on the day of assessment",sign_ocularoth_spec}', 'completionGuide', 'If ''Yes'', specify other opthalmological signs ', NULL, 97286),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid}', 'definition', 'This refers to any prescribed fluids (oral, or parenteral/intravenous), excluding those the patient consumes in a non-prescribed dietary manner.', NULL, 97287),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_prothrombin}', 'definition', 'Prothrombin time or PT.', NULL, 97368),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid}', 'completionGuide', 'Indicate ''Yes'', if the patient was prescribed and received fluids between 00:00 and 24:00 hours on day of assessment.', NULL, 97288),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_oral}', 'definition', 'This refers to enteral/oral fluids for the purposes of rehydration.', NULL, 97289),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_oral}', 'completionGuide', 'Indicate ''Yes'', if the patient received oral rehydration between 00:00 and 24:00 hours on day of assessment.', NULL, 97290),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_oralvol}', 'definition', 'This refers to enteral/oral fluids for the purposes of rehydration.', NULL, 97291),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_oralvol}', 'completionGuide', 'If ''Yes'', record the amount of eneteral/oral fluids for the purposes of rehydration given between 00:00 and 24:00 on day of assessment in millilitres (mL).', NULL, 97292),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_parent}', 'definition', 'This refers to intravenous fluid which includes crystalloid, albumin, gelatin, starches or other solutions.', NULL, 97293),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_parent_type}', 'definition', 'This refers to the type of parenteral or intravenous (IV) fluid is prescribed as a replacement of fluid, electrolytes, calories, vitamins, and other nutritional substances. Intravenous fluids may be crystalloids (commonly including 0.9% Sodium Chloride (Normal Saline), Lactated Ringer(USP), 0.45% Sodium Chloride (Half-normal saline), 0.45% normal saline + 4% Glucose (Half-normal saline with dextrose), 0.18%-0.3% Sodium Chloride + 4% Glucose (Hypotonic saline with dextrose), 5% Glucose (Dextrose 5% in Water), Ringeracetate or Plasmalyte) or colloids (commonly including gelatins, starches or albumin). ', NULL, 97294),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_parent_type}', 'completionGuide', 'Select the most appropriate option corresponding to the type of intravenous or parenteral fluid(s) administered.', NULL, 97295),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_cryst}', 'definition', 'Crystalloid fluids refer to aqueous solutions of mineral salts and other small, water-soluble molecules. They are commonly used for fluid resuscitation in the presence of hypovolemia, hemorrhage, sepsis, and dehydration Common crystalloids include 0.9% Sodium Chloride (Normal Saline), Lactated Ringer(USP), 0.45% Sodium Chloride (Half-normal saline), 0.45% normal saline + 4% Glucose (Half-normal saline with dextrose), 0.18%-0.3% Sodium Chloride + 4% Glucose (Hypotonic saline with dextrose), 5% Glucose (Dextrose 5% in Water), Ringeracetate or Plasmalyte.', NULL, 97296),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_fluid_colloid}', 'definition', 'Colloid fluids are solutions that contain large molecules, such as proteins or polysaccharides, which remain in the bloodstream for a longer duration compared to crystalloids. These fluids help maintain or expand intravascular volume by drawing water into the blood vessels via oncotic pressure. Common colloids include gelatins, starches or albumin. ', NULL, 97297),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_blood}', 'definition', 'This refers to a transfusion of blood (whole blood or packed red blood cells) or other blood products excluding human normal immunoglobulin (e.g. albumin, granulocytes, platelets, fresh-frozen plasma (FFP), FP24, PF-24, cryoprecipitate, protein C concentrate, cryosupernatant, or a specific non-recombinant clotting factor) at any time on the date of assessment. ', NULL, 97298),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_blood}', 'completionGuide', 'Indicate ''Yes'', if the patient received blood products or blood product transfusion any time between 00:00 and 24:00 hours on day of assessment. If ''Yes'' Select the product(s) below.', NULL, 97299),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_blood_type}', 'definition', 'This refers to a transfusion of blood (whole blood or packed red blood cells) or other blood products excluding human normal immunoglobulin (e.g. albumin, granulocytes, platelets, fresh-frozen plasma (FFP), FP24, PF-24, cryoprecipitate, protein C concentrate, cryosupernatant, or a specific non-recombinant clotting factor) at any time on the date of assessment. Platelets refers to the transfer of blood platelets from a donor to a recipient or reinfusion to the donor. Cryoprecipitate refers to a frozen blood product prepared from frozen plasma that contains fibrinogen (factor I), antihemophilic factor (factor VIII), factor XIII, von Willebrand factor (vWF) and fibronectin. Whole blood refers to intravenous administration of whole blood (blood that contains plasma and red blood cells) into an individual. Packed RBC refers to red blood cells from a unit of whole blood following removal of most of the plasma, leaving a unit with a haematocrit of about 60%. Fresh frozen plasma refers to the plasma that is separated from the whole blood and frozen quickly after a blood donation in order to be used for blood transfusions. Fibrinogen concentrate is a haemostatic agent used for the treatment of acute bleeding episodes in patients with congenital fibrinogen deficiency, including afibrinogenemia and hypofibrinogenemia.', NULL, 97300),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_blood_rcc}', 'question', 'Packed RBC (red cell concentrate) (units/24 hours)', NULL, 97301),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_blood_rcc}', 'definition', 'Packed RBC refers to red blood cells from a unit of whole blood following removal of most of the plasma, leaving a unit with a haematocrit of about 60%.', NULL, 97302),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_aptt}', 'question', 'Activated Partial Thromboplastin Time / APTT (sec)', NULL, 97369),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_intravenim}', 'definition', 'This refers to immunoglobulin preparations, containing primarily Immunoglobulin G (IgG), that are used as intravenous infusions. Examples include Octagam®, Intragam P®, KIOVIG®, Flebogamma 5% DIF®, Carimune NF®, Gamunex®, Gammagard S/D®, Gammagard Liquid®, Gammaked® and Privigen®.', NULL, 97303),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_plasmapher}', 'definition', 'Plasmapheresis (plasma exchange) refers to the extracorporeal separation of blood components, resulting in a filtered product. Methods include discontinuous flow centrifugation, continuous flow centrifugation and plasma filtration.', NULL, 97304),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_other}', 'definition', 'This refers to any other specific therapeutic intervention(s) or procedure(s) not otherwise characterised that you believe may be relevant.', NULL, 97305),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_other}', 'completionGuide', 'Indicate ''Yes'' if other intervention(s) or procedure(s) were used between 00:00 and 24:00 hours on day of assessment. ', NULL, 97306),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"TREATMENTS & INTERVENTIONS: Record all interventions given between 00:00 to 24:00 on day of assessment.",treat_other_spec}', 'completionGuide', 'If ''Yes'', please specify the therapeutic intervention(s) or procedure(s)not otherwise characterised that you believe may be relevant.', NULL, 97307),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_ecmo}', 'question', 'ECLS / ECMO', '{Yes,No,Unknown}', 97308),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_o2supp_pao2}', 'question', 'PaO2 sample type', '{Arterial,Capillary,Venous,Unknown,"Not done"}', 97309),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_o2supp_pao2}', 'definition', 'This refers to the type of blood sample used to measure partial pressure of oxygen in blood (PaO2) using blood gas analysis.', NULL, 97310),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_o2supp_pao2}', 'completionGuide', 'Select the type of blood sample used to measure partial pressure of oxygen.', NULL, 97311),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_pao2_kpa}', 'definition', 'This refers to the lowest PaO2 (in kPa) between 00:00 and 24:00 on day of assessment.', NULL, 97312),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_pao2_mmhg}', 'definition', 'This refers to the lowest PaO2 (in mmHg) between 00:00 and 24:00 on day of assessment.', NULL, 97313),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_prone}', 'definition', 'This refers to prone positioning which is the act of having the patient lying in the prone position to assist ventilation. It includes both invasive ventilation (intubated) patients and non-intubated or self-ventilating patients. ', NULL, 97314),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"RESPIRATORY SUPPORT: Record all respiratory interventions given between 00:00 to 24:00 on day of assessment.",treat_prone_when}', 'definition', 'This refers to the type of assisted ventilation when the patient was placed in prone position. It may be either invasive ventilation (intubated) patients or non-intubated / self-ventilating patients. ', NULL, 97315),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_icu}', 'definition', 'This refers to admission of the patient tointensive care units (ICU), intensive therapy/treatment units (ITU), critical care units, high dependency units (HDU) or unit of similar level between 00:00 and 24:00 hours on day of assessment.', NULL, 97316),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_neuromusc}', 'definition', 'This refers to the use of neuromuscular blockers between 00:00 and 24:00 hours on day of assessment.. Examples include Atracurium, Cisatracurium, Nimbex, Norcuron, Pancuronium, Pavulon, Rocuronium, Tracrium, Vecuronium, Zemuron.', NULL, 97317),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_nitricoxide}', 'definition', 'This refers to nitric oxide as in inhalant between 00:00 and 24:00 hours on day of assessment. Inhaled nitric oxide is typically used for hypoxic respiratory failure, among other uses.', NULL, 97318),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_rtt}', 'definition', 'This refers to treatments that substitute for the blood-filtering function of the kidneys. It includes dialysis (hemodialysis or peritoneal dialysis), hemofiltration, and hemodiafiltration. It may be intermittent or continuous.', NULL, 97319),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_rtt_typ}', 'definition', 'This refers to treatments that substitute for the blood-filtering function of the kidneys. It includes dialysis (hemodialysis or peritoneal dialysis), hemofiltration, and hemodiafiltration. It may be intermittent or continuous. Intermittent refers to procedures with non-continuous blood purification (e.g., dialysis, filtration and/or perfusion) via vascular access by increasing blood flow rate. Continuous refers to procedures with continuous blood purification (e.g., dialysis, filtration or perfusion) via vascular access designed to mimic kidney function in kidney diseases.', NULL, 97320),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_rtt_typ}', 'completionGuide', 'Select the single most appropriate option corresponding to the type of renal replacement therapy (RRT) or dialysis / hemofiltration', NULL, 97321),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_vasopress}', 'definition', 'This refers to continuous use of a vasopressor or inotrope for at least one hour. A vasopressor is a pharmaceutical agent that causes vasoconstriction. Agents include norepinephrine, epinephrine, vasopressin, terlipressin and phenylephrine. An inotrope is a pharmaceutical agent that alters the force of myocardial contractility. Commonly used ''positive'' inotropes include dobutamine, dopamine, milrinone and adrenaline (epinephrine).', NULL, 97322),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_vasopress1}', 'completionGuide', 'Indicate ''Yes'', if this agent(s) was used for at least one hour between 00:00 and 24:00 hours on day of assessment. Indicate the amount used below.', NULL, 97323),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_vasopress2}', 'question', 'Dopamine 5-15ug/kg/min OR epinephrine(adrenaline) / norepinephrine(noradrenaline) < 0.1ug/kg/min OR vasopressin OR phenylephrine', '{Yes,No,Unknown}', 97324),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_vasopress2}', 'completionGuide', 'Indicate ''Yes'', if this agent(s) was used for at least one hour between 00:00 and 24:00 hours on day of assessment. Indicate the amount used below.', NULL, 97325),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_vasopress3}', 'question', 'Dopamine >15ug/kg/min OR epinephrine(adrenaline) / norepinephrine(noradrenaline) > 0.1ug/kg/min', '{Yes,No,Unknown}', 97326),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_vasopress3}', 'completionGuide', 'Indicate ''Yes'', if this agent(s) was used for at least one hour between 00:00 and 24:00 hours on day of assessment. Indicate the amount used below.', NULL, 97327),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_critcareunlst}', 'completionGuide', 'Indicate ''Yes'' if other critical care intervention(s) or procedure(s) were used between 00:00 and 24:00 hours on day of assessment. ', NULL, 97328),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"ADVANCED CARE INTERVENTIONS: Record all advanced care interventions given between 00:00 to 24:00 on day of assessment.",critd_critcareunlst_oth}', 'completionGuide', 'If ''Yes'', please specify the critical care therapeutic intervention(s) or procedure(s)not otherwise characterised that you believe may be relevant.', NULL, 97329),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_dailydata}', 'definition', 'This section refers only to those laboratory tests that were performed at the time that the patient stayed in the clinical facility (hospital) and collected on the date of assessment. In general, results that were rejected by the clinical team (e.g. haemolysed blood samples, contaminated microbiology results) should not be reported.', NULL, 97330),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_fbc}', 'definition', 'This refers to results from full blood count ', NULL, 97331),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_fbc}', 'completionGuide', 'Indicate ''Yes'' to enter full blood count results', NULL, 97332),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_haemo_gdl}', 'definition', 'Haemoglobin (Hb or Hgb) refers to haemoglobin concentration measurement in blood.', NULL, 97333),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_haemo_gdl}', 'completionGuide', 'Write haemoglobin (g/dL) level. If there are multiple, report the measure furthest from the normal physiological or laboratory range between 00:00 and 24:00 hours on day of assessment.', NULL, 97334),
	('2026-03-24 07:38:44.812991+00', '{ARC,daily,"LABORATORY RESULTS: Record the value furthest from normal range between 00:00 to 24:00 on day of assessment.",labs_haemo_gl}', 'definition', 'This refers to the haemoglobin concentration measurement in blood.', NULL, 97335),
