	('2026-03-24 08:18:45.374493+00', NULL, 'answerOption', 'Eye pain', NULL, 98387),
	('2026-03-24 08:18:45.374493+00', NULL, 'answerOption', 'Visual disturbance', NULL, 98388),
	('2026-03-24 08:18:45.374493+00', '{ARC,presentation,"SIGNS AND SYMPTOMS ON ADMISSION: Indicate if experienced at any time from onset of this illness to the day of presentation.",adsym_ocularoth}', 'question', 'If other: Specify ocular complaint(s)', NULL, 98389),
