	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_sev}', 'definition', 'Defined as the severe bleeding / hemorrhage requiring medical intervention for hemostasis and/or hemodynamic support.', NULL, 98591),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_sev}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 98592),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site}', 'question', 'If yes: Specify bleeding / haemorrhage site(s)', '{Skin,Petechiae,Nose,Gums,"GI tract","Urinary tract",Vagina,Other(s),Unknown}', 98593),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site}', 'definition', 'This refers to the location of bleeding/haemorrhage site(s). Petechiae refer to small reddish or purplish spots in skin or mucous membrane as a result of localised haemorrhage. Nose bleeding refers to haemorrhage localized in the nose. Gum bleeding refers to haemorrhage affecting the gingiva. Gastrointestinal (GI) bleeding refers to haemorrhage in any segment of the gastrointestinal tract from oesophagus to rectum. Urinary tract bleeding refers to haemorrhage originating from any part of the urinary system. Vaginal bleeding refers to haemorrhage originating from vagina, unrelated to normal menstruation.', NULL, 98594),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_site}', 'completionGuide', 'Select the most appropriate option(s) corresponding to the location of bleeding/haemorrhage site(s).', NULL, 98595),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_other}', 'question', 'If other: Specify bleeding / haemorrhage site(s)', NULL, 98596),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_other}', 'definition', 'This refers to the location of bleeding/haemorrhage site(s).', NULL, 98597),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_haemorrhag_other}', 'completionGuide', 'If ''Other'', write the location of bleeding/haemorrhage site(s).', NULL, 98598),
