	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_neurodist}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 98622),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_cerebesig}', 'question', 'Cerebellar signs', '{Yes,No}', 98623),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_cerebesig}', 'definition', 'Refers to the presence of a constellation of neurological signs typically indicate cerebellar dysfunction. Signs include dysdiadochokinesia, dysmetria, ataxia, nystagmus, intention tremor, slurred or scanning speech, hypotonia.', NULL, 98624),
	('2026-03-24 08:18:45.374493+00', '{ARC,daily,"SIGNS AND SYMPTOMS: Indicate if experienced between 00:00 to 24:00 on day of assessment.",sympt_cerebesig}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 98625),
