	(67660, '2026-03-18 11:00:35.939913+00', 91373, 'french', 'Infection suspectée ou confirmée', NULL, 'Machine Translation', false),
	(67661, '2026-03-18 11:00:35.939913+00', 91373, 'portuguese', 'Infecção suspeita ou confirmada', NULL, 'Machine Translation', false),
	(67662, '2026-03-18 11:00:35.939913+00', 91373, 'spanish', 'Infección sospechada o confirmada', NULL, 'Machine Translation', false),
	(67663, '2026-03-18 11:00:35.939913+00', 91374, 'french', 'Il s''agit de toute infection suspectée ou confirmée.', NULL, 'Machine Translation', false),
	(67664, '2026-03-18 11:00:35.939913+00', 91374, 'portuguese', 'Refere-se a qualquer infecção suspeita ou confirmada.', NULL, 'Machine Translation', false),
	(67665, '2026-03-18 11:00:35.939913+00', 91374, 'spanish', 'Se refiere a cualquier infección sospechosa o confirmada.', NULL, 'Machine Translation', false),
	(67666, '2026-03-18 11:00:35.939913+00', 91375, 'french', 'Si plusieurs infections sont suspectées, sélectionnez la plus probable et remplissez la section « TEST DE DÉPISTAGE DE L''AGENT PATHOGÈNE » avec la confirmation du laboratoire.', NULL, 'Machine Translation', false),
	(67667, '2026-03-18 11:00:35.939913+00', 91375, 'portuguese', 'Se houver suspeita de mais de uma infecção, selecione a mais provável e preencha a seção TESTE DE PATÓGENOS com a confirmação laboratorial.', NULL, 'Machine Translation', false),
	(67668, '2026-03-18 11:00:35.939913+00', 91375, 'spanish', 'Si se sospecha más de una infección, seleccione la más probable y complete la sección PRUEBAS DE PATÓGENOS con la confirmación del laboratorio.', NULL, 'Machine Translation', false),
	(67669, '2026-03-18 11:00:35.939913+00', 91376, 'french', 'L''infection suspectée ou confirmée est-elle la raison de l''admission à l''hôpital ?', NULL, 'Machine Translation', false),
	(67670, '2026-03-18 11:00:35.939913+00', 91376, 'portuguese', 'A infecção suspeita ou confirmada é o motivo da admissão hospitalar?', NULL, 'Machine Translation', false),
	(67671, '2026-03-18 11:00:35.939913+00', 91376, 'spanish', '¿Es la infección sospechada o confirmada el motivo del ingreso hospitalario?', NULL, 'Machine Translation', false),
	(67672, '2026-03-18 11:00:35.939913+00', 91377, 'french', 'Il s''agit de savoir si l''infection suspectée ou confirmée par l''agent pathogène d''intérêt est la raison (l''indication) de l''admission à l''hôpital.', NULL, 'Machine Translation', false),
	(67673, '2026-03-18 11:00:35.939913+00', 91377, 'portuguese', 'Refere-se à existência de uma infecção suspeita ou confirmada pelo agente patogénico em questão, se for essa a razão (indicação) para a admissão hospitalar.', NULL, 'Machine Translation', false),
	(67674, '2026-03-18 11:00:35.939913+00', 91377, 'spanish', 'Se refiere a si la infección sospechosa o confirmada por el patógeno de interés es el motivo (indicación) del ingreso hospitalario.', NULL, 'Machine Translation', false),
	(67675, '2026-03-18 11:00:35.939913+00', 91378, 'french', 'Indiquez « Oui » si l''infection par l''agent pathogène concerné est suspectée ou confirmée et si elle est la raison (l''indication) de l''admission à l''hôpital. Indiquez « Non » si l''infection suspectée ou confirmée par l''agent pathogène concerné n''est pas la raison (l''indication) de l''admission à l''hôpital.', NULL, 'Machine Translation', false),
	(67676, '2026-03-18 11:00:35.939913+00', 91378, 'portuguese', 'Indique “Sim” se houver suspeita ou confirmação de infecção pelo patógeno de interesse se esse for o motivo (indicação) da admissão hospitalar. Indique “Não” se a suspeita ou confirmação de infecção pelo patógeno de interesse não for o motivo (indicação) da admissão hospitalar.', NULL, 'Machine Translation', false),
	(67677, '2026-03-18 11:00:35.939913+00', 91378, 'spanish', 'Indique «Sí» si se sospecha o se confirma la infección por el patógeno de interés si es el motivo (indicación) del ingreso hospitalario. Indique «No» si la infección sospechada o confirmada por el patógeno de interés no es el motivo (indicación) del ingreso hospitalario.', NULL, 'Machine Translation', false),
