	(68894, '2026-03-18 11:00:35.939913+00', 91823, 'portuguese', 'Estágio 1', NULL, 'Machine Translation', false),
	(68895, '2026-03-18 11:00:35.939913+00', 91823, 'spanish', 'Estadio 1', NULL, 'Machine Translation', false),
