	(68962, '2026-03-18 11:00:35.939913+00', 91846, 'french', 'Si séropositif : charge virale détectable', NULL, 'Machine Translation', false),
	(68963, '2026-03-18 11:00:35.939913+00', 91846, 'portuguese', 'Se HIV positivo: a carga viral do HIV é detectável', NULL, 'Machine Translation', false),
	(68964, '2026-03-18 11:00:35.939913+00', 91846, 'spanish', 'Si es VIH positivo: ¿es detectable la carga viral del VIH?', NULL, 'Machine Translation', false),
	(68965, '2026-03-18 11:00:35.939913+00', 91847, 'french', 'Le terme « détectable » inclut généralement les cas supprimés (détectés mais <= 1000 copies/mL) et non supprimés (>1000 copies/mL). Le terme « indétectable » désigne une charge virale non détectée par le test utilisé.', NULL, 'Machine Translation', false),
	(68966, '2026-03-18 11:00:35.939913+00', 91847, 'portuguese', 'Detectável normalmente inclui suprimido (detectado, mas <= 1000 cópias/mL) e não suprimido (>1000 cópias/mL). Indetectável refere-se à carga viral não detectada pelo teste utilizado.', NULL, 'Machine Translation', false),
	(68967, '2026-03-18 11:00:35.939913+00', 91847, 'spanish', 'Detectable suele incluir suprimido (detectado pero <= 1000 copias/ml) y no suprimido (>1000 copias/ml). Indetectable se refiere a la carga viral no detectada por la prueba utilizada.', NULL, 'Machine Translation', false),
	(68968, '2026-03-18 11:00:35.939913+00', 91848, 'french', 'Indiquez « Oui » si détectable (y compris supprimé (détecté mais <= 1000 copies/mL) et non supprimé (>1000 copies/mL)). Indiquez « Non » si indétectable (charge virale non détectée par le test utilisé).', NULL, 'Machine Translation', false),
	(68969, '2026-03-18 11:00:35.939913+00', 91848, 'portuguese', 'Indique “Sim” se detectável (inclui: suprimido (detectado, mas <= 1000 cópias/mL) e não suprimido (>1000 cópias/mL)). Indique “Não” se indetectável (carga viral não detectada pelo teste utilizado).', NULL, 'Machine Translation', false),
	(68970, '2026-03-18 11:00:35.939913+00', 91848, 'spanish', 'Indique «Sí» si es detectable (incluye: suprimido (detectado pero <= 1000 copias/ml) y no suprimido (>1000 copias/ml)). Indique «No» si es indetectable (carga viral no detectada por la prueba utilizada).', NULL, 'Machine Translation', false),
