	(69014, '2026-03-18 11:00:35.939913+00', 91864, 'portuguese', 'Infecção crônica por hepatite B/C', NULL, 'Machine Translation', false),
	(69015, '2026-03-18 11:00:35.939913+00', 91864, 'spanish', 'Infección crónica por hepatitis B/C', NULL, 'Machine Translation', false),
	(69016, '2026-03-18 11:00:35.939913+00', 91865, 'french', 'Définie comme une hépatite chronique due à une infection par le virus de l''hépatite B (VHB) ou de l''hépatite C (VHC). N''inclut pas les personnes dont la guérison de l''hépatite C est documentée.', NULL, 'Machine Translation', false),
	(69017, '2026-03-18 11:00:35.939913+00', 91865, 'portuguese', 'Definida como hepatite crônica devido à infecção pelo vírus da hepatite B (HBV) ou hepatite C (HCV). Não inclui aqueles com cura documentada da hepatite C.', NULL, 'Machine Translation', false),
	(69018, '2026-03-18 11:00:35.939913+00', 91865, 'spanish', 'Se define como hepatitis crónica debida a la infección por el virus de la hepatitis B (VHB) o el virus de la hepatitis C (VHC). No se incluyen los casos con curación documentada de la hepatitis C.', NULL, 'Machine Translation', false),
