	(69712, '2026-03-18 11:00:35.939913+00', 92122, 'french', 'Précisez autre raison', NULL, 'Machine Translation', false),
	(69713, '2026-03-18 11:00:35.939913+00', 92122, 'portuguese', 'Especifique outro motivo', NULL, 'Machine Translation', false),
