	(70368, '2026-03-18 11:00:35.939913+00', 92352, 'spanish', 'Fecha más reciente de vacunación contra la varicela', NULL, 'Machine Translation', false),
	(70369, '2026-03-18 11:00:35.939913+00', 92353, 'french', 'Il s''agit de la date du dernier vaccin contre le virus varicelle-zona.', NULL, 'Machine Translation', false),
	(70370, '2026-03-18 11:00:35.939913+00', 92353, 'portuguese', 'Refere-se à data da vacina mais recente contra o vírus varicela-zoster.', NULL, 'Machine Translation', false),
	(70371, '2026-03-18 11:00:35.939913+00', 92353, 'spanish', 'Se refiere a la fecha de la vacuna más reciente contra el virus varicela-zóster.', NULL, 'Machine Translation', false),
	(70464, '2026-03-18 11:00:35.939913+00', 92392, 'spanish', 'Dolores musculares / mialgia', NULL, 'Machine Translation', false),
	(70372, '2026-03-18 11:00:35.939913+00', 92354, 'french', 'Indiquez la date du dernier vaccin contre la varicelle au format JJ/MM/AAAA. Si vous ne connaissez pas la date exacte, estimez-la.  ', NULL, 'Machine Translation', false),
	(70373, '2026-03-18 11:00:35.939913+00', 92354, 'portuguese', 'Escreva a data da vacina mais recente contra varicela no formato DD/MM/AAAA. Se a data exata for desconhecida, faça uma estimativa.  ', NULL, 'Machine Translation', false),
	(70374, '2026-03-18 11:00:35.939913+00', 92354, 'spanish', 'Escriba la fecha de la última vacuna contra la varicela en el formato DD/MM/AAAA. Si no conoce la fecha exacta, haga una estimación.  ', NULL, 'Machine Translation', false),
	(70375, '2026-03-18 11:00:35.939913+00', 92355, 'french', 'SYMPTÔMES À L''ADMISSION : Indiquez si vous avez présenté ces symptômes à tout moment entre le début de la maladie et le jour de la consultation.', NULL, 'Machine Translation', false),
	(70376, '2026-03-18 11:00:35.939913+00', 92355, 'portuguese', 'SINTOMAS NA ADMISSÃO: Indique se apresentados em qualquer momento desde o início da doença até o dia da apresentação.', NULL, 'Machine Translation', false),
	(70377, '2026-03-18 11:00:35.939913+00', 92355, 'spanish', 'SÍNTOMAS AL INGRESO: Indicar si se experimentaron desde el inicio de la enfermedad hasta el día de la presentación', NULL, 'Machine Translation', false),
	(70378, '2026-03-18 11:00:35.939913+00', 92356, 'french', 'Symptômes systémiques / généraux', NULL, 'Machine Translation', false),
	(70379, '2026-03-18 11:00:35.939913+00', 92356, 'portuguese', 'Sintomas sistêmicos/gerais', NULL, 'Machine Translation', false),
	(70380, '2026-03-18 11:00:35.939913+00', 92356, 'spanish', 'Síntomas sistémicos/generales', NULL, 'Machine Translation', false),
	(70381, '2026-03-18 11:00:35.939913+00', 92357, 'french', 'Il s''agit de signes et symptômes systémiques / généraux / non spécifiques.', NULL, 'Machine Translation', false),
	(70382, '2026-03-18 11:00:35.939913+00', 92357, 'portuguese', 'Refere-se a sinais e sintomas sistêmicos/gerais/não específicos.', NULL, 'Machine Translation', false),
	(70383, '2026-03-18 11:00:35.939913+00', 92357, 'spanish', 'Se refiere a signos y síntomas sistémicos/generales/no específicos.', NULL, 'Machine Translation', false),
