	(70389, '2026-03-18 11:00:35.939913+00', 92361, 'spanish', 'Indique «Sí» si el paciente experimentó esto en cualquier momento durante la fecha de la evaluación.', NULL, 'Machine Translation', false),
	(70390, '2026-03-18 11:00:35.939913+00', 92362, 'french', 'Frissons ou rigide', NULL, 'Machine Translation', false),
