	(70482, '2026-03-18 11:00:35.939913+00', 92401, 'spanish', 'Lugar donde apareció la erupción por primera vez', NULL, 'Machine Translation', false),
	(70483, '2026-03-18 11:00:35.939913+00', 92403, 'french', 'Sélectionnez la ou les options les plus appropriées correspondant à l''endroit où l''éruption cutanée est apparue pour la première fois.', NULL, 'Machine Translation', false),
	(70484, '2026-03-18 11:00:35.939913+00', 92403, 'portuguese', 'Selecione a(s) opção(ões) mais adequada(s) correspondente(s) ao local onde a erupção cutânea ocorreu pela primeira vez.', NULL, 'Machine Translation', false),
