	(70516, '2026-03-18 11:00:35.939913+00', 92416, 'french', 'Il s''agit des sensations cutanées perçues (par exemple, froid, chaleur, picotements, pression, etc.) qui apparaissent spontanément en l''absence de stimulation.', NULL, 'Machine Translation', false),
	(70517, '2026-03-18 11:00:35.939913+00', 92416, 'portuguese', 'Refere-se às sensações cutâneas percebidas (por exemplo, frio, calor, formigamento, pressão, etc.) que são experimentadas espontaneamente na ausência de estímulos.', NULL, 'Machine Translation', false),
	(70572, '2026-03-18 11:00:35.939913+00', 92445, 'spanish', 'Síntomas respiratorios', NULL, 'Machine Translation', false),
	(70518, '2026-03-18 11:00:35.939913+00', 92416, 'spanish', 'Se refiere a las sensaciones cutáneas percibidas (por ejemplo, frío, calor, hormigueo, presión, etc.) que se experimentan de forma espontánea en ausencia de estimulación.', NULL, 'Machine Translation', false),
	(70519, '2026-03-18 11:00:35.939913+00', 92418, 'french', 'Modifications de la texture de la peau', NULL, 'Machine Translation', false),
