	(70521, '2026-03-18 11:00:35.939913+00', 92418, 'spanish', 'Cambios en la textura de la piel', NULL, 'Machine Translation', false),
	(70522, '2026-03-18 11:00:35.939913+00', 92419, 'french', 'Il s''agit des modifications de l''aspect et du toucher de la peau, telles que la rugosité, l''irrégularité ou la présence de bosses.', NULL, 'Machine Translation', false),
	(70523, '2026-03-18 11:00:35.939913+00', 92419, 'portuguese', 'Refere-se a alterações na aparência e na sensação da superfície da pele, tais como aspereza, irregularidade ou presença de protuberâncias.', NULL, 'Machine Translation', false),
	(70524, '2026-03-18 11:00:35.939913+00', 92419, 'spanish', 'Se refiere a alteraciones en el aspecto y el tacto de la superficie de la piel, como rugosidad, irregularidad o presencia de protuberancias.', NULL, 'Machine Translation', false),
