	(70530, '2026-03-18 11:00:35.939913+00', 92422, 'spanish', 'Se refiere al aspecto pálido y antinatural de la piel.', NULL, 'Machine Translation', false),
	(70531, '2026-03-18 11:00:35.939913+00', 92424, 'french', 'Démangeaisons / prurit', NULL, 'Machine Translation', false),
