	(70562, '2026-03-18 11:00:35.939913+00', 92440, 'portuguese', 'Refere-se à sede excessiva.', NULL, 'Machine Translation', false),
	(70563, '2026-03-18 11:00:35.939913+00', 92440, 'spanish', 'Se refiere a la sed excesiva.', NULL, 'Machine Translation', false),
	(70564, '2026-03-18 11:00:35.939913+00', 92442, 'french', 'Modifications des règles (règles irrégulières)', NULL, 'Machine Translation', false),
	(70565, '2026-03-18 11:00:35.939913+00', 92442, 'portuguese', 'Alterações na menstruação (menstruação irregular)', NULL, 'Machine Translation', false),
	(70566, '2026-03-18 11:00:35.939913+00', 92442, 'spanish', 'Cambios en la menstruación (menstruación irregular)', NULL, 'Machine Translation', false),
	(70567, '2026-03-18 11:00:35.939913+00', 92443, 'french', 'Il s''agit de tout écart par rapport au processus normal, par exemple des saignements retardés, difficiles, abondants, peu abondants, inhabituels, etc.', NULL, 'Machine Translation', false),
	(70568, '2026-03-18 11:00:35.939913+00', 92443, 'portuguese', 'Refere-se a qualquer desvio do processo normal; por exemplo, atraso, dificuldade, profusão, escassez, sangramento incomum, etc.', NULL, 'Machine Translation', false),
	(70569, '2026-03-18 11:00:35.939913+00', 92443, 'spanish', 'Se refiere a cualquier desviación del proceso normal; por ejemplo, retraso, dificultad, profusión, escasez, sangrado inusual, etc.', NULL, 'Machine Translation', false),
	(70570, '2026-03-18 11:00:35.939913+00', 92445, 'french', 'Symptômes respiratoires', NULL, 'Machine Translation', false),
