	(70589, '2026-03-18 11:00:35.939913+00', 92454, 'portuguese', 'Não produtivo', NULL, 'Machine Translation', false),
	(70590, '2026-03-18 11:00:35.939913+00', 92454, 'spanish', 'No productiva', NULL, 'Machine Translation', false),
	(70591, '2026-03-18 11:00:35.939913+00', 92455, 'french', 'Productif', NULL, 'Machine Translation', false),
