	(70596, '2026-03-18 11:00:35.939913+00', 92456, 'spanish', 'Hemoptisis', NULL, 'Machine Translation', false),
	(70597, '2026-03-18 11:00:35.939913+00', 92457, 'french', 'Maux de gorge', NULL, 'Machine Translation', false),
	(70598, '2026-03-18 11:00:35.939913+00', 92457, 'portuguese', 'Dor de garganta', NULL, 'Machine Translation', false),
	(70599, '2026-03-18 11:00:35.939913+00', 92457, 'spanish', 'Dolor de garganta', NULL, 'Machine Translation', false),
	(70600, '2026-03-18 11:00:35.939913+00', 92458, 'french', 'Définie comme une sensation désagréable caractérisée par un inconfort physique (tel qu''une sensation de picotement, de pulsation ou de douleur) et perçue comme provenant de la gorge.', NULL, 'Machine Translation', false),
	(70601, '2026-03-18 11:00:35.939913+00', 92458, 'portuguese', 'Definida como uma sensação desagradável caracterizada por desconforto físico (como formigamento, latejamento ou dor) e percebida como originária da garganta.', NULL, 'Machine Translation', false),
	(70602, '2026-03-18 11:00:35.939913+00', 92458, 'spanish', 'Se define como una sensación desagradable caracterizada por malestar físico (como pinchazos, palpitaciones o dolor) y que se percibe como si se originara en la garganta.', NULL, 'Machine Translation', false),
	(70603, '2026-03-18 11:00:35.939913+00', 92460, 'french', 'Écoulement nasal / rhinorrhée', NULL, 'Machine Translation', false),
	(70604, '2026-03-18 11:00:35.939913+00', 92460, 'portuguese', 'Coriza / rinorreia', NULL, 'Machine Translation', false),
	(70605, '2026-03-18 11:00:35.939913+00', 92460, 'spanish', 'Secreción nasal / rinorrea', NULL, 'Machine Translation', false),
	(70606, '2026-03-18 11:00:35.939913+00', 92461, 'french', 'Définie comme une augmentation des sécrétions muqueuses du nez.', NULL, 'Machine Translation', false),
	(70607, '2026-03-18 11:00:35.939913+00', 92461, 'portuguese', 'Definida como aumento da secreção mucosa do nariz.', NULL, 'Machine Translation', false),
	(70608, '2026-03-18 11:00:35.939913+00', 92461, 'spanish', 'Se define como un aumento de la secreción mucosa de la nariz.', NULL, 'Machine Translation', false),
	(70609, '2026-03-18 11:00:35.939913+00', 92463, 'french', 'Respiration sifflante', NULL, 'Machine Translation', false),
	(70610, '2026-03-18 11:00:35.939913+00', 92463, 'portuguese', 'Sibilância', NULL, 'Machine Translation', false),
	(70611, '2026-03-18 11:00:35.939913+00', 92463, 'spanish', 'Sibilancias', NULL, 'Machine Translation', false),
	(70612, '2026-03-18 11:00:35.939913+00', 92464, 'french', 'Définie comme un bruit respiratoire aigu résultant d''un rétrécissement ou d''une obstruction des petites voies respiratoires.', NULL, 'Machine Translation', false),
	(70613, '2026-03-18 11:00:35.939913+00', 92464, 'portuguese', 'Definida como um som respiratório agudo resultante do estreitamento ou obstrução das vias aéreas pequenas.', NULL, 'Machine Translation', false),
	(70614, '2026-03-18 11:00:35.939913+00', 92464, 'spanish', 'Se define como un sonido respiratorio agudo que resulta de un estrechamiento u obstrucción de las vías respiratorias pequeñas.', NULL, 'Machine Translation', false),
	(70615, '2026-03-18 11:00:35.939913+00', 92466, 'french', 'Essoufflement', NULL, 'Machine Translation', false),
	(70616, '2026-03-18 11:00:35.939913+00', 92466, 'portuguese', 'Falta de ar', NULL, 'Machine Translation', false),
	(70617, '2026-03-18 11:00:35.939913+00', 92466, 'spanish', 'Dificultad para respirar', NULL, 'Machine Translation', false),
	(70618, '2026-03-18 11:00:35.939913+00', 92467, 'french', 'Définie comme la sensation désagréable d''une respiration difficile ou laborieuse, disproportionnée par rapport au niveau d''activité physique du patient.', NULL, 'Machine Translation', false),
	(70619, '2026-03-18 11:00:35.939913+00', 92467, 'portuguese', 'Definida como a sensação desconfortável de respiração difícil ou ofegante, desproporcional ao nível de atividade física do paciente.', NULL, 'Machine Translation', false),
	(70620, '2026-03-18 11:00:35.939913+00', 92467, 'spanish', 'Se define como la sensación incómoda de dificultad o esfuerzo al respirar, desproporcionada con respecto al nivel de actividad física del paciente.', NULL, 'Machine Translation', false),
	(70621, '2026-03-18 11:00:35.939913+00', 92469, 'french', 'Congestion nasale', NULL, 'Machine Translation', false),
	(70622, '2026-03-18 11:00:35.939913+00', 92469, 'portuguese', 'Congestão nasal', NULL, 'Machine Translation', false),
	(70623, '2026-03-18 11:00:35.939913+00', 92469, 'spanish', 'Congestión nasal', NULL, 'Machine Translation', false),
	(70624, '2026-03-18 11:00:35.939913+00', 92472, 'french', 'Douleur thoracique', NULL, 'Machine Translation', false),
	(70625, '2026-03-18 11:00:35.939913+00', 92472, 'portuguese', 'Dor no peito', NULL, 'Machine Translation', false),
	(70626, '2026-03-18 11:00:35.939913+00', 92472, 'spanish', 'Dolor en el pecho', NULL, 'Machine Translation', false),
	(70627, '2026-03-18 11:00:35.939913+00', 92473, 'french', 'Définie comme une sensation désagréable, inconfortable ou douloureuse caractérisée par un inconfort physique localisé dans la poitrine.', NULL, 'Machine Translation', false),
	(70628, '2026-03-18 11:00:35.939913+00', 92473, 'portuguese', 'Definida como a sensação desagradável, desconfortável ou dolorosa caracterizada por desconforto físico localizado no peito.', NULL, 'Machine Translation', false),
	(70629, '2026-03-18 11:00:35.939913+00', 92473, 'spanish', 'Se define como la sensación desagradable, incómoda o dolorosa caracterizada por malestar físico localizado en el pecho.', NULL, 'Machine Translation', false),
	(70630, '2026-03-18 11:00:35.939913+00', 92475, 'french', 'Éternuements', NULL, 'Machine Translation', false),
	(70631, '2026-03-18 11:00:35.939913+00', 92475, 'portuguese', 'Espirros', NULL, 'Machine Translation', false),
	(70632, '2026-03-18 11:00:35.939913+00', 92475, 'spanish', 'Estornudos', NULL, 'Machine Translation', false),
	(70633, '2026-03-18 11:00:35.939913+00', 92476, 'french', 'Il s''agit d''une expiration soudaine, violente, spasmodique et audible par le nez et la bouche.', NULL, 'Machine Translation', false),
	(70634, '2026-03-18 11:00:35.939913+00', 92476, 'portuguese', 'Refere-se a uma expiração repentina, violenta, espasmódica e audível pela nariz e boca.', NULL, 'Machine Translation', false),
	(70635, '2026-03-18 11:00:35.939913+00', 92476, 'spanish', 'Se refiere a una exhalación repentina, violenta, espasmódica y audible por la nariz y la boca.', NULL, 'Machine Translation', false),
	(70636, '2026-03-18 11:00:35.939913+00', 92478, 'french', 'Symptômes cardiovasculaires', NULL, 'Machine Translation', false),
	(70637, '2026-03-18 11:00:35.939913+00', 92478, 'portuguese', 'Sintomas cardiovasculares', NULL, 'Machine Translation', false),
	(70638, '2026-03-18 11:00:35.939913+00', 92478, 'spanish', 'Síntomas cardiovasculares', NULL, 'Machine Translation', false),
	(70639, '2026-03-18 11:00:35.939913+00', 92479, 'french', 'Ce terme désigne les signes et symptômes liés au système cardiovasculaire.', NULL, 'Machine Translation', false),
	(70640, '2026-03-18 11:00:35.939913+00', 92479, 'portuguese', 'Refere-se a sinais e sintomas relacionados com o sistema cardiovascular.', NULL, 'Machine Translation', false),
	(70641, '2026-03-18 11:00:35.939913+00', 92479, 'spanish', 'Se refiere a los signos y síntomas relacionados con el sistema cardiovascular.', NULL, 'Machine Translation', false),
	(70642, '2026-03-18 11:00:35.939913+00', 92481, 'french', 'Palpitations', NULL, 'Machine Translation', false),
	(70643, '2026-03-18 11:00:35.939913+00', 92481, 'portuguese', 'Palpitações', NULL, 'Machine Translation', false),
	(70644, '2026-03-18 11:00:35.939913+00', 92481, 'spanish', 'Palpitaciones', NULL, 'Machine Translation', false),
	(70645, '2026-03-18 11:00:35.939913+00', 92482, 'french', 'Désigne la perception désagréable de ses propres battements cardiaques.', NULL, 'Machine Translation', false),
	(70646, '2026-03-18 11:00:35.939913+00', 92482, 'portuguese', 'Refere-se à sensação desagradável de perceber os próprios batimentos cardíacos.', NULL, 'Machine Translation', false),
	(70647, '2026-03-18 11:00:35.939913+00', 92482, 'spanish', 'Se refiere a la percepción desagradable de los latidos del propio corazón.', NULL, 'Machine Translation', false),
	(70648, '2026-03-18 11:00:35.939913+00', 92484, 'french', 'Symptômes gastro-intestinaux', NULL, 'Machine Translation', false),
	(70649, '2026-03-18 11:00:35.939913+00', 92484, 'portuguese', 'Sintomas gastrointestinais', NULL, 'Machine Translation', false),
	(70650, '2026-03-18 11:00:35.939913+00', 92484, 'spanish', 'Síntomas gastrointestinales', NULL, 'Machine Translation', false),
	(70651, '2026-03-18 11:00:35.939913+00', 92485, 'french', 'Il s''agit des signes et symptômes liés au système gastro-intestinal.', NULL, 'Machine Translation', false),
	(70652, '2026-03-18 11:00:35.939913+00', 92485, 'portuguese', 'Refere-se a sinais e sintomas relacionados ao sistema gastrointestinal.', NULL, 'Machine Translation', false),
	(70653, '2026-03-18 11:00:35.939913+00', 92485, 'spanish', 'Se refiere a los signos y síntomas relacionados con el sistema gastrointestinal.', NULL, 'Machine Translation', false),
	(70654, '2026-03-18 11:00:35.939913+00', 92487, 'french', 'Douleurs abdominales', NULL, 'Machine Translation', false),
	(70655, '2026-03-18 11:00:35.939913+00', 92487, 'portuguese', 'Dor abdominal', NULL, 'Machine Translation', false),
	(70656, '2026-03-18 11:00:35.939913+00', 92487, 'spanish', 'Dolor abdominal', NULL, 'Machine Translation', false),
	(70657, '2026-03-18 11:00:35.939913+00', 92488, 'french', 'Définie comme une sensation désagréable d''inconfort, de détresse ou d''agonie dans la région abdominale.', NULL, 'Machine Translation', false),
	(70658, '2026-03-18 11:00:35.939913+00', 92488, 'portuguese', 'Definido como uma sensação desagradável de desconforto, angústia ou agonia na região abdominal.', NULL, 'Machine Translation', false),
	(70659, '2026-03-18 11:00:35.939913+00', 92488, 'spanish', 'Se define como una sensación desagradable de malestar, angustia o agonía en la región abdominal.', NULL, 'Machine Translation', false),
	(70660, '2026-03-18 11:00:35.939913+00', 92490, 'french', 'Diarrhée', NULL, 'Machine Translation', false),
	(70661, '2026-03-18 11:00:35.939913+00', 92490, 'portuguese', 'Diarreia', NULL, 'Machine Translation', false),
	(70662, '2026-03-18 11:00:35.939913+00', 92490, 'spanish', 'Diarrea', NULL, 'Machine Translation', false),
	(70663, '2026-03-18 11:00:35.939913+00', 92491, 'french', 'Définie comme une augmentation anormale de la fréquence (généralement définie comme trois ou plus) des selles molles ou liquides par jour (ou plus fréquentes que la normale pour l''individu).', NULL, 'Machine Translation', false),
	(70664, '2026-03-18 11:00:35.939913+00', 92491, 'portuguese', 'Definido como aumento anormal da frequência (geralmente definido como três ou mais) de evacuações moles ou líquidas por dia (ou evacuações mais frequentes do que o normal para o indivíduo).', NULL, 'Machine Translation', false),
	(70665, '2026-03-18 11:00:35.939913+00', 92491, 'spanish', 'Se define como un aumento anormal de la frecuencia (normalmente definido como tres o más) de deposiciones blandas o líquidas al día (o más frecuentes de lo normal para la persona).', NULL, 'Machine Translation', false),
	(70666, '2026-03-18 11:00:35.939913+00', 92493, 'french', 'Constipation', NULL, 'Machine Translation', false),
	(70667, '2026-03-18 11:00:35.939913+00', 92493, 'portuguese', 'Constipação', NULL, 'Machine Translation', false),
	(70668, '2026-03-18 11:00:35.939913+00', 92493, 'spanish', 'Estreñimiento', NULL, 'Machine Translation', false),
	(70669, '2026-03-18 11:00:35.939913+00', 92494, 'french', 'Définie comme une évacuation irrégulière et peu fréquente ou difficile des selles.', NULL, 'Machine Translation', false),
	(70670, '2026-03-18 11:00:35.939913+00', 92494, 'portuguese', 'Definido como evacuação irregular e pouco frequente ou difícil dos intestinos.', NULL, 'Machine Translation', false),
	(70671, '2026-03-18 11:00:35.939913+00', 92494, 'spanish', 'Se define como la evacuación irregular y poco frecuente o difícil de los intestinos.', NULL, 'Machine Translation', false),
	(70672, '2026-03-18 11:00:35.939913+00', 92496, 'french', 'Vomissements', NULL, 'Machine Translation', false),
	(70673, '2026-03-18 11:00:35.939913+00', 92496, 'portuguese', 'Vômito', NULL, 'Machine Translation', false),
	(70674, '2026-03-18 11:00:35.939913+00', 92496, 'spanish', 'Vómitos', NULL, 'Machine Translation', false),
	(70675, '2026-03-18 11:00:35.939913+00', 92497, 'french', 'Définie comme l''expulsion du contenu de l''estomac ou de l''intestin grêle par la bouche.', NULL, 'Machine Translation', false),
	(70676, '2026-03-18 11:00:35.939913+00', 92497, 'portuguese', 'Definido como a expulsão do estômago ou do intestino delgado pela boca.', NULL, 'Machine Translation', false),
	(70677, '2026-03-18 11:00:35.939913+00', 92497, 'spanish', 'Se define como la expulsión del estómago o del intestino delgado a través de la boca.', NULL, 'Machine Translation', false),
	(70678, '2026-03-18 11:00:35.939913+00', 92499, 'french', 'Vomissements persistants ? (>=2/jour)', NULL, 'Machine Translation', false),
	(70679, '2026-03-18 11:00:35.939913+00', 92499, 'portuguese', 'Vômito persistente? (>=2/dia)', NULL, 'Machine Translation', false),
	(70680, '2026-03-18 11:00:35.939913+00', 92499, 'spanish', '¿Vómitos persistentes? (>=2/día)', NULL, 'Machine Translation', false),
	(70681, '2026-03-18 11:00:35.939913+00', 92500, 'french', 'Désigne des vomissements persistants, définis ici comme deux vomissements ou plus par jour.', NULL, 'Machine Translation', false),
	(70682, '2026-03-18 11:00:35.939913+00', 92500, 'portuguese', 'Refere-se ao vômito persistente, definido aqui como vômito duas ou mais vezes por dia.', NULL, 'Machine Translation', false),
	(70683, '2026-03-18 11:00:35.939913+00', 92500, 'spanish', 'Se refiere al vómito persistente, definido aquí como dos o más vómitos al día.', NULL, 'Machine Translation', false),
	(70684, '2026-03-18 11:00:35.939913+00', 92502, 'french', 'Hématémèse (vomissements de sang)', NULL, 'Machine Translation', false),
	(70685, '2026-03-18 11:00:35.939913+00', 92502, 'portuguese', 'Hematêmese (vômito com sangue)', NULL, 'Machine Translation', false),
	(70686, '2026-03-18 11:00:35.939913+00', 92502, 'spanish', 'Hematemesis (vómitos con sangre)', NULL, 'Machine Translation', false),
	(70687, '2026-03-18 11:00:35.939913+00', 92503, 'french', 'Désigne le vomissement de sang.', NULL, 'Machine Translation', false),
	(70688, '2026-03-18 11:00:35.939913+00', 92503, 'portuguese', 'Refere-se ao vômito com sangue.', NULL, 'Machine Translation', false),
	(70689, '2026-03-18 11:00:35.939913+00', 92503, 'spanish', 'Se refiere al vómito con sangre.', NULL, 'Machine Translation', false),
	(70690, '2026-03-18 11:00:35.939913+00', 92505, 'french', 'Nausées', NULL, 'Machine Translation', false),
	(70691, '2026-03-18 11:00:35.939913+00', 92505, 'portuguese', 'Náusea', NULL, 'Machine Translation', false),
	(70692, '2026-03-18 11:00:35.939913+00', 92505, 'spanish', 'Náuseas', NULL, 'Machine Translation', false),
	(70693, '2026-03-18 11:00:35.939913+00', 92506, 'french', 'Définie comme la sensation subjective désagréable et indolore que l''on va vomir immédiatement.', NULL, 'Machine Translation', false),
	(70694, '2026-03-18 11:00:35.939913+00', 92506, 'portuguese', 'Definido como a sensação subjetiva desagradável e indolor de que se vai vomitar em breve.', NULL, 'Machine Translation', false),
	(70695, '2026-03-18 11:00:35.939913+00', 92506, 'spanish', 'Se define como la sensación subjetiva desagradable e indolora de que se va a vomitar de forma inminente.', NULL, 'Machine Translation', false),
	(70696, '2026-03-18 11:00:35.939913+00', 92508, 'french', 'Anorexie', NULL, 'Machine Translation', false),
	(70697, '2026-03-18 11:00:35.939913+00', 92508, 'portuguese', 'Anorexia', NULL, 'Machine Translation', false),
	(70698, '2026-03-18 11:00:35.939913+00', 92508, 'spanish', 'Anorexia', NULL, 'Machine Translation', false),
	(70699, '2026-03-18 11:00:35.939913+00', 92509, 'french', 'Définie comme l''absence ou la perte d''appétit.', NULL, 'Machine Translation', false),
	(70700, '2026-03-18 11:00:35.939913+00', 92509, 'portuguese', 'Definido como falta ou perda de apetite.', NULL, 'Machine Translation', false),
	(70701, '2026-03-18 11:00:35.939913+00', 92509, 'spanish', 'Se define como la falta o pérdida de apetito.', NULL, 'Machine Translation', false),
	(70702, '2026-03-18 11:00:35.939913+00', 92511, 'french', 'Salivation excessive', NULL, 'Machine Translation', false),
	(70703, '2026-03-18 11:00:35.939913+00', 92511, 'portuguese', 'Salivação excessiva', NULL, 'Machine Translation', false),
	(70704, '2026-03-18 11:00:35.939913+00', 92511, 'spanish', 'Salivación excesiva', NULL, 'Machine Translation', false),
	(70705, '2026-03-18 11:00:35.939913+00', 92512, 'french', 'Définie comme une salivation excessive ou une sialorrhée, ce symptôme est mieux évalué par le patient lui-même.', NULL, 'Machine Translation', false),
	(70706, '2026-03-18 11:00:35.939913+00', 92512, 'portuguese', 'Definido como salivação excessiva ou sialorreia, é um sintoma melhor avaliado pelo paciente.', NULL, 'Machine Translation', false),
	(70707, '2026-03-18 11:00:35.939913+00', 92512, 'spanish', 'Se define como la salivación excesiva o sialorrea, es un síntoma que evalúa mejor el paciente.', NULL, 'Machine Translation', false),
	(70708, '2026-03-18 11:00:35.939913+00', 92514, 'french', 'Difficultés à avaler (dysphagie)', NULL, 'Machine Translation', false),
	(70709, '2026-03-18 11:00:35.939913+00', 92514, 'portuguese', 'Dificuldade para engolir (disfagia)', NULL, 'Machine Translation', false),
	(70710, '2026-03-18 11:00:35.939913+00', 92514, 'spanish', 'Dificultad para tragar (disfagia)', NULL, 'Machine Translation', false),
	(70711, '2026-03-18 11:00:35.939913+00', 92515, 'french', 'Définie comme une difficulté à avaler des aliments, des liquides ou de la salive.', NULL, 'Machine Translation', false),
	(70712, '2026-03-18 11:00:35.939913+00', 92515, 'portuguese', 'Definido como dificuldade em engolir alimentos, líquidos ou saliva.', NULL, 'Machine Translation', false),
	(70713, '2026-03-18 11:00:35.939913+00', 92515, 'spanish', 'Definido como dificultad para tragar alimentos, líquidos o saliva.', NULL, 'Machine Translation', false),
	(70714, '2026-03-18 11:00:35.939913+00', 92517, 'french', 'Incontinence fécale', NULL, 'Machine Translation', false),
	(70715, '2026-03-18 11:00:35.939913+00', 92517, 'portuguese', 'Incontinência fecal', NULL, 'Machine Translation', false),
	(70716, '2026-03-18 11:00:35.939913+00', 92517, 'spanish', 'Incontinencia fecal', NULL, 'Machine Translation', false),
	(70717, '2026-03-18 11:00:35.939913+00', 92518, 'french', 'Définie comme l''incapacité à contrôler volontairement les sphincters anaux, avec passage involontaire de selles et de flatulences.', NULL, 'Machine Translation', false),
	(70718, '2026-03-18 11:00:35.939913+00', 92518, 'portuguese', 'Definido como falha no controle voluntário dos esfíncteres anais, com passagem involuntária de fezes e gases.', NULL, 'Machine Translation', false),
	(70719, '2026-03-18 11:00:35.939913+00', 92518, 'spanish', 'Definido como la incapacidad de controlar voluntariamente los esfínteres anales, con paso involuntario de heces y gases.', NULL, 'Machine Translation', false),
