	(70722, '2026-03-18 11:00:35.939913+00', 92520, 'spanish', 'Síntomas renales/genitourinarios', NULL, 'Machine Translation', false),
	(70723, '2026-03-18 11:00:35.939913+00', 92521, 'french', 'Il s''agit des signes et symptômes liés au système rénal/génito-urinaire.', NULL, 'Machine Translation', false),
	(70724, '2026-03-18 11:00:35.939913+00', 92521, 'portuguese', 'Refere-se a sinais e sintomas relacionados ao sistema renal/geniturinário.', NULL, 'Machine Translation', false),
	(70725, '2026-03-18 11:00:35.939913+00', 92521, 'spanish', 'Se refiere a los signos y síntomas relacionados con el sistema renal/genitourinario.', NULL, 'Machine Translation', false),
	(70726, '2026-03-18 11:00:35.939913+00', 92523, 'french', 'Rétention urinaire', NULL, 'Machine Translation', false),
	(70727, '2026-03-18 11:00:35.939913+00', 92523, 'portuguese', 'Retenção urinária', NULL, 'Machine Translation', false),
	(70728, '2026-03-18 11:00:35.939913+00', 92523, 'spanish', 'Retención urinaria', NULL, 'Machine Translation', false),
	(70729, '2026-03-18 11:00:35.939913+00', 92524, 'french', 'Définie comme l''accumulation d''urine dans la vessie en raison de l''incapacité d''uriner.', NULL, 'Machine Translation', false),
	(70730, '2026-03-18 11:00:35.939913+00', 92524, 'portuguese', 'Definida como o acúmulo de urina na bexiga devido à incapacidade de urinar.', NULL, 'Machine Translation', false),
	(70731, '2026-03-18 11:00:35.939913+00', 92524, 'spanish', 'Se define como la acumulación de orina en la vejiga debido a la incapacidad de orinar.', NULL, 'Machine Translation', false),
