	(70734, '2026-03-18 11:00:35.939913+00', 92526, 'spanish', 'Incontinencia urinaria', NULL, 'Machine Translation', false),
	(70735, '2026-03-18 11:00:35.939913+00', 92529, 'french', 'Augmentation de la miction (polyurie)', NULL, 'Machine Translation', false),
