	(70859, '2026-03-18 11:00:35.939913+00', 92589, 'portuguese', 'Olhos vermelhos/rosados', NULL, 'Machine Translation', false),
	(70860, '2026-03-18 11:00:35.939913+00', 92589, 'spanish', 'Ojos rojos/rosados', NULL, 'Machine Translation', false),
	(70861, '2026-03-18 11:00:35.939913+00', 92590, 'french', 'Défini comme une inflammation ou une infection de la conjonctive, caractérisée par une rougeur dans un œil ou les deux yeux.', NULL, 'Machine Translation', false),
	(70862, '2026-03-18 11:00:35.939913+00', 92590, 'portuguese', 'Definido como inflamação ou infecção da conjuntiva, caracterizada por vermelhidão em um ou ambos os olhos.', NULL, 'Machine Translation', false),
	(70863, '2026-03-18 11:00:35.939913+00', 92590, 'spanish', 'Se define como inflamación o infección de la conjuntiva, caracterizada por enrojecimiento en uno o ambos ojos.', NULL, 'Machine Translation', false),
	(70864, '2026-03-18 11:00:35.939913+00', 92592, 'french', 'Douleurs oculaires', NULL, 'Machine Translation', false),
	(70865, '2026-03-18 11:00:35.939913+00', 92592, 'portuguese', 'Dor nos olhos', NULL, 'Machine Translation', false),
	(70866, '2026-03-18 11:00:35.939913+00', 92592, 'spanish', 'Dolor en los ojos', NULL, 'Machine Translation', false),
	(70867, '2026-03-18 11:00:35.939913+00', 92593, 'french', 'Défini comme une gêne ou une douleur localisée dans ou autour de la région de l''œil.', NULL, 'Machine Translation', false),
	(70868, '2026-03-18 11:00:35.939913+00', 92593, 'portuguese', 'Definido como desconforto ou dor localizada dentro ou ao redor da área dos olhos.', NULL, 'Machine Translation', false),
	(70869, '2026-03-18 11:00:35.939913+00', 92593, 'spanish', 'Se define como malestar o dolor localizado en el área del ojo o alrededor de él.', NULL, 'Machine Translation', false),
	(70870, '2026-03-18 11:00:35.939913+00', 92595, 'french', 'Œdème des paupières', NULL, 'Machine Translation', false),
	(70871, '2026-03-18 11:00:35.939913+00', 92595, 'portuguese', 'Edema das pálpebras', NULL, 'Machine Translation', false),
	(70872, '2026-03-18 11:00:35.939913+00', 92595, 'spanish', 'Edema en los párpados', NULL, 'Machine Translation', false),
	(70873, '2026-03-18 11:00:35.939913+00', 92596, 'french', 'Défini comme un gonflement dû à une accumulation de liquide dans les tissus de la paupière.', NULL, 'Machine Translation', false),
	(70874, '2026-03-18 11:00:35.939913+00', 92596, 'portuguese', 'Definido como inchaço devido ao acúmulo de líquido nos tecidos da pálpebra.', NULL, 'Machine Translation', false),
	(70875, '2026-03-18 11:00:35.939913+00', 92596, 'spanish', 'Se define como la hinchazón debida a la acumulación de líquido en los tejidos del párpado.', NULL, 'Machine Translation', false),
