	(70878, '2026-03-18 11:00:35.939913+00', 92598, 'spanish', 'Secreción ocular', NULL, 'Machine Translation', false),
	(70879, '2026-03-18 11:00:35.939913+00', 92599, 'french', 'Défini comme l''écoulement d''un liquide clair à purulent provenant de l''œil, souvent indicatif d''une infection ou d''une irritation.', NULL, 'Machine Translation', false),
	(70880, '2026-03-18 11:00:35.939913+00', 92599, 'portuguese', 'Definido como a liberação de fluidos que variam de transparentes a semelhantes a pus do olho, frequentemente indicativo de infecção ou irritação.', NULL, 'Machine Translation', false),
	(70881, '2026-03-18 11:00:35.939913+00', 92599, 'spanish', 'Se define como la secreción de líquidos que van desde transparentes hasta purulentos por el ojo, a menudo indicativa de infección o irritación.', NULL, 'Machine Translation', false),
