	(70883, '2026-03-18 11:00:35.939913+00', 92601, 'portuguese', 'Visão turva/embaçada', NULL, 'Machine Translation', false),
	(70884, '2026-03-18 11:00:35.939913+00', 92601, 'spanish', 'Visión borrosa/nublada', NULL, 'Machine Translation', false),
	(70885, '2026-03-18 11:00:35.939913+00', 92602, 'french', 'Défini comme une perte d''acuité visuelle entraînant une vision floue ou déformée.', NULL, 'Machine Translation', false),
	(70886, '2026-03-18 11:00:35.939913+00', 92602, 'portuguese', 'Definido como perda da acuidade visual, resultando em visão turva ou distorcida.', NULL, 'Machine Translation', false),
	(70887, '2026-03-18 11:00:35.939913+00', 92602, 'spanish', 'Se define como la pérdida de agudeza visual, que da lugar a una visión borrosa o distorsionada.', NULL, 'Machine Translation', false),
	(70888, '2026-03-18 11:00:35.939913+00', 92604, 'french', 'Sensibilité des yeux à la lumière', NULL, 'Machine Translation', false),
	(70889, '2026-03-18 11:00:35.939913+00', 92604, 'portuguese', 'Sensibilidade dos olhos à luz', NULL, 'Machine Translation', false),
	(70890, '2026-03-18 11:00:35.939913+00', 92604, 'spanish', 'Sensibilidad de los ojos a la luz', NULL, 'Machine Translation', false),
	(70891, '2026-03-18 11:00:35.939913+00', 92605, 'french', 'Défini comme une intolérance anormale à la lumière, provoquant une gêne ou une douleur dans les yeux lorsqu''ils sont exposés à une lumière vive.', NULL, 'Machine Translation', false),
	(70892, '2026-03-18 11:00:35.939913+00', 92605, 'portuguese', 'Definido como intolerância anormal à luz, causando desconforto ou dor nos olhos quando expostos à luz forte.', NULL, 'Machine Translation', false),
	(70893, '2026-03-18 11:00:35.939913+00', 92605, 'spanish', 'Se define como una intolerancia anómala a la luz, que provoca molestias o dolor en los ojos cuando se exponen a una luz intensa.', NULL, 'Machine Translation', false),
