	(70895, '2026-03-18 11:00:35.939913+00', 92607, 'portuguese', 'Distúrbios visuais', NULL, 'Machine Translation', false),
	(70896, '2026-03-18 11:00:35.939913+00', 92607, 'spanish', 'Alteración de la visión', NULL, 'Machine Translation', false),
	(70897, '2026-03-18 11:00:35.939913+00', 92608, 'french', 'Désigne une perturbation de la vision normale sans nécessairement affecter l''acuité visuelle.', NULL, 'Machine Translation', false),
	(70898, '2026-03-18 11:00:35.939913+00', 92608, 'portuguese', 'Refere-se a uma interferência na visão normal, sem necessariamente afetar a acuidade visual.', NULL, 'Machine Translation', false),
	(70899, '2026-03-18 11:00:35.939913+00', 92608, 'spanish', 'Se refiere a una interferencia en la visión normal sin que necesariamente afecte a la agudeza visual.', NULL, 'Machine Translation', false),
