	(71224, '2026-03-18 11:00:35.939913+00', 92760, 'french', 'Il s''agit de selles anormalement foncées et goudronneuses contenant du sang, généralement provenant d''un saignement gastro-intestinal.', NULL, 'Machine Translation', false),
	(71225, '2026-03-18 11:00:35.939913+00', 92760, 'portuguese', 'Refere-se a fezes anormalmente escuras e pegajosas contendo sangue, geralmente proveniente de sangramento gastrointestinal.', NULL, 'Machine Translation', false),
	(71226, '2026-03-18 11:00:35.939913+00', 92760, 'spanish', 'Se refiere a heces anormalmente oscuras y alquitranadas que contienen sangre, generalmente procedente de una hemorragia gastrointestinal.', NULL, 'Machine Translation', false),
	(71227, '2026-03-18 11:00:35.939913+00', 92762, 'french', 'Sang frais dans les selles (hématochézie)', NULL, 'Machine Translation', false),
	(71228, '2026-03-18 11:00:35.939913+00', 92762, 'portuguese', '1, Sim | 0, Não | 99, Desconhecido', NULL, 'Machine Translation', false),
	(71229, '2026-03-18 11:00:35.939913+00', 92762, 'spanish', 'Sangre fresca en las heces (hematochezia)', NULL, 'Machine Translation', false),
	(71230, '2026-03-18 11:00:35.939913+00', 92763, 'french', 'Il s''agit de la présence de sang dans les selles. Il résulte d''une hémorragie gastro-intestinale et peut être facilement observé dans les selles ou identifié au microscope.', NULL, 'Machine Translation', false),
	(71231, '2026-03-18 11:00:35.939913+00', 92763, 'portuguese', 'Refere-se à presença de sangue nas fezes. É o resultado de hemorragia gastrointestinal e pode ser facilmente observado nas fezes ou identificado microscopicamente.', NULL, 'Machine Translation', false),
	(71232, '2026-03-18 11:00:35.939913+00', 92763, 'spanish', 'Se refiere a la presencia de sangre en las heces. Es el resultado de una hemorragia gastrointestinal y puede verse fácilmente en las heces o identificarse microscópicamente.', NULL, 'Machine Translation', false),
	(71233, '2026-03-18 11:00:35.939913+00', 92765, 'french', 'Saignement rectal', NULL, 'Machine Translation', false),
