	(71240, '2026-03-18 11:00:35.939913+00', 92768, 'portuguese', '1, Sim | 0, Não | 99, Desconhecido', NULL, 'Machine Translation', false),
	(71241, '2026-03-18 11:00:35.939913+00', 92768, 'spanish', 'Disminución de la diuresis', NULL, 'Machine Translation', false),
	(71242, '2026-03-18 11:00:35.939913+00', 92769, 'french', 'Il s''agit d''un résultat indiquant que la production d''urine est inférieure à 500 millilitres sur une période de 24 heures.', NULL, 'Machine Translation', false),
	(71243, '2026-03-18 11:00:35.939913+00', 92769, 'portuguese', 'Refere-se a um achado que indica que a produção de urina é inferior a 500 mililitros durante um período de 24 horas.', NULL, 'Machine Translation', false),
	(71244, '2026-03-18 11:00:35.939913+00', 92769, 'spanish', 'Se refiere a un hallazgo que indica que la producción de orina es inferior a 500 mililitros durante un período de 24 horas.', NULL, 'Machine Translation', false),
	(71245, '2026-03-18 11:00:35.939913+00', 92771, 'french', 'Signes hématologiques', NULL, 'Machine Translation', false),
