	(71316, '2026-03-18 11:00:35.939913+00', 92808, 'spanish', 'Se refiere a los signos y síntomas relacionados con los ojos.', NULL, 'Machine Translation', false),
	(71317, '2026-03-18 11:00:35.939913+00', 92809, 'french', 'Indiquez « Oui » si le patient a présenté ce symptôme entre 00 h 00 et 24 h 00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(71318, '2026-03-18 11:00:35.939913+00', 92809, 'portuguese', 'Indique “Sim” se o paciente tiver apresentado esse sintoma entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
