	(71327, '2026-03-18 11:00:35.939913+00', 92813, 'portuguese', '1, Sim | 0, Não | 99, Desconhecido', NULL, 'Machine Translation', false),
	(71328, '2026-03-18 11:00:35.939913+00', 92813, 'spanish', 'Hemorragia subconjuntival', NULL, 'Machine Translation', false),
	(71329, '2026-03-18 11:00:35.939913+00', 92814, 'french', 'Défini comme une accumulation de sang sous la conjonctive, se présentant sous la forme d''une tache rouge vif ou sombre dans l''œil.', NULL, 'Machine Translation', false),
	(71330, '2026-03-18 11:00:35.939913+00', 92814, 'portuguese', 'Definida como a acumulação de sangue sob a conjuntiva, apresentando-se como uma mancha vermelha brilhante ou escura no olho.', NULL, 'Machine Translation', false),
	(71331, '2026-03-18 11:00:35.939913+00', 92814, 'spanish', 'Se define como la acumulación de sangre debajo de la conjuntiva, que se presenta como una mancha roja brillante u oscura en el ojo.', NULL, 'Machine Translation', false),
