	(71366, '2026-03-18 11:00:35.939913+00', 92832, 'portuguese', '1, Sim | 0, Não | 99, Desconhecido', NULL, 'Machine Translation', false),
	(71367, '2026-03-18 11:00:35.939913+00', 92832, 'spanish', 'Otros signos', NULL, 'Machine Translation', false),
	(71368, '2026-03-18 11:00:35.939913+00', 92833, 'french', 'Défini comme d''autres signes et symptômes, non spécifiés ci-dessus.', NULL, 'Machine Translation', false),
	(71369, '2026-03-18 11:00:35.939913+00', 92833, 'portuguese', 'Refere-se a outros sinais e sintomas, não especificados acima.', NULL, 'Machine Translation', false),
	(71370, '2026-03-18 11:00:35.939913+00', 92833, 'spanish', 'Se refiere a otros signos y síntomas, no especificados anteriormente.', NULL, 'Machine Translation', false),
