	(71725, '2026-03-18 11:00:35.939913+00', 92958, 'french', 'Saturation en oxygène avec apport supplémentaire en oxygène (%)', NULL, 'Machine Translation', false),
	(71726, '2026-03-18 11:00:35.939913+00', 92958, 'portuguese', 'Saturação de oxigênio com oxigênio suplementar (%)', NULL, 'Machine Translation', false),
	(71727, '2026-03-18 11:00:35.939913+00', 92958, 'spanish', 'Saturación de oxígeno con oxígeno suplementario (%)', NULL, 'Machine Translation', false),
	(71728, '2026-03-18 11:00:35.939913+00', 92959, 'french', 'Il s''agit de la saturation en oxygène, qui peut être mesurée par oxymétrie de pouls ou par analyse des gaz artériels. Elle est indépendante de la ventilation ou du besoin en oxygène supplémentaire.', NULL, 'Machine Translation', false),
	(71729, '2026-03-18 11:00:35.939913+00', 92959, 'portuguese', 'Refere-se à saturação de oxigênio, que pode ser medida por oximetria de pulso ou por análise de gases sanguíneos arteriais. É independente da ventilação ou da necessidade de oxigênio suplementar.', NULL, 'Machine Translation', false),
	(71730, '2026-03-18 11:00:35.939913+00', 92959, 'spanish', 'Se refiere a la saturación de oxígeno, que puede medirse mediante pulsioximetría o análisis de gases en sangre arterial. Es independiente de la ventilación o la necesidad de oxígeno suplementario.', NULL, 'Machine Translation', false),
	(71731, '2026-03-18 11:00:35.939913+00', 92960, 'french', 'Entrez le pourcentage de saturation en oxygène. Enregistrez la valeur la plus éloignée de la plage normale entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(71732, '2026-03-18 11:00:35.939913+00', 92960, 'portuguese', 'Insira a porcentagem de saturação de oxigênio. Registre o valor mais distante da faixa normal entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(71733, '2026-03-18 11:00:35.939913+00', 92960, 'spanish', 'Introduzca el porcentaje de saturación de oxígeno. Registre el valor más alejado del rango normal entre las 00:00 y las 24:00 del día de la evaluación.', NULL, 'Machine Translation', false),
	(71734, '2026-03-18 11:00:35.939913+00', 92961, 'french', 'Comment la saturation en oxygène avec apport supplémentaire en oxygène a-t-elle été mesurée ?', NULL, 'Machine Translation', false),
	(71735, '2026-03-18 11:00:35.939913+00', 92961, 'portuguese', 'Como foi medida a saturação de oxigênio com oxigênio suplementar?', NULL, 'Machine Translation', false),
