	(71868, '2026-03-18 11:00:35.939913+00', 93010, 'spanish', 'Se refiere a la sudoración nocturna que no está relacionada con la temperatura ambiental.', NULL, 'Machine Translation', false),
	(71869, '2026-03-18 11:00:35.939913+00', 93011, 'french', 'Indiquez « Oui » si le patient a présenté ce symptôme entre 00 h 00 et 24 h 00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(71870, '2026-03-18 11:00:35.939913+00', 93011, 'portuguese', 'Indique “Sim” se o paciente tiver apresentado esse sintoma entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(71871, '2026-03-18 11:00:35.939913+00', 93011, 'spanish', 'Indique «Sí» si el paciente ha experimentado esto entre las 00:00 y las 24:00 del día de la evaluación.', NULL, 'Machine Translation', false),
	(71872, '2026-03-18 11:00:35.939913+00', 93012, 'french', 'Sueurs froides', NULL, 'Machine Translation', false),
	(71873, '2026-03-18 11:00:35.939913+00', 93012, 'portuguese', 'Suores frios', NULL, 'Machine Translation', false),
