	(71932, '2026-03-18 11:00:35.939913+00', 93033, 'french', 'Vertiges / évanouissements', NULL, 'Machine Translation', false),
	(71933, '2026-03-18 11:00:35.939913+00', 93033, 'portuguese', 'Tontura/desmaio', NULL, 'Machine Translation', false),
	(71934, '2026-03-18 11:00:35.939913+00', 93033, 'spanish', 'Mareos / desmayos', NULL, 'Machine Translation', false),
	(71935, '2026-03-18 11:00:35.939913+00', 93034, 'french', 'Il s''agit de la sensation subjective de vertige ou d''étourdissement qui peut précéder un épisode de syncope ou une sensation d''instabilité, de rotation ou de balancement.', NULL, 'Machine Translation', false),
	(71936, '2026-03-18 11:00:35.939913+00', 93034, 'portuguese', 'Refere-se à sensação subjetiva de tontura ou vertigem que pode preceder um episódio de síncope ou uma sensação de instabilidade, giro ou balanço.', NULL, 'Machine Translation', false),
	(71937, '2026-03-18 11:00:35.939913+00', 93034, 'spanish', 'Se refiere a la sensación subjetiva de mareo o vértigo que puede preceder a un episodio de síncope o a una sensación de inestabilidad, giro o balanceo.', NULL, 'Machine Translation', false),
	(71938, '2026-03-18 11:00:35.939913+00', 93035, 'french', 'Indiquez « Oui » si le patient a présenté ce symptôme à tout moment au cours de la date d''évaluation.', NULL, 'Machine Translation', false),
