	(71944, '2026-03-18 11:00:35.939913+00', 93037, 'french', 'Définie comme une douleur localisée dans un muscle ou un groupe de muscles.', NULL, 'Machine Translation', false),
	(71945, '2026-03-18 11:00:35.939913+00', 93037, 'portuguese', 'Definida como dor localizada em um músculo ou grupo de músculos.', NULL, 'Machine Translation', false),
	(71946, '2026-03-18 11:00:35.939913+00', 93037, 'spanish', 'Se define como el dolor localizado en un músculo o grupo de músculos.', NULL, 'Machine Translation', false),
	(71947, '2026-03-18 11:00:35.939913+00', 93038, 'french', 'Indiquez « Oui » si le patient a présenté ce symptôme à tout moment au cours de la date d''évaluation.', NULL, 'Machine Translation', false),
