	(71977, '2026-03-18 11:00:35.939913+00', 93048, 'french', 'Modifications de la texture de la peau', NULL, 'Machine Translation', false),
	(71978, '2026-03-18 11:00:35.939913+00', 93048, 'portuguese', 'Alterações na textura da pele', NULL, 'Machine Translation', false),
