	(72891, '2026-03-18 11:00:35.939913+00', 93368, 'spanish', 'Sangre fresca en las heces (hematochezia)', NULL, 'Machine Translation', false),
	(72892, '2026-03-18 11:00:35.939913+00', 93369, 'french', 'Il s''agit de la présence de sang dans les selles. Il résulte d''une hémorragie gastro-intestinale et peut être facilement observé dans les selles ou identifié au microscope.', NULL, 'Machine Translation', false),
	(72893, '2026-03-18 11:00:35.939913+00', 93369, 'portuguese', 'Refere-se à presença de sangue nas fezes. É o resultado de hemorragia gastrointestinal e pode ser facilmente observado nas fezes ou identificado microscopicamente.', NULL, 'Machine Translation', false),
	(72894, '2026-03-18 11:00:35.939913+00', 93369, 'spanish', 'Se refiere a la presencia de sangre en las heces. Es el resultado de una hemorragia gastrointestinal y puede verse fácilmente en las heces o identificarse microscópicamente.', NULL, 'Machine Translation', false),
