	(73138, '2026-03-18 11:00:35.939913+00', 93460, 'french', 'Lésions semi-confluentes', NULL, 'Machine Translation', false),
	(73139, '2026-03-18 11:00:35.939913+00', 93460, 'portuguese', 'Lesões semi-confluentes', NULL, 'Machine Translation', false),
