	(73147, '2026-03-18 11:00:35.939913+00', 93463, 'french', 'Taille de l''éruption cutanée (peau) - diamètre maximal de toute lésion', NULL, 'Machine Translation', false),
	(73148, '2026-03-18 11:00:35.939913+00', 93463, 'portuguese', 'Tamanho da erupção cutânea (pele) - diâmetro mais largo de qualquer lesão', NULL, 'Machine Translation', false),
	(73149, '2026-03-18 11:00:35.939913+00', 93463, 'spanish', 'Tamaño de la erupción (piel): diámetro máximo de cualquier lesión', NULL, 'Machine Translation', false),
	(73150, '2026-03-18 11:00:35.939913+00', 93464, 'french', 'Il s''agit de la taille de l''éruption cutanée, enregistrée en centimètres (cm) comme le diamètre le plus large de toute lésion.', NULL, 'Machine Translation', false),
	(73151, '2026-03-18 11:00:35.939913+00', 93464, 'portuguese', 'Refere-se ao tamanho da erupção cutânea, registrado como o diâmetro mais largo de qualquer lesão em centímetros (cm).', NULL, 'Machine Translation', false),
	(73152, '2026-03-18 11:00:35.939913+00', 93464, 'spanish', 'Se refiere al tamaño de la erupción cutánea, registrado como el diámetro más ancho de cualquier lesión en centímetros (cm).', NULL, 'Machine Translation', false),
	(73153, '2026-03-18 11:00:35.939913+00', 93465, 'french', 'Indiquez le diamètre le plus large de toute lésion cutanée mesurée en centimètres (cm) le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(73154, '2026-03-18 11:00:35.939913+00', 93465, 'portuguese', 'Indique o diâmetro mais largo de qualquer lesão cutânea medido em centímetros (cm) no dia da avaliação.', NULL, 'Machine Translation', false),
	(73155, '2026-03-18 11:00:35.939913+00', 93465, 'spanish', 'Indique el diámetro más amplio de cualquier lesión cutánea medido en centímetros (cm) el día de la evaluación.', NULL, 'Machine Translation', false),
