	(73643, '2026-03-18 11:00:35.939913+00', 93648, 'portuguese', 'Indique “Sim” se novas lesões apareceram nas últimas 24 horas.', NULL, 'Machine Translation', false),
	(73644, '2026-03-18 11:00:35.939913+00', 93648, 'spanish', 'Indique «Sí» si han aparecido nuevas lesiones en las últimas 24 horas.', NULL, 'Machine Translation', false),
