	(73749, '2026-03-18 11:00:35.939913+00', 93684, 'spanish', 'Cualquier líquido recetado', NULL, 'Machine Translation', false),
	(73750, '2026-03-18 11:00:35.939913+00', 93685, 'french', 'Il s''agit de tous les liquides prescrits (par voie orale ou parentérale/intraveineuse), à l''exclusion de ceux que le patient consomme dans le cadre d''un régime alimentaire non prescrit.', NULL, 'Machine Translation', false),
	(73751, '2026-03-18 11:00:35.939913+00', 93685, 'portuguese', 'Refere-se a quaisquer fluidos prescritos (orais ou parenterais/intravenosos), excluindo aqueles que o paciente consome de forma não prescrita na dieta.', NULL, 'Machine Translation', false),
	(73752, '2026-03-18 11:00:35.939913+00', 93685, 'spanish', 'Se refiere a cualquier líquido prescrito (oral o parenteral/intravenoso), excepto aquellos que el paciente consume de forma no prescrita en su dieta.', NULL, 'Machine Translation', false),
	(73753, '2026-03-18 11:00:35.939913+00', 93686, 'french', 'Indiquez « Oui » si le patient s''est vu prescrire et a reçu des liquides entre 00 h 00 et 24 h 00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(73754, '2026-03-18 11:00:35.939913+00', 93686, 'portuguese', 'Indique “Sim” se o paciente recebeu prescrição e recebeu fluidos entre 00:00 e 24:00 horas no dia da avaliação.', NULL, 'Machine Translation', false),
	(73755, '2026-03-18 11:00:35.939913+00', 93686, 'spanish', 'Indique «Sí» si se le recetaron y administraron líquidos al paciente entre las 00:00 y las 24:00 horas del día de la evaluación.', NULL, 'Machine Translation', false),
	(73756, '2026-03-18 11:00:35.939913+00', 93687, 'french', 'Réhydratation par voie orale', NULL, 'Machine Translation', false),
	(73757, '2026-03-18 11:00:35.939913+00', 93687, 'portuguese', 'Reidratação oral', NULL, 'Machine Translation', false),
	(73758, '2026-03-18 11:00:35.939913+00', 93687, 'spanish', 'Rehidratación oral', NULL, 'Machine Translation', false),
	(73759, '2026-03-18 11:00:35.939913+00', 93688, 'french', 'Il s''agit de liquides entéraux/oraux destinés à la réhydratation.', NULL, 'Machine Translation', false),
	(73760, '2026-03-18 11:00:35.939913+00', 93688, 'portuguese', 'Refere-se a fluidos entéricos/orais para fins de reidratação.', NULL, 'Machine Translation', false),
	(73761, '2026-03-18 11:00:35.939913+00', 93688, 'spanish', 'Se refiere a los líquidos enterales/orales con fines de rehidratación.', NULL, 'Machine Translation', false),
	(73762, '2026-03-18 11:00:35.939913+00', 93689, 'french', 'Indiquez « Oui » si le patient a reçu une réhydratation par voie orale entre 00 h 00 et 24 h 00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(73763, '2026-03-18 11:00:35.939913+00', 93689, 'portuguese', 'Indique “Sim” se o paciente recebeu reidratação oral entre 00:00 e 24:00 horas no dia da avaliação.', NULL, 'Machine Translation', false),
	(73764, '2026-03-18 11:00:35.939913+00', 93689, 'spanish', 'Indique «Sí» si el paciente recibió rehidratación oral entre las 00:00 y las 24:00 horas del día de la evaluación.', NULL, 'Machine Translation', false),
