	(73888, '2026-03-18 11:00:35.939913+00', 93732, 'french', 'Concentré de globules rouges (unités/24 heures)', NULL, 'Machine Translation', false),
	(73889, '2026-03-18 11:00:35.939913+00', 93732, 'portuguese', 'Concentrado de hemácias (unidades/24 horas)', NULL, 'Machine Translation', false),
	(73890, '2026-03-18 11:00:35.939913+00', 93732, 'spanish', 'Concentrado de hematíes (unidades/24 horas)', NULL, 'Machine Translation', false),
	(73891, '2026-03-18 11:00:35.939913+00', 93733, 'french', 'Les concentrés de globules rouges désignent les globules rouges provenant d''une unité de sang total après élimination de la majeure partie du plasma, laissant une unité avec un hématocrite d''environ 60 %.', NULL, 'Machine Translation', false),
	(73892, '2026-03-18 11:00:35.939913+00', 93733, 'portuguese', 'RBC concentrado refere-se aos glóbulos vermelhos de uma unidade de sangue total após a remoção da maior parte do plasma, deixando uma unidade com um hematócrito de cerca de 60%.', NULL, 'Machine Translation', false),
	(73893, '2026-03-18 11:00:35.939913+00', 93733, 'spanish', 'Los glóbulos rojos concentrados son glóbulos rojos procedentes de una unidad de sangre total tras la eliminación de la mayor parte del plasma, dejando una unidad con un hematocrito de aproximadamente el 60 %.', NULL, 'Machine Translation', false),
	(73894, '2026-03-18 11:00:35.939913+00', 93734, 'french', 'Enregistrez le nombre d''unités que le patient a reçues entre 00h00 et 24h00 le jour de l''évaluation en millilitres (mL).', NULL, 'Machine Translation', false),
