	(75595, '2026-03-18 11:00:35.939913+00', 94343, 'french', 'MÉDICAMENTS : Consigner les médicaments administrés ou prescrits entre le jour de la présentation et le jour du congé ou de l''issue (un formulaire par médicament).', NULL, 'Machine Translation', false),
	(75596, '2026-03-18 11:00:35.939913+00', 94343, 'portuguese', 'MEDICAÇÃO: Registre os medicamentos administrados ou prescritos desde o dia da apresentação até o dia da alta/resultado (um formulário por medicamento).', NULL, 'Machine Translation', false),
	(75597, '2026-03-18 11:00:35.939913+00', 94343, 'spanish', 'MEDICACIÓN: Registrar medicamentos administrados o prescritos desde el día de presentación hasta el alta o desenlace (una forma por medicamento)', NULL, 'Machine Translation', false),
