	(75600, '2026-03-18 11:00:35.939913+00', 94344, 'spanish', 'Seleccione los agentes administrados durante la hospitalización o al alta (un formulario por medicamento)', NULL, 'Machine Translation', false),
	(75601, '2026-03-18 11:00:35.939913+00', 94347, 'french', 'Ce médicament est-il utilisé pour traiter la maladie ?', NULL, 'Machine Translation', false),
