	(75626, '2026-03-18 11:00:35.939913+00', 94355, 'portuguese', 'Selecione o(s) agente(s) antibiótico(s) administrado(s) em qualquer momento durante a internação do paciente na unidade clínica (hospital), incluindo no pronto-socorro, e prescrito(s) na alta.', NULL, 'Machine Translation', false),
	(75627, '2026-03-18 11:00:35.939913+00', 94355, 'spanish', 'Seleccione el agente antibiótico o los agentes antibióticos administrados en cualquier momento durante la estancia del paciente en el centro clínico (hospital), incluido el servicio de urgencias, y prescritos al alta.', NULL, 'Machine Translation', false),
