	(75687, '2026-03-18 11:00:35.939913+00', 94375, 'spanish', 'Terapéutico (tratamiento de TVP/EP)', NULL, 'Machine Translation', false),
	(75688, '2026-03-18 11:00:35.939913+00', 94376, 'french', 'Prophylaxie renforcée contre les infections par les agents pathogènes d''intérêt', NULL, 'Machine Translation', false),
