	(75693, '2026-03-18 11:00:35.939913+00', 94377, 'spanish', 'Profilaxis rutinaria en pacientes hospitalizados', NULL, 'Machine Translation', false),
	(75694, '2026-03-18 11:00:35.939913+00', 94378, 'french', 'Antifongique', NULL, 'Machine Translation', false),
	(75695, '2026-03-18 11:00:35.939913+00', 94378, 'portuguese', 'Agente antifúngico', NULL, 'Machine Translation', false),
	(75696, '2026-03-18 11:00:35.939913+00', 94378, 'spanish', 'Agente antifúngico', NULL, 'Machine Translation', false),
	(75745, '2026-03-18 11:00:35.939913+00', 94395, 'french', 'Il s''agit de tout agent qui soulage les démangeaisons (prurit).', NULL, 'Machine Translation', false),
	(75697, '2026-03-18 11:00:35.939913+00', 94379, 'french', 'Désigne tout agent inhibant la croissance ou tuant les champignons, prescrit spécifiquement pour traiter une infection fongique suspectée ou confirmée.', NULL, 'Machine Translation', false),
	(75698, '2026-03-18 11:00:35.939913+00', 94379, 'portuguese', 'Refere-se a qualquer agente que iniba o crescimento ou mate fungos, prescrito especificamente para tratar uma infecção fúngica suspeita ou confirmada.', NULL, 'Machine Translation', false),
	(75699, '2026-03-18 11:00:35.939913+00', 94379, 'spanish', 'Se refiere a cualquier agente que inhiba el crecimiento o elimine los hongos, prescrito específicamente para tratar una infección fúngica sospechada o confirmada.', NULL, 'Machine Translation', false),
	(75700, '2026-03-18 11:00:35.939913+00', 94380, 'french', 'Sélectionnez le ou les antifongiques administrés à tout moment pendant l''admission du patient dans l''établissement clinique (hôpital), y compris aux urgences, et prescrits à la sortie.', NULL, 'Machine Translation', false),
	(75701, '2026-03-18 11:00:35.939913+00', 94380, 'portuguese', 'Selecione o(s) agente(s) antifúngico(s) administrado(s) a qualquer momento durante a internação do paciente na unidade clínica (hospital), incluindo no pronto-socorro, e prescrito(s) na alta.', NULL, 'Machine Translation', false),
	(75702, '2026-03-18 11:00:35.939913+00', 94380, 'spanish', 'Seleccione el agente antifúngico o agentes antifúngicos administrados en cualquier momento durante la estancia del paciente en el centro clínico (hospital), incluido el servicio de urgencias, y prescritos al alta.', NULL, 'Machine Translation', false),
	(75703, '2026-03-18 11:00:35.939913+00', 94381, 'french', 'Inotropes / vasopresseurs', NULL, 'Machine Translation', false),
	(75704, '2026-03-18 11:00:35.939913+00', 94381, 'portuguese', 'Inotrópicos/vasopressores', NULL, 'Machine Translation', false),
	(75705, '2026-03-18 11:00:35.939913+00', 94381, 'spanish', 'Inotrópicos/vasopresores', NULL, 'Machine Translation', false),
	(75706, '2026-03-18 11:00:35.939913+00', 94382, 'french', 'Il s''agit de l''utilisation continue d''un vasopresseur ou d''un inotrope pendant au moins une heure. Les agents comprennent la norépinéphrine, l''épinéphrine, la vasopressine, la terlipressine et la phényléphrine. Les inotropes « positifs » couramment utilisés comprennent la dobutamine, la dopamine, la milrinone et l''adrénaline (épinéphrine).', NULL, 'Machine Translation', false),
	(75707, '2026-03-18 11:00:35.939913+00', 94382, 'portuguese', 'Refere-se ao uso contínuo de um vasopressor ou inotrópico por pelo menos uma hora. Os agentes incluem norepinefrina, epinefrina, vasopressina, terlipressina e fenilefrina. Os inotrópicos “positivos” comumente usados incluem dobutamina, dopamina, milrinona e adrenalina (epinefrina).', NULL, 'Machine Translation', false),
	(75708, '2026-03-18 11:00:35.939913+00', 94382, 'spanish', 'Se refiere al uso continuo de un vasopresor o inotrópico durante al menos una hora. Entre los agentes se incluyen la norepinefrina, la epinefrina, la vasopresina, la terlipresina y la fenilefrina. Los inotrópicos «positivos» más utilizados son la dobutamina, la dopamina, la milrinona y la adrenalina (epinefrina).', NULL, 'Machine Translation', false),
	(75709, '2026-03-18 11:00:35.939913+00', 94383, 'french', 'Sélectionnez le ou les agents vasopresseurs ou inotropes administrés à tout moment pendant l''hospitalisation du patient dans l''établissement clinique (hôpital), y compris aux urgences, et prescrits à la sortie.', NULL, 'Machine Translation', false),
	(75710, '2026-03-18 11:00:35.939913+00', 94383, 'portuguese', 'Selecione o vasopressor ou agente inotrópico administrado a qualquer momento durante a internação do paciente na unidade clínica (hospital), incluindo no pronto-socorro, e prescrito na alta.', NULL, 'Machine Translation', false),
	(75711, '2026-03-18 11:00:35.939913+00', 94383, 'spanish', 'Seleccione el agente vasopresor o inotrópico administrado en cualquier momento durante la estancia del paciente en el centro clínico (hospital), incluido el servicio de urgencias, y prescrito al alta.', NULL, 'Machine Translation', false),
