	(75722, '2026-03-18 11:00:35.939913+00', 94387, 'portuguese', 'Agente analgésico', NULL, 'Machine Translation', false),
	(75723, '2026-03-18 11:00:35.939913+00', 94387, 'spanish', 'Agente analgésico', NULL, 'Machine Translation', false),
	(75724, '2026-03-18 11:00:35.939913+00', 94388, 'french', 'Il s''agit de tout agent qui soulage la douleur sans perte de conscience. Il s''agit notamment des analgésiques opioïdes, non opioïdes et adjuvants.', NULL, 'Machine Translation', false),
	(75725, '2026-03-18 11:00:35.939913+00', 94388, 'portuguese', 'Refere-se a quaisquer agentes que aliviam a dor sem perda de consciência. Estes incluem agentes analgésicos opióides, não opióides e adjuvantes.', NULL, 'Machine Translation', false),
	(75726, '2026-03-18 11:00:35.939913+00', 94388, 'spanish', 'Se refiere a cualquier agente que alivie el dolor sin pérdida de conciencia. Entre ellos se incluyen los agentes analgésicos opioides, no opioides y adyuvantes.', NULL, 'Machine Translation', false),
	(75727, '2026-03-18 11:00:35.939913+00', 94389, 'french', 'Indiquez le ou les agents analgésiques administrés à tout moment pendant l''hospitalisation du patient dans l''établissement clinique (hôpital), y compris aux urgences, et prescrits à la sortie.', NULL, 'Machine Translation', false),
	(75728, '2026-03-18 11:00:35.939913+00', 94389, 'portuguese', 'Indique o(s) agente(s) analgésico(s) administrado(s) a qualquer momento durante a internação do paciente na unidade clínica (hospital), incluindo no pronto-socorro, e prescrito na alta.', NULL, 'Machine Translation', false),
	(75729, '2026-03-18 11:00:35.939913+00', 94389, 'spanish', 'Indique el agente o agentes analgésicos administrados en cualquier momento durante la estancia del paciente en el centro clínico (hospital), incluido el servicio de urgencias, y prescritos al alta.', NULL, 'Machine Translation', false),
