	(76393, '2026-03-18 11:00:35.939913+00', 94632, 'french', 'Il s''agit du lieu où la pneumonie a été contractée : communauté, hôpital, ventilateur ou inconnu.', NULL, 'Machine Translation', false),
	(76394, '2026-03-18 11:00:35.939913+00', 94632, 'portuguese', 'Refere-se ao local onde a pneumonia foi contraída: comunidade, hospital, associada ao uso de ventilador ou desconhecido.', NULL, 'Machine Translation', false),
	(76395, '2026-03-18 11:00:35.939913+00', 94632, 'spanish', 'Se refiere al entorno en el que se contrajo la neumonía: comunidad, hospital, asociada al uso de respiradores o desconocido.', NULL, 'Machine Translation', false),
