	(76405, '2026-03-18 11:00:35.939913+00', 94636, 'french', 'Pneumothorax', NULL, 'Machine Translation', false),
	(76406, '2026-03-18 11:00:35.939913+00', 94636, 'portuguese', 'Pneumotórax', NULL, 'Machine Translation', false),
	(76407, '2026-03-18 11:00:35.939913+00', 94636, 'spanish', 'Neumotórax', NULL, 'Machine Translation', false),
	(76408, '2026-03-18 11:00:35.939913+00', 94637, 'french', 'Définie comme la présence anormale d''air dans la cavité pleurale (entre les poumons et la paroi thoracique), provoquant un collapsus pulmonaire. Elle peut être diagnostiquée cliniquement, généralement avec confirmation radiologique.', NULL, 'Machine Translation', false),
	(76409, '2026-03-18 11:00:35.939913+00', 94637, 'portuguese', 'Definida como a presença anormal de ar na cavidade pleural (entre os pulmões e a parede torácica), causando colapso do pulmão. Pode ser diagnosticada clinicamente, geralmente com confirmação radiológica.', NULL, 'Machine Translation', false),
	(76410, '2026-03-18 11:00:35.939913+00', 94637, 'spanish', '', NULL, 'Machine Translation', false),
