	(76594, '2026-03-18 11:00:35.939913+00', 94702, 'french', 'Tractus gastro-intestinal', NULL, 'Machine Translation', false),
	(76595, '2026-03-18 11:00:35.939913+00', 94702, 'portuguese', 'Trato gastrointestinal', NULL, 'Machine Translation', false),
