	(76649, '2026-03-18 11:00:35.939913+00', 94720, 'portuguese', 'Infecção do trato urinário', NULL, 'Machine Translation', false),
	(76650, '2026-03-18 11:00:35.939913+00', 94720, 'spanish', 'Infección del tracto urinario', NULL, 'Machine Translation', false),
	(76651, '2026-03-18 11:00:35.939913+00', 94721, 'french', 'Il s''agit de réactions inflammatoires de l''épithélium des voies urinaires à des invasions microbiennes. Il s''agit souvent d''infections bactériennes associées à une bactériurie et une pyurie.', NULL, 'Machine Translation', false),
	(76652, '2026-03-18 11:00:35.939913+00', 94721, 'portuguese', 'Refere-se às respostas inflamatórias do epitélio do trato urinário a invasões microbianas. São frequentemente infecções bacterianas associadas a bacteriúria e piúria.', NULL, 'Machine Translation', false),
	(76653, '2026-03-18 11:00:35.939913+00', 94721, 'spanish', 'Se refiere a las respuestas inflamatorias del epitelio del tracto urinario a invasiones microbianas. A menudo se trata de infecciones bacterianas asociadas a bacteriuria y piuria.', NULL, 'Machine Translation', false),
