	(76924, '2026-03-18 11:00:35.939913+00', 94813, 'french', 'Précisez toutes les autres complications, non mentionnées ci-dessus, présentées par le patient à tout moment au cours de son hospitalisation.', NULL, 'Machine Translation', false),
	(76925, '2026-03-18 11:00:35.939913+00', 94813, 'portuguese', 'Especifique todas as outras complicações, não listadas acima, que o paciente apresentou em qualquer momento durante a hospitalização.', NULL, 'Machine Translation', false),
	(76926, '2026-03-18 11:00:35.939913+00', 94813, 'spanish', 'Especifique todas las demás complicaciones, no enumeradas anteriormente, que el paciente experimentó en cualquier momento durante la hospitalización.', NULL, 'Machine Translation', false),
	(76927, '2026-03-18 11:00:35.939913+00', 94814, 'french', 'INTERVENTIONS : Enregistrer les interventions administrées ou prescrites entre le jour de la présentation et le jour de la sortie / l''issue.', NULL, 'Machine Translation', false),
	(76928, '2026-03-18 11:00:35.939913+00', 94814, 'portuguese', 'INTERVENÇÕES: Registre as intervenções realizadas ou prescritas desde o dia da apresentação até o dia da alta/resultado.', NULL, 'Machine Translation', false),
	(76929, '2026-03-18 11:00:35.939913+00', 94814, 'spanish', 'INTERVENCIONES: Registrar las intervenciones realizadas o prescritas desde el día de presentación hasta el alta o desenlace', NULL, 'Machine Translation', false),
	(76930, '2026-03-18 11:00:35.939913+00', 94815, 'french', 'Liquides intraveineux (parentéraux)', NULL, 'Machine Translation', false),
	(76931, '2026-03-18 11:00:35.939913+00', 94815, 'portuguese', 'Fluidos intravenosos (parentéricos)', NULL, 'Machine Translation', false),
