	(76957, '2026-03-18 11:00:35.939913+00', 94826, 'french', 'Enregistrez le volume total de liquide colloïdal que le patient a reçu pendant son admission en millilitres (mL).', NULL, 'Machine Translation', false),
	(76958, '2026-03-18 11:00:35.939913+00', 94826, 'portuguese', 'Registre o volume total de fluido colóide que o paciente recebeu durante a admissão em mililitros (mL).', NULL, 'Machine Translation', false),
