	(76979, '2026-03-18 11:00:35.939913+00', 94834, 'portuguese', 'Refere-se à data em que foi iniciada a primeira administração de fluidos parenterais/intravenosos (IV).', NULL, 'Machine Translation', false),
	(76980, '2026-03-18 11:00:35.939913+00', 94834, 'spanish', 'Se refiere a la fecha en que se inició la primera administración de líquidos parenterales/intravenosos (IV).', NULL, 'Machine Translation', false),
	(76981, '2026-03-18 11:00:35.939913+00', 94835, 'french', 'Indiquez la date au format JJ/MM/AAAA.', NULL, 'Machine Translation', false),
