	(76983, '2026-03-18 11:00:35.939913+00', 94835, 'spanish', 'Escriba la fecha en formato DD/MM/AAAA.', NULL, 'Machine Translation', false),
	(76984, '2026-03-18 11:00:35.939913+00', 94836, 'french', 'Date de la fin de l''administration intraveineuse', NULL, 'Machine Translation', false),
