	(77029, '2026-03-18 11:00:35.939913+00', 94853, 'french', 'Enregistrez le nombre total d''unités que le patient a reçues pendant son hospitalisation.', NULL, 'Machine Translation', false),
	(77030, '2026-03-18 11:00:35.939913+00', 94853, 'portuguese', 'Registre o número total de unidades que o paciente recebeu durante a internação.', NULL, 'Machine Translation', false),
	(77031, '2026-03-18 11:00:35.939913+00', 94853, 'spanish', 'Anote el número total de unidades que recibió el paciente durante la hospitalización.', NULL, 'Machine Translation', false),
	(77032, '2026-03-18 11:00:35.939913+00', 94854, 'french', 'Plasma frais congelé (PFC), nombre total d''unités', NULL, 'Machine Translation', false),
	(77033, '2026-03-18 11:00:35.939913+00', 94854, 'portuguese', 'Plasma fresco congelado (FFP), número total de unidades', NULL, 'Machine Translation', false),
	(77034, '2026-03-18 11:00:35.939913+00', 94854, 'spanish', 'Plasma fresco congelado (PFC), número total de unidades', NULL, 'Machine Translation', false),
	(77035, '2026-03-18 11:00:35.939913+00', 94855, 'french', 'Le plasma frais congelé désigne le plasma qui est séparé du sang total et congelé rapidement après un don de sang afin d''être utilisé pour des transfusions sanguines.', NULL, 'Machine Translation', false),
	(77036, '2026-03-18 11:00:35.939913+00', 94855, 'portuguese', 'Plasma fresco congelado refere-se ao plasma que é separado do sangue total e congelado rapidamente após uma doação de sangue, a fim de ser utilizado em transfusões sanguíneas.', NULL, 'Machine Translation', false),
	(77037, '2026-03-18 11:00:35.939913+00', 94855, 'spanish', 'El plasma fresco congelado se refiere al plasma que se separa de la sangre completa y se congela rápidamente después de una donación de sangre para ser utilizado en transfusiones sanguíneas.', NULL, 'Machine Translation', false),
	(77038, '2026-03-18 11:00:35.939913+00', 94856, 'french', 'Enregistrez le nombre total d''unités que le patient a reçues pendant son hospitalisation.', NULL, 'Machine Translation', false),
	(77039, '2026-03-18 11:00:35.939913+00', 94856, 'portuguese', 'Registre o número total de unidades que o paciente recebeu durante a internação.', NULL, 'Machine Translation', false),
	(77040, '2026-03-18 11:00:35.939913+00', 94856, 'spanish', 'Anote el número total de unidades que recibió el paciente durante la hospitalización.', NULL, 'Machine Translation', false),
	(77041, '2026-03-18 11:00:35.939913+00', 94857, 'french', 'Concentré de fibrinogène, nombre total d''unités', NULL, 'Machine Translation', false),
	(77042, '2026-03-18 11:00:35.939913+00', 94857, 'portuguese', 'Concentrado de fibrinogênio, número total de unidades', NULL, 'Machine Translation', false),
	(77043, '2026-03-18 11:00:35.939913+00', 94857, 'spanish', 'Concentrado de fibrinógeno, número total de unidades', NULL, 'Machine Translation', false),
	(77044, '2026-03-18 11:00:35.939913+00', 94858, 'french', 'Le concentré de fibrinogène est un agent hémostatique utilisé pour le traitement des épisodes hémorragiques aigus chez les patients présentant un déficit congénital en fibrinogène, notamment l''afibrinogénémie et l''hypofibrinogénémie.', NULL, 'Machine Translation', false),
	(77045, '2026-03-18 11:00:35.939913+00', 94858, 'portuguese', 'O concentrado de fibrinogênio é um agente hemostático utilizado no tratamento de episódios de hemorragia aguda em pacientes com deficiência congênita de fibrinogênio, incluindo afibrinogenemia e hipofibrinogenemia.', NULL, 'Machine Translation', false),
	(77046, '2026-03-18 11:00:35.939913+00', 94858, 'spanish', 'El concentrado de fibrinógeno es un agente hemostático utilizado para el tratamiento de episodios hemorrágicos agudos en pacientes con deficiencia congénita de fibrinógeno, incluyendo la afibrinogenemia y la hipofibrinogenemia.', NULL, 'Machine Translation', false),
	(77047, '2026-03-18 11:00:35.939913+00', 94859, 'french', 'Enregistrez le nombre total d''unités que le patient a reçues pendant son hospitalisation.', NULL, 'Machine Translation', false),
	(77048, '2026-03-18 11:00:35.939913+00', 94859, 'portuguese', 'Registre o número total de unidades que o paciente recebeu durante a internação.', NULL, 'Machine Translation', false),
	(77049, '2026-03-18 11:00:35.939913+00', 94859, 'spanish', 'Anote el número total de unidades que recibió el paciente durante la hospitalización.', NULL, 'Machine Translation', false),
	(77050, '2026-03-18 11:00:35.939913+00', 94860, 'french', 'Concentré de globules rouges (concentré de globules rouges), nombre total d''unités', NULL, 'Machine Translation', false),
	(77051, '2026-03-18 11:00:35.939913+00', 94860, 'portuguese', 'Concentrado de hemácias (concentrado de glóbulos vermelhos), número total de unidades', NULL, 'Machine Translation', false),
	(77052, '2026-03-18 11:00:35.939913+00', 94860, 'spanish', 'Concentrado de hematíes (concentrado de glóbulos rojos), número total de unidades', NULL, 'Machine Translation', false),
	(77053, '2026-03-18 11:00:35.939913+00', 94861, 'french', 'Les globules rouges concentrés désignent les globules rouges provenant d''une unité de sang total après élimination de la majeure partie du plasma, laissant une unité avec un hématocrite d''environ 60 %.', NULL, 'Machine Translation', false),
	(77097, '2026-03-18 11:00:35.939913+00', 94875, 'spanish', 'Motivo de este drenaje', NULL, 'Machine Translation', false),
	(78653, '2026-03-18 11:00:35.939913+00', 95409, 'portuguese', 'Anorexia', NULL, 'Machine Translation', false),
	(77054, '2026-03-18 11:00:35.939913+00', 94861, 'portuguese', 'O concentrado de hemácias refere-se aos glóbulos vermelhos de uma unidade de sangue total após a remoção da maior parte do plasma, deixando uma unidade com um hematócrito de cerca de 60%.', NULL, 'Machine Translation', false),
	(77055, '2026-03-18 11:00:35.939913+00', 94861, 'spanish', 'Los glóbulos rojos concentrados son glóbulos rojos procedentes de una unidad de sangre total tras la eliminación de la mayor parte del plasma, lo que da lugar a una unidad con un hematocrito de aproximadamente el 60 %.', NULL, 'Machine Translation', false),
	(77056, '2026-03-18 11:00:35.939913+00', 94862, 'french', 'Enregistrez le nombre total d''unités que le patient a reçues pendant son hospitalisation.', NULL, 'Machine Translation', false),
	(77057, '2026-03-18 11:00:35.939913+00', 94862, 'portuguese', 'Registre o número total de unidades que o paciente recebeu durante a internação.', NULL, 'Machine Translation', false),
	(77058, '2026-03-18 11:00:35.939913+00', 94862, 'spanish', 'Anote el número total de unidades que recibió el paciente durante la hospitalización.', NULL, 'Machine Translation', false),
	(77059, '2026-03-18 11:00:35.939913+00', 94863, 'french', 'Immunoglobulines intraveineuses', NULL, 'Machine Translation', false),
	(77060, '2026-03-18 11:00:35.939913+00', 94863, 'portuguese', 'Imunoglobulina intravenosa', NULL, 'Machine Translation', false),
	(77061, '2026-03-18 11:00:35.939913+00', 94863, 'spanish', 'Inmunoglobulina intravenosa', NULL, 'Machine Translation', false),
	(77062, '2026-03-18 11:00:35.939913+00', 94864, 'french', 'Il s''agit de préparations d''immunoglobulines, contenant principalement de l''immunoglobuline G (IgG), qui sont utilisées en perfusion intraveineuse. Exemples : Octagam®, Intragam P®, KIOVIG®, Flebogamma 5 % DIF®, Carimune NF®, Gamunex®, Gammagard S/D®, Gammagard Liquid®, Gammaked® et Privigen®.', NULL, 'Machine Translation', false),
	(77063, '2026-03-18 11:00:35.939913+00', 94864, 'portuguese', 'Refere-se a preparações de imunoglobulina, contendo principalmente imunoglobulina G (IgG), que são utilizadas como infusões intravenosas. Exemplos incluem Octagam®, Intragam P®, KIOVIG®, Flebogamma 5% DIF®, Carimune NF®, Gamunex®, Gammagard S/D®, Gammagard Liquid® e Privigen®.', NULL, 'Machine Translation', false),
	(77064, '2026-03-18 11:00:35.939913+00', 94864, 'spanish', 'Se refiere a preparados de inmunoglobulina, que contienen principalmente inmunoglobulina G (IgG), que se utilizan en infusiones intravenosas. Algunos ejemplos son Octagam®, Intragam P®, KIOVIG®, Flebogamma 5 % DIF®, Carimune NF®, Gamunex®, Gammagard S/D®, Gammagard Liquid®, Gammaked® y Privigen®.', NULL, 'Machine Translation', false),
	(77065, '2026-03-18 11:00:35.939913+00', 94865, 'french', 'Indiquez « Oui » si le patient a reçu une immunoglobuline intraveineuse à un moment quelconque pendant son admission.', NULL, 'Machine Translation', false),
	(77066, '2026-03-18 11:00:35.939913+00', 94865, 'portuguese', 'Indique “Sim” se o paciente recebeu imunoglobulina intravenosa em qualquer momento durante a internação.', NULL, 'Machine Translation', false),
	(77067, '2026-03-18 11:00:35.939913+00', 94865, 'spanish', 'Indique «Sí» si el paciente recibió inmunoglobulina intravenosa en cualquier momento durante el ingreso.', NULL, 'Machine Translation', false),
	(77068, '2026-03-18 11:00:35.939913+00', 94866, 'french', 'Diurétiques', NULL, 'Machine Translation', false),
	(77069, '2026-03-18 11:00:35.939913+00', 94866, 'portuguese', 'Diuréticos', NULL, 'Machine Translation', false),
	(77070, '2026-03-18 11:00:35.939913+00', 94866, 'spanish', 'Diuréticos', NULL, 'Machine Translation', false),
	(77071, '2026-03-18 11:00:35.939913+00', 94867, 'french', 'Il s''agit d''une classe d''agents qui augmentent la production d''urine par les reins. Grâce à divers mécanismes d''action, les diurétiques retiennent l''eau dans l''urine, ce qui permet une diurèse forcée.', NULL, 'Machine Translation', false),
	(77072, '2026-03-18 11:00:35.939913+00', 94867, 'portuguese', 'Refere-se a uma classe de agentes que aumentam a produção de urina pelos rins. Através de vários mecanismos de ação, os diuréticos retêm água na urina, proporcionando assim uma diurese forçada.', NULL, 'Machine Translation', false),
	(77073, '2026-03-18 11:00:35.939913+00', 94867, 'spanish', 'Se refiere a una clase de agentes que aumentan la producción de orina por parte del riñón. A través de diversos mecanismos de acción, los diuréticos retienen el agua en la orina, lo que proporciona un medio de diuresis forzada.', NULL, 'Machine Translation', false),
	(77074, '2026-03-18 11:00:35.939913+00', 94868, 'french', 'Indiquez « Oui » si le patient a reçu un traitement diurétique à un moment quelconque pendant son admission.', NULL, 'Machine Translation', false),
	(77075, '2026-03-18 11:00:35.939913+00', 94868, 'portuguese', 'Indique “Sim” se o paciente recebeu terapia diurética em qualquer momento durante a internação.', NULL, 'Machine Translation', false),
	(77076, '2026-03-18 11:00:35.939913+00', 94868, 'spanish', 'Indique «Sí» si el paciente recibió tratamiento diurético en cualquier momento durante el ingreso.', NULL, 'Machine Translation', false),
	(77077, '2026-03-18 11:00:35.939913+00', 94869, 'french', 'N-acétylcystéine', NULL, 'Machine Translation', false),
	(77078, '2026-03-18 11:00:35.939913+00', 94869, 'portuguese', 'N-acetilcisteína', NULL, 'Machine Translation', false),
	(77079, '2026-03-18 11:00:35.939913+00', 94869, 'spanish', 'N-acetilcisteína', NULL, 'Machine Translation', false),
	(77080, '2026-03-18 11:00:35.939913+00', 94870, 'french', 'Il s''agit d''un dérivé N-acétylé de la cystéine, utilisé comme agent mucolytique pour réduire la viscosité des sécrétions muqueuses.', NULL, 'Machine Translation', false),
	(77081, '2026-03-18 11:00:35.939913+00', 94870, 'portuguese', 'Refere-se ao derivado N-acetil da cisteína; utilizado como agente mucolítico para reduzir a viscosidade das secreções mucosas.', NULL, 'Machine Translation', false),
	(77082, '2026-03-18 11:00:35.939913+00', 94870, 'spanish', 'Se refiere al derivado N-acetil de la cisteína, utilizado como agente mucolítico para reducir la viscosidad de las secreciones mucosas.', NULL, 'Machine Translation', false),
	(77083, '2026-03-18 11:00:35.939913+00', 94871, 'french', 'Indiquez « Oui » si le patient a reçu de la N-acétylcystéine (NAC) à un moment quelconque pendant son admission.', NULL, 'Machine Translation', false),
	(77084, '2026-03-18 11:00:35.939913+00', 94871, 'portuguese', 'Indique “Sim” se o paciente recebeu N-acetilcisteína (NAC) em qualquer momento durante a internação.', NULL, 'Machine Translation', false),
	(77085, '2026-03-18 11:00:35.939913+00', 94871, 'spanish', 'Indique «Sí» si el paciente recibió N-acetilcisteína (NAC) en cualquier momento durante el ingreso.', NULL, 'Machine Translation', false),
	(77086, '2026-03-18 11:00:35.939913+00', 94872, 'french', 'Drainage de liquide', NULL, 'Machine Translation', false),
	(77087, '2026-03-18 11:00:35.939913+00', 94872, 'portuguese', 'Drenagem de fluidos', NULL, 'Machine Translation', false),
	(77088, '2026-03-18 11:00:35.939913+00', 94872, 'spanish', 'Drenaje de líquidos', NULL, 'Machine Translation', false),
	(77089, '2026-03-18 11:00:35.939913+00', 94873, 'french', 'Il s''agit de la procédure consistant à retirer le liquide de l''espace pleural ou de la cavité péritonéale.', NULL, 'Machine Translation', false),
	(77090, '2026-03-18 11:00:35.939913+00', 94873, 'portuguese', 'Refere-se ao procedimento de remoção de líquido do espaço pleural ou da cavidade peritoneal.', NULL, 'Machine Translation', false),
	(77091, '2026-03-18 11:00:35.939913+00', 94873, 'spanish', 'Se refiere al procedimiento de extracción de líquido del espacio pleural o de la cavidad peritoneal.', NULL, 'Machine Translation', false),
	(77092, '2026-03-18 11:00:35.939913+00', 94874, 'french', 'Indiquez « Oui » si un drainage de liquide de la cavité pleurale ou péritonéale a été effectué à un moment quelconque pendant l''admission.', NULL, 'Machine Translation', false),
	(77093, '2026-03-18 11:00:35.939913+00', 94874, 'portuguese', 'Indique “Sim” se foi realizada drenagem de fluidos da cavidade pleural ou peritoneal em qualquer momento durante a internação.', NULL, 'Machine Translation', false),
	(77094, '2026-03-18 11:00:35.939913+00', 94874, 'spanish', 'Indique «Sí» si se realizó un drenaje de líquido de la cavidad pleural o peritoneal en cualquier momento durante el ingreso.', NULL, 'Machine Translation', false),
	(77095, '2026-03-18 11:00:35.939913+00', 94875, 'french', 'Raison de ce drainage', NULL, 'Machine Translation', false),
	(77096, '2026-03-18 11:00:35.939913+00', 94875, 'portuguese', 'Motivo para esta drenagem', NULL, 'Machine Translation', false),
	(77098, '2026-03-18 11:00:35.939913+00', 94876, 'french', 'Il s''agit de la raison (indication) du drainage des liquides. L''ascite désigne l''accumulation anormale de liquide dans la cavité péritonéale. L''épanchement pleural désigne la présence de liquide dans la cavité pleurale résultant d''une transsudation ou d''une exsudation excessive des surfaces pleurales.', NULL, 'Machine Translation', false),
	(77099, '2026-03-18 11:00:35.939913+00', 94876, 'portuguese', 'Refere-se à razão (indicação) para a drenagem de fluidos. Ascite refere-se ao acúmulo anormal de fluido na cavidade peritoneal. Derrame pleural refere-se à presença de fluido na cavidade pleural resultante de transudação ou exsudação excessiva das superfícies pleurais.', NULL, 'Machine Translation', false),
	(77100, '2026-03-18 11:00:35.939913+00', 94876, 'spanish', 'Se refiere a la razón (indicación) para el drenaje de líquido. La ascitis se refiere a la acumulación anormal de líquido en la cavidad peritoneal. El derrame pleural se refiere a la presencia de líquido en la cavidad pleural como resultado de una transudación o exudación excesiva de las superficies pleurales.', NULL, 'Machine Translation', false),
	(77101, '2026-03-18 11:00:35.939913+00', 94877, 'french', 'Sélectionnez l''option la plus appropriée correspondant à la raison (indication) du drainage de liquide.', NULL, 'Machine Translation', false),
	(77102, '2026-03-18 11:00:35.939913+00', 94877, 'portuguese', 'Selecione a opção mais adequada correspondente ao motivo (indicação) para a drenagem de fluidos.', NULL, 'Machine Translation', false),
	(77103, '2026-03-18 11:00:35.939913+00', 94877, 'spanish', 'Seleccione la opción más adecuada correspondiente al motivo (indicación) del drenaje de líquido.', NULL, 'Machine Translation', false),
	(77104, '2026-03-18 11:00:35.939913+00', 94878, 'french', 'Ascite', NULL, 'Machine Translation', false),
	(77105, '2026-03-18 11:00:35.939913+00', 94878, 'portuguese', 'Ascites', NULL, 'Machine Translation', false),
	(77106, '2026-03-18 11:00:35.939913+00', 94878, 'spanish', 'Ascitis', NULL, 'Machine Translation', false),
	(77107, '2026-03-18 11:00:35.939913+00', 94879, 'french', 'Épanchement pleural', NULL, 'Machine Translation', false),
	(77108, '2026-03-18 11:00:35.939913+00', 94879, 'portuguese', 'Derrame pleural', NULL, 'Machine Translation', false),
	(77109, '2026-03-18 11:00:35.939913+00', 94879, 'spanish', 'Derrame pleural', NULL, 'Machine Translation', false),
	(77110, '2026-03-18 11:00:35.939913+00', 94880, 'french', 'Plasmaphérèse / échange plasmatique', NULL, 'Machine Translation', false),
	(77111, '2026-03-18 11:00:35.939913+00', 94880, 'portuguese', 'Plasmaférese/troca de plasma', NULL, 'Machine Translation', false),
	(77112, '2026-03-18 11:00:35.939913+00', 94880, 'spanish', 'Plasmaféresis/canalización de plasma', NULL, 'Machine Translation', false),
	(77113, '2026-03-18 11:00:35.939913+00', 94881, 'french', 'La plasmaphérèse (échange plasmatique) désigne la séparation extracorporelle des composants sanguins, qui aboutit à un produit filtré. Les méthodes comprennent la centrifugation à flux discontinu, la centrifugation à flux continu et la filtration plasmatique.', NULL, 'Machine Translation', false),
	(77114, '2026-03-18 11:00:35.939913+00', 94881, 'portuguese', 'Plasmaférese (troca de plasma) refere-se à separação extracorpórea de componentes do sangue, resultando em um produto filtrado. Os métodos incluem centrifugação de fluxo descontínuo, centrifugação de fluxo contínuo e filtragem de plasma.', NULL, 'Machine Translation', false),
	(77115, '2026-03-18 11:00:35.939913+00', 94881, 'spanish', 'La plasmaféresis (intercambio de plasma) se refiere a la separación extracorpórea de los componentes sanguíneos, lo que da como resultado un producto filtrado. Los métodos incluyen la centrifugación de flujo discontinuo, la centrifugación de flujo continuo y la filtración de plasma.', NULL, 'Machine Translation', false),
	(77116, '2026-03-18 11:00:35.939913+00', 94882, 'french', 'Indiquez « Oui » si le patient a reçu une plasmaphérèse à un moment quelconque pendant son admission.', NULL, 'Machine Translation', false),
	(77117, '2026-03-18 11:00:35.939913+00', 94882, 'portuguese', 'Indique “Sim” se o paciente recebeu plasmaférese em qualquer momento durante a internação.', NULL, 'Machine Translation', false),
	(77118, '2026-03-18 11:00:35.939913+00', 94882, 'spanish', 'Indique «Sí» si el paciente recibió plasmaféresis en algún momento durante el ingreso.', NULL, 'Machine Translation', false),
