	(77399, '2026-03-18 11:00:35.939913+00', 94978, 'portuguese', 'Indique “Sim” se o paciente ainda estiver em ventilação invasiva.', NULL, 'Machine Translation', false),
	(77400, '2026-03-18 11:00:35.939913+00', 94978, 'spanish', 'Indique «Sí» si el paciente sigue con ventilación invasiva.', NULL, 'Machine Translation', false),
