	(77537, '2026-03-18 11:00:35.939913+00', 95027, 'portuguese', 'Escreva o número total de dias corridos em que o paciente foi internado na UTI.', NULL, 'Machine Translation', false),
	(77538, '2026-03-18 11:00:35.939913+00', 95027, 'spanish', 'Escriba el número total de días naturales que el paciente estuvo ingresado en la UCI.', NULL, 'Machine Translation', false),
	(77539, '2026-03-18 11:00:35.939913+00', 95028, 'french', 'Le patient a-t-il été admis en USI / UTI / UHD / unité de soins intermédiaires plus d''une fois ? ', NULL, 'Machine Translation', false),
	(77540, '2026-03-18 11:00:35.939913+00', 95028, 'portuguese', 'O paciente foi admitido na UTI / UT / HDU / Unidade de Cuidados Intermediários mais de uma vez? ', NULL, 'Machine Translation', false),
	(77541, '2026-03-18 11:00:35.939913+00', 95028, 'spanish', '¿El paciente ingresó en la UCI/UTI/UDH/unidad de cuidados intermedios más de una vez? ', NULL, 'Machine Translation', false),
	(77542, '2026-03-18 11:00:35.939913+00', 95029, 'french', 'Il s''agit de toute admission dans une unité de soins intensifs (ou unité de niveau similaire) à tout moment pendant l''hospitalisation du patient.', NULL, 'Machine Translation', false),
	(77543, '2026-03-18 11:00:35.939913+00', 95029, 'portuguese', 'Refere-se a qualquer admissão em uma unidade de terapia intensiva (ou unidade de nível semelhante) a qualquer momento durante a internação do paciente.', NULL, 'Machine Translation', false),
	(77544, '2026-03-18 11:00:35.939913+00', 95029, 'spanish', 'Se refiere a cualquier admisión en una unidad de cuidados intensivos (o unidad de nivel similar) en cualquier momento durante la hospitalización del paciente.', NULL, 'Machine Translation', false),
	(77545, '2026-03-18 11:00:35.939913+00', 95030, 'french', 'Indiquez « Oui » si le patient a été admis en soins intensifs plus d''une fois à tout moment au cours de son hospitalisation.', NULL, 'Machine Translation', false),
	(77546, '2026-03-18 11:00:35.939913+00', 95030, 'portuguese', 'Indique “Sim” se o paciente foi internado na UTI mais de uma vez em qualquer momento durante a internação.', NULL, 'Machine Translation', false),
	(77547, '2026-03-18 11:00:35.939913+00', 95030, 'spanish', 'Indique «Sí» si el paciente fue ingresado en la UCI más de una vez en cualquier momento durante su hospitalización.', NULL, 'Machine Translation', false),
	(77548, '2026-03-18 11:00:35.939913+00', 95031, 'french', 'Date de la dernière admission en soins intensifs / unité de soins intensifs / unité de soins continus / unité de soins intermédiaires', NULL, 'Machine Translation', false),
