	(78031, '2026-03-18 11:00:35.939913+00', 95194, 'french', 'Un niveau maximal de prise en charge médicale (« plafond de soins ») a-t-il été fixé pour le patient pendant son admission ?', NULL, 'Machine Translation', false),
	(78032, '2026-03-18 11:00:35.939913+00', 95194, 'portuguese', 'Foi definido um nível máximo de suporte médico (“limite de cuidados”) para o paciente durante a internação?', NULL, 'Machine Translation', false),
	(78033, '2026-03-18 11:00:35.939913+00', 95194, 'spanish', '¿Se estableció un nivel máximo de asistencia médica («límite de la asistencia») para el paciente durante su ingreso?', NULL, 'Machine Translation', false),
	(78034, '2026-03-18 11:00:35.939913+00', 95195, 'french', 'Cela fait référence au niveau maximal de soutien médical fixé pour le patient pendant l''hospitalisation en cours.', NULL, 'Machine Translation', false),
	(78035, '2026-03-18 11:00:35.939913+00', 95195, 'portuguese', 'Refere-se ao nível máximo de suporte médico definido para o paciente durante a internação atual.', NULL, 'Machine Translation', false),
	(78036, '2026-03-18 11:00:35.939913+00', 95195, 'spanish', 'Se refiere al nivel máximo de asistencia médica establecido para el paciente durante la admisión actual.', NULL, 'Machine Translation', false),
	(78037, '2026-03-18 11:00:35.939913+00', 95197, 'french', 'Décrivez ce niveau (par exemple, pas de ventilation invasive, pas d''unité de soins intensifs ou pas de réanimation cardio-pulmonaire)', NULL, 'Machine Translation', false),
	(78038, '2026-03-18 11:00:35.939913+00', 95197, 'portuguese', 'Descreva o que foi (por exemplo, não para ventilação invasiva; não para UTI; ou não para RCP)', NULL, 'Machine Translation', false),
	(78039, '2026-03-18 11:00:35.939913+00', 95197, 'spanish', 'Describa en qué consistía (por ejemplo, no se le administró ventilación invasiva, no se le ingresó en la UCI o no se le practicó la RCP).', NULL, 'Machine Translation', false),
	(78040, '2026-03-18 11:00:35.939913+00', 95198, 'french', 'Cela fait référence au niveau maximal de soutien médical fixé pour le patient pendant l''hospitalisation en cours.', NULL, 'Machine Translation', false),
	(78041, '2026-03-18 11:00:35.939913+00', 95198, 'portuguese', 'Refere-se ao nível máximo de suporte médico definido para o paciente durante a internação atual.', NULL, 'Machine Translation', false),
