	(83420, '2026-03-24 07:38:47.050188+00', 97005, 'spanish', 'Se refiere al ingreso del paciente en su centro por la enfermedad actual.', NULL, 'Machine Translation', false),
	(83421, '2026-03-24 07:38:47.050188+00', 97006, 'french', 'Indiquez l''heure d''admission dans votre établissement au format 24 heures (00:00 - 24:00 heures).', NULL, 'Machine Translation', false),
	(83422, '2026-03-24 07:38:47.050188+00', 97006, 'portuguese', 'Insira a hora da admissão em sua unidade no formato de 24 horas (00:00 - 24:00 horas).', NULL, 'Machine Translation', false),
	(83423, '2026-03-24 07:38:47.050188+00', 97006, 'spanish', 'Introduzca la hora de ingreso en su centro en formato de 24 horas (00:00 - 24:00 horas).', NULL, 'Machine Translation', false),
