	(83427, '2026-03-24 07:38:47.050188+00', 97008, 'french', 'Il s''agit de la date d''inscription/de début de la collecte des données.', NULL, 'Machine Translation', false),
	(83428, '2026-03-24 07:38:47.050188+00', 97008, 'portuguese', 'Refere-se à data de inscrição/início da coleta de dados.', NULL, 'Machine Translation', false),
	(83429, '2026-03-24 07:38:47.050188+00', 97008, 'spanish', 'Se refiere a la fecha de inscripción/inicio de la recopilación de datos.', NULL, 'Machine Translation', false),
	(83430, '2026-03-24 07:38:47.050188+00', 97009, 'french', 'Indiquez la date d''inscription du patient à l''étude au format jour/mois/année (JJ/MM/AAAA).', NULL, 'Machine Translation', false),
	(83431, '2026-03-24 07:38:47.050188+00', 97009, 'portuguese', 'Insira a data de inscrição do paciente no estudo no formato dia/mês/ano (DD/MM/AAAA).', NULL, 'Machine Translation', false),
	(83432, '2026-03-24 07:38:47.050188+00', 97009, 'spanish', 'Introduzca la fecha de inscripción del paciente en el estudio en formato día/mes/año (DD/MM/AAAA).', NULL, 'Machine Translation', false),
	(83433, '2026-03-24 07:38:47.050188+00', 97010, 'french', 'Indiquez la date de présentation à l''établissement dans lequel le patient a été admis ou transféré précédemment.', NULL, 'Machine Translation', false),
	(83434, '2026-03-24 07:38:47.050188+00', 97010, 'portuguese', 'Insira a data de apresentação na instituição na qual o paciente foi admitido ou transferido anteriormente.', NULL, 'Machine Translation', false),
	(83435, '2026-03-24 07:38:47.050188+00', 97010, 'spanish', 'Introduzca la fecha de presentación en el centro en el que fue ingresado o trasladado el paciente.', NULL, 'Machine Translation', false),
