	(83919, '2026-03-24 07:38:47.050188+00', 97194, 'french', 'Saignement / hémorragie grave (nécessitant une intervention)', NULL, 'Machine Translation', false),
	(83920, '2026-03-24 07:38:47.050188+00', 97194, 'portuguese', 'Sangramento/hemorragia grave (requer intervenção)', NULL, 'Machine Translation', false),
	(83921, '2026-03-24 07:38:47.050188+00', 97194, 'spanish', 'Sangrado/hemorragia grave (requiere intervención)', NULL, 'Machine Translation', false),
	(83922, '2026-03-24 07:38:47.050188+00', 97195, 'french', 'Précisez le(s) site(s) du saignement / de l''hémorragie', NULL, 'Machine Translation', false),
	(83923, '2026-03-24 07:38:47.050188+00', 97195, 'portuguese', 'Especifique o(s) local(is) do sangramento/hemorragia', NULL, 'Machine Translation', false),
	(83924, '2026-03-24 07:38:47.050188+00', 97195, 'spanish', 'Especifique el lugar o lugares del sangrado/hemorragia', NULL, 'Machine Translation', false),
	(83925, '2026-03-24 07:38:47.050188+00', 97196, 'french', 'Précisez tout autre site de saignement / d''hémorragie', NULL, 'Machine Translation', false),
	(83926, '2026-03-24 07:38:47.050188+00', 97196, 'portuguese', 'Especifique outro(s) local(is) do sangramento/hemorragia', NULL, 'Machine Translation', false),
	(83927, '2026-03-24 07:38:47.050188+00', 97196, 'spanish', 'Especifique otros lugares de sangrado/hemorragia', NULL, 'Machine Translation', false),
	(83928, '2026-03-24 07:38:47.050188+00', 97197, 'french', 'Ce terme fait référence à la localisation du ou des sites de saignement/hémorragie.', NULL, 'Machine Translation', false),
	(83929, '2026-03-24 07:38:47.050188+00', 97197, 'portuguese', 'Refere-se à localização do(s) local(is) do sangramento/hemorragia.', NULL, 'Machine Translation', false),
	(83930, '2026-03-24 07:38:47.050188+00', 97197, 'spanish', 'Se refiere a la ubicación del sitio o sitios de sangrado/hemorragia.', NULL, 'Machine Translation', false),
	(83931, '2026-03-24 07:38:47.050188+00', 97198, 'french', 'Si « Autre », indiquez l''autre emplacement du ou des sites où le patient a présenté des saignements/hémorragies à tout moment entre le début de la maladie et la présentation ou l''admission.', NULL, 'Machine Translation', false),
	(83932, '2026-03-24 07:38:47.050188+00', 97198, 'portuguese', 'Se “Outro”, escreva a outra localização do(s) local(is) onde o paciente apresentou sangramento/hemorragia em qualquer momento desde o início da doença até a apresentação ou admissão.', NULL, 'Machine Translation', false),
	(83933, '2026-03-24 07:38:47.050188+00', 97198, 'spanish', 'Si «Otro», escriba la otra ubicación del sitio o sitios donde el paciente ha experimentado sangrado/hemorragia en cualquier momento desde el inicio de esta enfermedad y la presentación o el ingreso.', NULL, 'Machine Translation', false),
	(83934, '2026-03-24 07:38:47.050188+00', 97199, 'french', 'Autre(s) symptôme(s)', NULL, 'Machine Translation', false),
