	(83937, '2026-03-24 07:38:47.050188+00', 97200, 'french', 'Entrez la date de l''accouchement au format JJ/MM/AAAA.', NULL, 'Machine Translation', false),
	(83938, '2026-03-24 07:38:47.050188+00', 97200, 'portuguese', 'Insira a data do parto no formato DD/MM/AAAA.', NULL, 'Machine Translation', false),
	(83939, '2026-03-24 07:38:47.050188+00', 97200, 'spanish', 'Introduzca la fecha del parto en formato DD/MM/AAAA.', NULL, 'Machine Translation', false),
