	(83941, '2026-03-24 07:38:47.050188+00', 97201, 'portuguese', 'Se houve interrupção da gravidez: Qual foi o motivo?', NULL, 'Machine Translation', false),
	(83942, '2026-03-24 07:38:47.050188+00', 97201, 'spanish', 'Si se ha interrumpido el embarazo: ¿Cuál fue el motivo?', NULL, 'Machine Translation', false),
	(83943, '2026-03-24 07:38:47.050188+00', 97203, 'french', 'Sélectionnez l''option la plus appropriée qui correspond à l''indication de l''interruption de grossesse.', NULL, 'Machine Translation', false),
	(83944, '2026-03-24 07:38:47.050188+00', 97203, 'portuguese', 'Selecione a opção mais adequada que representa a indicação para a interrupção da gravidez.', NULL, 'Machine Translation', false),
	(83945, '2026-03-24 07:38:47.050188+00', 97203, 'spanish', 'Seleccione la opción más adecuada que represente la indicación para la interrupción del embarazo.', NULL, 'Machine Translation', false),
