	(85041, '2026-03-24 07:38:47.050188+00', 97594, 'french', 'Oxygénothérapie après la sortie de l''hôpital', NULL, 'Machine Translation', false),
	(85042, '2026-03-24 07:38:47.050188+00', 97594, 'portuguese', 'Oxigenoterapia após a alta', NULL, 'Machine Translation', false),
