	(87503, '2026-03-24 08:40:11.045472+00', 100210, 'spanish', 'Super-infección bacteriana', NULL, 'Machine Translation', false),
	(87504, '2026-03-24 08:40:11.045472+00', 100211, 'french', 'Défini comme une infection bactérienne secondaire diagnostiquée par un médecin qui se produit lors d''une infection existante ou immédiatement après une infection antérieure.', NULL, 'Machine Translation', false),
