	(87516, '2026-03-24 08:40:11.045472+00', 100217, 'french', 'Cela fait référence aux autres types ou emplacements de la super-infection bactérienne, non spécifiée ci-dessus.', NULL, 'Machine Translation', false),
	(87517, '2026-03-24 08:40:11.045472+00', 100217, 'portuguese', 'Isso se refere aos outros tipos ou locais da (s) localização (s) da super infecção bacteriana, não especificados acima.', NULL, 'Machine Translation', false),
	(87518, '2026-03-24 08:40:11.045472+00', 100217, 'spanish', 'Esto se refiere al otro tipo (s) o ubicación (s) de la superinfección bacteriana, no especificada anteriormente.', NULL, 'Machine Translation', false),
	(87519, '2026-03-24 08:40:11.045472+00', 100219, 'french', 'Pharyngite / amygdalite', NULL, 'Machine Translation', false),
