	(87521, '2026-03-24 08:40:11.045472+00', 100219, 'spanish', 'Faringitis / amigdalitis', NULL, 'Machine Translation', false),
	(87522, '2026-03-24 08:40:11.045472+00', 100220, 'french', 'Cela fait référence à la présence de l''inflammation de la gorge et / ou des amygdales.', NULL, 'Machine Translation', false),
	(87523, '2026-03-24 08:40:11.045472+00', 100220, 'portuguese', 'Isso se refere à presença de inflamação da garganta e/ou amígdalas.', NULL, 'Machine Translation', false),
