	(87816, '2026-03-24 08:40:11.045472+00', 100357, 'french', 'Salivation excessive', NULL, 'Machine Translation', false),
	(87817, '2026-03-24 08:40:11.045472+00', 100357, 'portuguese', 'Salivação excessiva', NULL, 'Machine Translation', false),
	(87818, '2026-03-24 08:40:11.045472+00', 100357, 'spanish', 'Salivación excesiva', NULL, 'Machine Translation', false),
	(87819, '2026-03-24 08:40:11.045472+00', 100358, 'french', 'Défini comme une salivation excessive ou une sialorrhée, est un symptôme mieux évalué par le patient.', NULL, 'Machine Translation', false),
	(87820, '2026-03-24 08:40:11.045472+00', 100358, 'portuguese', 'Definido como salivação excessiva ou sialorréia, é um sintoma melhor avaliado pelo paciente.', NULL, 'Machine Translation', false),
	(87821, '2026-03-24 08:40:11.045472+00', 100358, 'spanish', 'Definido como salivación excesiva o sialorrea, es un síntoma mejor evaluado por el paciente.', NULL, 'Machine Translation', false),
	(87822, '2026-03-24 08:40:11.045472+00', 100360, 'french', 'Difficulté à avaler / dysphagie', NULL, 'Machine Translation', false),
	(87823, '2026-03-24 08:40:11.045472+00', 100360, 'portuguese', 'Dificuldade de engolir / disfagia', NULL, 'Machine Translation', false),
	(87824, '2026-03-24 08:40:11.045472+00', 100360, 'spanish', 'Dificultad para tragar / disfagia', NULL, 'Machine Translation', false),
	(87825, '2026-03-24 08:40:11.045472+00', 100361, 'french', 'Défini comme difficulté à avaler des aliments, des liquides ou de la salive.', NULL, 'Machine Translation', false),
	(87826, '2026-03-24 08:40:11.045472+00', 100361, 'portuguese', 'Definido como dificuldade em engolir alimentos, líquidos ou saliva.', NULL, 'Machine Translation', false),
	(87827, '2026-03-24 08:40:11.045472+00', 100361, 'spanish', 'Definido como dificultad para tragar alimentos, líquidos o saliva.', NULL, 'Machine Translation', false),
	(87828, '2026-03-24 08:40:11.045472+00', 100363, 'french', 'Rétention urinaire', NULL, 'Machine Translation', false),
