	(87967, '2026-03-24 08:40:11.045472+00', 100427, 'portuguese', 'Definido como coceira de um ou ambos os olhos.', NULL, 'Machine Translation', false),
	(87968, '2026-03-24 08:40:11.045472+00', 100427, 'spanish', 'Definido como picazón de uno o ambos ojos.', NULL, 'Machine Translation', false),
	(87969, '2026-03-24 08:40:11.045472+00', 100429, 'french', 'Œil rouge / rose', NULL, 'Machine Translation', false),
