	(87971, '2026-03-24 08:40:11.045472+00', 100429, 'spanish', 'Ojo rojo / rosa', NULL, 'Machine Translation', false),
	(87972, '2026-03-24 08:40:11.045472+00', 100430, 'french', 'Défini comme une inflammation ou une infection de la conjonctive, caractérisée par des rougeurs dans un ou deux yeux.', NULL, 'Machine Translation', false),
	(87973, '2026-03-24 08:40:11.045472+00', 100430, 'portuguese', 'Definido como inflamação ou infecção da conjuntiva, caracterizada pela vermelhidão em um ou nos dois olhos.', NULL, 'Machine Translation', false),
	(87974, '2026-03-24 08:40:11.045472+00', 100430, 'spanish', 'Definido como inflamación o infección de la conjuntiva, caracterizada por el enrojecimiento en uno o ambos ojos.', NULL, 'Machine Translation', false),
