	(88058, '2026-03-24 08:40:11.045472+00', 100471, 'spanish', 'Especificar otros sitios de linfadenopatía', NULL, 'Machine Translation', false),
	(88059, '2026-03-24 08:40:11.045472+00', 100472, 'french', 'Cela fait référence à l''emplacement dans lequel la lymphadénopathie a été identifiée.', NULL, 'Machine Translation', false),
	(88060, '2026-03-24 08:40:11.045472+00', 100472, 'portuguese', 'Isso se refere ao local em que a linfadenopatia foi identificada.', NULL, 'Machine Translation', false),
	(88061, '2026-03-24 08:40:11.045472+00', 100472, 'spanish', 'Esto se refiere a la ubicación en la que se identificó la linfadenopatía.', NULL, 'Machine Translation', false),
	(88062, '2026-03-24 08:40:11.045472+00', 100473, 'french', 'Si «autre», écrivez l''emplacement dans lequel la lymphadénopathie a été identifiée.', NULL, 'Machine Translation', false),
	(88063, '2026-03-24 08:40:11.045472+00', 100473, 'portuguese', 'Se ''outro'', escreva o local em que a linfadenopatia foi identificada.', NULL, 'Machine Translation', false),
	(88064, '2026-03-24 08:40:11.045472+00', 100473, 'spanish', 'Si ''otro'', escriba la ubicación en la que se identificó la linfadenopatía.', NULL, 'Machine Translation', false),
	(88065, '2026-03-24 08:40:11.045472+00', 100474, 'french', 'Super-infection bactérienne', NULL, 'Machine Translation', false),
	(88066, '2026-03-24 08:40:11.045472+00', 100474, 'portuguese', 'Super infecção bacteriana', NULL, 'Machine Translation', false),
	(88067, '2026-03-24 08:40:11.045472+00', 100474, 'spanish', 'Super-infección bacteriana', NULL, 'Machine Translation', false),
	(88068, '2026-03-24 08:40:11.045472+00', 100475, 'french', 'Défini comme une infection bactérienne secondaire diagnostiquée par un médecin qui se produit lors d''une infection existante ou immédiatement après une infection antérieure.', NULL, 'Machine Translation', false),
	(88069, '2026-03-24 08:40:11.045472+00', 100475, 'portuguese', 'Definido como uma infecção bacteriana secundária diagnosticada por médicos que ocorre durante uma infecção existente ou imediatamente após uma infecção anterior.', NULL, 'Machine Translation', false),
	(88070, '2026-03-24 08:40:11.045472+00', 100475, 'spanish', 'Definido como una infección bacteriana secundaria diagnosticada con el médico que ocurre durante una infección existente o inmediatamente después de una infección anterior.', NULL, 'Machine Translation', false),
	(88071, '2026-03-24 08:40:11.045472+00', 100476, 'french', 'Indiquez «oui», si le patient a connu entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88072, '2026-03-24 08:40:11.045472+00', 100476, 'portuguese', 'Indique ''sim'', se o paciente experimentou entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88073, '2026-03-24 08:40:11.045472+00', 100476, 'spanish', 'Indique ''sí'', si el paciente ha experimentado entre las 00:00 a las 24:00 el día de la evaluación.', NULL, 'Machine Translation', false),
	(88074, '2026-03-24 08:40:11.045472+00', 100477, 'french', 'Si oui: spécifiez la super-infection bactérienne.', NULL, 'Machine Translation', false),
	(88075, '2026-03-24 08:40:11.045472+00', 100477, 'portuguese', 'Se sim: especifique a super infecção bacteriana.', NULL, 'Machine Translation', false),
	(88076, '2026-03-24 08:40:11.045472+00', 100477, 'spanish', 'En caso afirmativo: especifique la superinfección bacteriana.', NULL, 'Machine Translation', false),
	(88077, '2026-03-24 08:40:11.045472+00', 100478, 'french', 'Il s''agit du type ou de l''emplacement de la super-infection bactérienne.', NULL, 'Machine Translation', false),
	(88078, '2026-03-24 08:40:11.045472+00', 100478, 'portuguese', 'Isso se refere ao tipo ou local da super infecção bacteriana.', NULL, 'Machine Translation', false),
	(88079, '2026-03-24 08:40:11.045472+00', 100478, 'spanish', 'Esto se refiere al tipo o ubicación de la superinfección bacteriana.', NULL, 'Machine Translation', false),
	(88080, '2026-03-24 08:40:11.045472+00', 100480, 'french', 'Si autre: spécifiez une autre super-infection bactérienne', NULL, 'Machine Translation', false),
	(88081, '2026-03-24 08:40:11.045472+00', 100480, 'portuguese', 'Se o outro: especifique outra super infecção bacteriana', NULL, 'Machine Translation', false),
	(88082, '2026-03-24 08:40:11.045472+00', 100480, 'spanish', 'Si otro: especifique otra super-infección bacteriana', NULL, 'Machine Translation', false),
	(88083, '2026-03-24 08:40:11.045472+00', 100481, 'french', 'Cela fait référence aux autres types ou emplacements de la super-infection bactérienne, non spécifiée ci-dessus.', NULL, 'Machine Translation', false),
	(88084, '2026-03-24 08:40:11.045472+00', 100481, 'portuguese', 'Isso se refere aos outros tipos ou locais da (s) localização (s) da super infecção bacteriana, não especificados acima.', NULL, 'Machine Translation', false),
	(88085, '2026-03-24 08:40:11.045472+00', 100481, 'spanish', 'Esto se refiere al otro tipo (s) o ubicación (s) de la superinfección bacteriana, no especificada anteriormente.', NULL, 'Machine Translation', false),
	(88086, '2026-03-24 08:40:11.045472+00', 100483, 'french', 'Pharyngite / amygdalite', NULL, 'Machine Translation', false),
	(88087, '2026-03-24 08:40:11.045472+00', 100483, 'portuguese', 'Faringite / amigdalite', NULL, 'Machine Translation', false),
	(88088, '2026-03-24 08:40:11.045472+00', 100483, 'spanish', 'Faringitis / amigdalitis', NULL, 'Machine Translation', false),
	(88089, '2026-03-24 08:40:11.045472+00', 100484, 'french', 'Cela fait référence à la douleur dans la gorge, généralement en présence d''une inflammation de la gorge (pharynx) et / ou d''amygdales.', NULL, 'Machine Translation', false),
	(88090, '2026-03-24 08:40:11.045472+00', 100484, 'portuguese', 'Isso se refere à dor na garganta, tipicamente na presença de inflamação da garganta (faringe) e/ou amígdalas.', NULL, 'Machine Translation', false),
	(88091, '2026-03-24 08:40:11.045472+00', 100484, 'spanish', 'Esto se refiere al dolor en la garganta, típicamente en presencia de inflamación de la garganta (faringe) y/o amígdalas.', NULL, 'Machine Translation', false),
	(88092, '2026-03-24 08:40:11.045472+00', 100485, 'french', 'Indiquez «oui», si le patient a vécu cela entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88093, '2026-03-24 08:40:11.045472+00', 100485, 'portuguese', 'Indique ''sim'', se o paciente experimentou isso entre 00:00 às 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88094, '2026-03-24 08:40:11.045472+00', 100485, 'spanish', 'Indique ''sí'', si el paciente experimentó esto entre las 00:00 a las 24:00 el día de la evaluación.', NULL, 'Machine Translation', false),
	(88095, '2026-03-24 08:40:11.045472+00', 100486, 'french', 'Mastite', NULL, 'Machine Translation', false),
	(88096, '2026-03-24 08:40:11.045472+00', 100486, 'portuguese', 'Mastite', NULL, 'Machine Translation', false),
	(88097, '2026-03-24 08:40:11.045472+00', 100486, 'spanish', 'Mastitis', NULL, 'Machine Translation', false),
	(88098, '2026-03-24 08:40:11.045472+00', 100487, 'french', 'Défini comme une inflammation du sein, avec ou sans infection qui l''accompagne', NULL, 'Machine Translation', false),
	(88099, '2026-03-24 08:40:11.045472+00', 100487, 'portuguese', 'Definido como uma inflamação da mama, com ou sem infecção acompanhante', NULL, 'Machine Translation', false),
	(88100, '2026-03-24 08:40:11.045472+00', 100487, 'spanish', 'Definido como una inflamación del seno, con o sin infección acompañante', NULL, 'Machine Translation', false),
	(88101, '2026-03-24 08:40:11.045472+00', 100488, 'french', 'Indiquez «oui», si le patient a vécu cela à tout moment à la date de l''évaluation.', NULL, 'Machine Translation', false),
	(88102, '2026-03-24 08:40:11.045472+00', 100488, 'portuguese', 'Indique ''sim'', se o paciente experimentou isso a qualquer momento durante a data da avaliação.', NULL, 'Machine Translation', false),
	(88103, '2026-03-24 08:40:11.045472+00', 100488, 'spanish', 'Indique ''sí'', si el paciente experimentó esto en cualquier momento durante la fecha de evaluación.', NULL, 'Machine Translation', false),
	(88104, '2026-03-24 08:40:11.045472+00', 100489, 'french', 'Entrez les données des signes vitaux pour cette date?', NULL, 'Machine Translation', false),
	(88105, '2026-03-24 08:40:11.045472+00', 100489, 'portuguese', 'Insira dados de sinais vitais para esta data?', NULL, 'Machine Translation', false),
	(88106, '2026-03-24 08:40:11.045472+00', 100489, 'spanish', 'Ingrese datos de signos vitales para esta fecha?', NULL, 'Machine Translation', false),
	(88107, '2026-03-24 08:40:11.045472+00', 100490, 'french', 'Indiquez «oui», si vous souhaitez enregistrer les données des signes vitaux pour ce jour d''évaluation. Si «oui», pour les questions suivantes, sauf indication contraire, enregistrez la valeur la plus éloignée de la plage physiologique normale enregistrée entre 00h00 et 24h00 le jour de l''évaluation. Les résultats qui ont été rejetés par l''équipe clinique ne doivent pas être inclus.', NULL, 'Machine Translation', false),
	(88108, '2026-03-24 08:40:11.045472+00', 100490, 'portuguese', 'Indique ''sim'', se você deseja gravar dados de sinal vital para este dia de avaliação. Se ''sim'', para as seguintes perguntas, a menos que especificado de outra forma, registre o valor mais distante da faixa fisiológica normal registrada entre 00:00 e 24:00 horas no dia da avaliação. Os resultados que foram rejeitados pela equipe clínica não devem ser incluídos.', NULL, 'Machine Translation', false),
	(88109, '2026-03-24 08:40:11.045472+00', 100490, 'spanish', 'Indique ''sí'', si desea registrar datos de signo vital para este día de evaluación. Si ''sí'', para las siguientes preguntas a menos que se especifique lo contrario, registre el valor más lejos del rango fisiológico normal registrado entre 00:00 y 24:00 horas en el día de la evaluación. Los resultados que fueron rechazados por el equipo clínico no deben incluirse.', NULL, 'Machine Translation', false),
	(88110, '2026-03-24 08:40:11.045472+00', 100491, 'french', 'Température la plus élevée (unités sélectionnées)', NULL, 'Machine Translation', false),
	(88111, '2026-03-24 08:40:11.045472+00', 100491, 'portuguese', 'Temperatura mais alta (unidades selecionadas)', NULL, 'Machine Translation', false),
	(88112, '2026-03-24 08:40:11.045472+00', 100491, 'spanish', 'Temperatura más alta (unidades seleccionadas)', NULL, 'Machine Translation', false),
	(88113, '2026-03-24 08:40:11.045472+00', 100492, 'french', 'Fait référence à la température corporelle périphérique la plus élevée (rectal si <3 mois) entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88114, '2026-03-24 08:40:11.045472+00', 100492, 'portuguese', 'Refere -se à maior temperatura corporal periférica (retal se <3 meses) entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88115, '2026-03-24 08:40:11.045472+00', 100492, 'spanish', 'Se refiere a la temperatura corporal periférica más alta (rectal IF <3 meses) entre las 00:00 y las 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88116, '2026-03-24 08:40:11.045472+00', 100493, 'french', 'Sélectionnez les unités les plus appropriées pour la température.', NULL, 'Machine Translation', false),
	(88117, '2026-03-24 08:40:11.045472+00', 100493, 'portuguese', 'Selecione as unidades mais apropriadas para a temperatura.', NULL, 'Machine Translation', false),
	(88118, '2026-03-24 08:40:11.045472+00', 100493, 'spanish', 'Seleccione las unidades más apropiadas para la temperatura.', NULL, 'Machine Translation', false),
	(88119, '2026-03-24 08:40:11.045472+00', 100494, 'french', 'Température la plus élevée (° C)', NULL, 'Machine Translation', false),
	(88120, '2026-03-24 08:40:11.045472+00', 100494, 'portuguese', 'Temperatura mais alta (° C)', NULL, 'Machine Translation', false),
	(88121, '2026-03-24 08:40:11.045472+00', 100494, 'spanish', 'Temperatura más alta (° C)', NULL, 'Machine Translation', false),
	(88122, '2026-03-24 08:40:11.045472+00', 100495, 'french', 'Fait référence à la température corporelle périphérique la plus élevée (rectal si <3 mois) en degrés Celsius (° C) entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88123, '2026-03-24 08:40:11.045472+00', 100495, 'portuguese', 'Refere -se à maior temperatura corporal periférica (retal se <3 meses) em graus Celsius (° C) entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88124, '2026-03-24 08:40:11.045472+00', 100495, 'spanish', 'Se refiere a la temperatura corporal periférica más alta (rectal IF <3 meses) en grados centígrados (° C) entre las 00:00 y las 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88125, '2026-03-24 08:40:11.045472+00', 100496, 'french', 'Entrez la température corporelle périphérique la plus élevée (° C) enregistrée entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88126, '2026-03-24 08:40:11.045472+00', 100496, 'portuguese', 'Entre na maior temperatura corporal periférica (° C) registrada entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88127, '2026-03-24 08:40:11.045472+00', 100496, 'spanish', 'Ingrese la temperatura corporal periférica más alta (° C) registrada entre las 00:00 y las 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88128, '2026-03-24 08:40:11.045472+00', 100497, 'french', 'Température la plus élevée (° F)', NULL, 'Machine Translation', false),
	(88129, '2026-03-24 08:40:11.045472+00', 100497, 'portuguese', 'Temperatura mais alta (° F)', NULL, 'Machine Translation', false),
	(88130, '2026-03-24 08:40:11.045472+00', 100497, 'spanish', 'Temperatura más alta (° F)', NULL, 'Machine Translation', false),
	(88131, '2026-03-24 08:40:11.045472+00', 100498, 'french', 'Fait référence à la température corporelle périphérique la plus élevée (rectal si <3 mois) en degrés Fahrenheit (° F) entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88132, '2026-03-24 08:40:11.045472+00', 100498, 'portuguese', 'Refere -se à maior temperatura corporal periférica (retal se <3 meses) em graus Fahrenheit (° F) entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88133, '2026-03-24 08:40:11.045472+00', 100498, 'spanish', 'Se refiere a la temperatura corporal periférica más alta (rectal IF <3 meses) en grados Fahrenheit (° F) entre 00:00 y 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88134, '2026-03-24 08:40:11.045472+00', 100499, 'french', 'Entrez la température corporelle périphérique la plus élevée (° F) enregistrée entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88135, '2026-03-24 08:40:11.045472+00', 100499, 'portuguese', 'Entre na maior temperatura corporal periférica (° F) registrada entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88136, '2026-03-24 08:40:11.045472+00', 100499, 'spanish', 'Ingrese la temperatura corporal periférica más alta (° F) registrada entre las 00:00 y las 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88137, '2026-03-24 08:40:11.045472+00', 100500, 'french', 'RH (battements / minute)', NULL, 'Machine Translation', false),
	(88138, '2026-03-24 08:40:11.045472+00', 100500, 'portuguese', 'RH (batidas/minuto)', NULL, 'Machine Translation', false),
	(88139, '2026-03-24 08:40:11.045472+00', 100500, 'spanish', 'HR (ritmos/minuto)', NULL, 'Machine Translation', false),
	(88140, '2026-03-24 08:40:11.045472+00', 100501, 'french', 'Fait référence à la fréquence cardiaque mesurée par des battements par minute. Cela peut être mesuré manuellement ou par surveillance électronique.', NULL, 'Machine Translation', false),
	(88141, '2026-03-24 08:40:11.045472+00', 100501, 'portuguese', 'Refere -se à freqüência cardíaca medida em batimentos por minuto. Isso pode ser medido manualmente ou por monitoramento eletrônico.', NULL, 'Machine Translation', false),
	(88142, '2026-03-24 08:40:11.045472+00', 100501, 'spanish', 'Se refiere a la frecuencia cardíaca medida en latidos por minuto. Esto puede medirse manualmente o mediante monitoreo electrónico.', NULL, 'Machine Translation', false),
	(88143, '2026-03-24 08:40:11.045472+00', 100502, 'french', 'Entrez le rythme cardiaque mesuré en battements par minute. Enregistrez la valeur la plus éloignée de la plage normale entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88144, '2026-03-24 08:40:11.045472+00', 100502, 'portuguese', 'Digite a frequência cardíaca medida em batidas por minuto. Registre o valor mais distante do intervalo normal entre 00:00 às 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88145, '2026-03-24 08:40:11.045472+00', 100502, 'spanish', 'Ingrese la frecuencia cardíaca medida en ritmos por minuto. Registre el valor más lejos del rango normal entre las 00:00 a las 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88146, '2026-03-24 08:40:11.045472+00', 100503, 'french', 'RR (BPM)', NULL, 'Machine Translation', false),
	(88147, '2026-03-24 08:40:11.045472+00', 100503, 'portuguese', 'RR (BPM)', NULL, 'Machine Translation', false),
	(88148, '2026-03-24 08:40:11.045472+00', 100503, 'spanish', 'RR (BPM)', NULL, 'Machine Translation', false),
	(88149, '2026-03-24 08:40:11.045472+00', 100504, 'french', 'Fait référence à la fréquence respiratoire en respirations par minute. La mesure manuelle plutôt que électronique est préférée dans la mesure du possible (celle-ci est réalisée en comptant le nombre de respirations pendant une minute, en comptant combien de fois la poitrine augmente dans cette période).  Si à la fois un taux anormal bas et élevé observé, enregistrez le taux anormalement élevé.', NULL, 'Machine Translation', false),
	(88150, '2026-03-24 08:40:11.045472+00', 100504, 'portuguese', 'Refere -se à frequência respiratória em respirações por minuto. A medição manual e não eletrônica é preferida sempre que possível (isso é alcançado contando o número de respirações por um minuto, contando quantas vezes o baú aumenta nesse período de tempo).  Se forem observadas uma taxa baixa e alta anormal, registre a taxa anormalmente alta.', NULL, 'Machine Translation', false),
	(88151, '2026-03-24 08:40:11.045472+00', 100504, 'spanish', 'Se refiere a la velocidad respiratoria en las respiraciones por minuto. Se prefiere el manual en lugar de la medición electrónica cuando sea posible (esto se logra contando el número de respiraciones durante un minuto, contando cuántas veces aumenta el cofre dentro de este período de tiempo).  Si se observa una tasa baja y alta anormal, registre la tasa anormalmente alta.', NULL, 'Machine Translation', false),
	(88152, '2026-03-24 08:40:11.045472+00', 100505, 'french', 'Entrez la fréquence respiratoire mesurée en respirations par minute. Enregistrez la valeur la plus éloignée de la plage normale entre 00h00 et 24h00 le jour de l''évaluation. Si à la fois un taux anormal bas et élevé observé, enregistrez le taux anormalement élevé.', NULL, 'Machine Translation', false),
	(88153, '2026-03-24 08:40:11.045472+00', 100505, 'portuguese', 'Digite a frequência respiratória medida em respirações por minuto. Registre o valor mais distante do intervalo normal entre 00:00 às 24:00 no dia da avaliação. Se forem observadas uma taxa baixa e alta anormal, registre a taxa anormalmente alta.', NULL, 'Machine Translation', false),
	(88154, '2026-03-24 08:40:11.045472+00', 100505, 'spanish', 'Ingrese la velocidad respiratoria medida en respiraciones por minuto. Registre el valor más lejos del rango normal entre las 00:00 a las 24:00 en el día de la evaluación. Si se observa una tasa baja y alta anormal, registre la tasa anormalmente alta.', NULL, 'Machine Translation', false),
	(88155, '2026-03-24 08:40:11.045472+00', 100506, 'french', 'BP systolique (MMHG)', NULL, 'Machine Translation', false),
	(88156, '2026-03-24 08:40:11.045472+00', 100506, 'portuguese', 'BP sistólica (MMHG)', NULL, 'Machine Translation', false),
	(88158, '2026-03-24 08:40:11.045472+00', 100507, 'french', 'Cela fait référence à la pression artérielle systolique de l''observation avec la pression artérielle moyenne la plus basse (si la pression artérielle moyenne n''a pas été calculée, signalez la mesure avec la pression artérielle systolique la plus basse).  Par exemple, si la pression artérielle est de 120/85 mmHg, entrez 120 dans la section marquée «BP systolique».', NULL, 'Machine Translation', false),
	(88159, '2026-03-24 08:40:11.045472+00', 100507, 'portuguese', 'Isso se refere à pressão arterial sistólica da observação com a menor pressão arterial média (se a pressão arterial média não tiver sido calculada, relate a medição com menor pressão arterial sistólica).  Por exemplo, se a pressão arterial for 120/85 mmHg, digite 120 na seção marcada como ''BP sistólica''.', NULL, 'Machine Translation', false),
	(88160, '2026-03-24 08:40:11.045472+00', 100507, 'spanish', 'Esto se refiere a la presión arterial sistólica de la observación con la presión arterial media más baja (si no se ha calculado la presión arterial media, informe la medición con la presión arterial sistólica más baja).  Por ejemplo, si la presión arterial es de 120/85 mmHg, ingrese 120 en la sección marcada ''BP sistólica''.', NULL, 'Machine Translation', false),
	(88161, '2026-03-24 08:40:11.045472+00', 100508, 'french', 'Entrez dans la pression artérielle systolique mesurée en millimètres de mercure (MMHg). Enregistrez la pression artérielle systolique de l''observation avec la pression artérielle moyenne la plus basse (MAP) (si la pression artérielle moyenne n''a pas été calculée, signalez la mesure avec la pression artérielle systolique la plus basse) qui s''est produite entre 00h00 et 24h00 le jour de l''évaluation .', NULL, 'Machine Translation', false),
	(88162, '2026-03-24 08:40:11.045472+00', 100508, 'portuguese', 'Entre na pressão arterial sistólica medida em milímetros de mercúrio (MMHG). Registre a pressão arterial sistólica da observação com a menor pressão arterial média (mapa) (se a pressão arterial média não tiver sido calculada, relate a medição com menor pressão arterial sistólica) que ocorreu entre 00:00 e 24:00 no dia da avaliação .', NULL, 'Machine Translation', false),
	(88163, '2026-03-24 08:40:11.045472+00', 100508, 'spanish', 'Ingrese la presión arterial sistólica medida en milímetros de mercurio (MMHG). Registre la presión arterial sistólica de la observación con la presión arterial media más baja (MAP) (si no se ha calculado la presión arterial media, informe la medición con la presión arterial sistólica más baja) que ocurrió entre las 00:00 a las 24:00 en el día de la evaluación .', NULL, 'Machine Translation', false),
	(88164, '2026-03-24 08:40:11.045472+00', 100509, 'french', 'BP diastolique (MMHG)', NULL, 'Machine Translation', false),
	(88165, '2026-03-24 08:40:11.045472+00', 100509, 'portuguese', 'BP diastólica (MMHG)', NULL, 'Machine Translation', false),
	(88166, '2026-03-24 08:40:11.045472+00', 100509, 'spanish', 'BP diastólico (MMHG)', NULL, 'Machine Translation', false),
	(88167, '2026-03-24 08:40:11.045472+00', 100510, 'french', 'Cela fait référence à la pression artérielle diastolique de l''observation avec la pression artérielle moyenne la plus basse (si la pression artérielle moyenne n''a pas été calculée, signalez la mesure avec la pression artérielle systolique la plus basse). Par exemple, si la pression artérielle est de 120/85 mmHg, entrez 85 dans la section marquée «BP diastolique».', NULL, 'Machine Translation', false),
	(88168, '2026-03-24 08:40:11.045472+00', 100510, 'portuguese', 'Isso se refere à pressão arterial diastólica da observação com a menor pressão arterial média (se a pressão arterial média não tiver sido calculada, relate a medição com menor pressão arterial sistólica). Por exemplo, se a pressão arterial for 120/85 mmHg, digite 85 na seção marcada ''BP diastólica''.', NULL, 'Machine Translation', false),
	(88169, '2026-03-24 08:40:11.045472+00', 100510, 'spanish', 'Esto se refiere a la presión arterial diastólica de la observación con la presión arterial media más baja (si no se ha calculado la presión arterial media, informe la medición con la presión arterial sistólica más baja). Por ejemplo, si la presión arterial es de 120/85 mmHg, ingrese 85 en la sección marcada ''BP diastólico''.', NULL, 'Machine Translation', false),
	(88170, '2026-03-24 08:40:11.045472+00', 100511, 'french', 'Entrez dans la pression artérielle diastolique mesurée en millimètres de mercure (MMHg). Enregistrez la pression artérielle diastolique de l''observation avec la pression artérielle moyenne la plus basse (MAP) (si la pression artérielle moyenne n''a pas été calculée, signalez la mesure avec la pression artérielle systolique la plus faible) qui s''est produite entre 00h00 et 24h00 le jour de l''évaluation .', NULL, 'Machine Translation', false),
	(88171, '2026-03-24 08:40:11.045472+00', 100511, 'portuguese', 'Entre na pressão arterial diastólica medida em milímetros de mercúrio (MMHG). Registre a pressão arterial diastólica da observação com a menor pressão arterial média (mapa) (se a pressão arterial média não tiver sido calculada, relate a medição com menor pressão arterial sistólica) que ocorreu entre 00:00 e 24:00 no dia da avaliação .', NULL, 'Machine Translation', false),
	(88172, '2026-03-24 08:40:11.045472+00', 100511, 'spanish', 'Ingrese la presión arterial diastólica medida en milímetros de mercurio (MMHG). Registre la presión arterial diastólica de la observación con la presión arterial media más baja (MAP) (si no se ha calculado la presión arterial media, informe la medición con la presión arterial sistólica más baja) que ocurrió entre las 00:00 a las 24:00 en el día de la evaluación .', NULL, 'Machine Translation', false),
	(88173, '2026-03-24 08:40:11.045472+00', 100512, 'french', 'Pression artérielle moyenne (MMHG)', NULL, 'Machine Translation', false),
	(88174, '2026-03-24 08:40:11.045472+00', 100512, 'portuguese', 'Pressão arterial média (MMHG)', NULL, 'Machine Translation', false),
	(88175, '2026-03-24 08:40:11.045472+00', 100512, 'spanish', 'Presión arterial media (MMHG)', NULL, 'Machine Translation', false),
	(88176, '2026-03-24 08:40:11.045472+00', 100513, 'french', 'La pression artérielle moyenne (MAP) peut être directement mesurée (via le cathéter intra-artériel) ou être approximée sans procédure invasive en utilisant la formule suivante: Pression diastolique plus 1/3 de la pression du pouls, où la pression d''impulsion est la pression systolique - pression diastolique .', NULL, 'Machine Translation', false),
	(88177, '2026-03-24 08:40:11.045472+00', 100513, 'portuguese', 'A pressão arterial média (mapa) pode ser medida diretamente (por cateter intra -arterial) ou ser aproximado sem um procedimento invasivo usando a seguinte fórmula: pressão diastólica mais 1/3 da pressão do pulso, onde a pressão do pulso é pressão sistólica - pressão diastólica .', NULL, 'Machine Translation', false),
	(88178, '2026-03-24 08:40:11.045472+00', 100513, 'spanish', 'La presión arterial media (MAP) puede medirse directamente (a través del catéter intraarterial) o aproximarse sin un procedimiento invasivo utilizando la siguiente fórmula: presión diastólica más 1/3 de la presión del pulso, donde la presión del pulso es la presión sistólica - presión diastólica .', NULL, 'Machine Translation', false),
	(88179, '2026-03-24 08:40:11.045472+00', 100514, 'french', 'Entrez la carte enregistrée la plus basse qui s''est produite entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88180, '2026-03-24 08:40:11.045472+00', 100514, 'portuguese', 'Digite o mapa mais baixo registrado que ocorreu entre 00:00 e 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88181, '2026-03-24 08:40:11.045472+00', 100514, 'spanish', 'Ingrese el mapa más bajo registrado que ocurrió entre las 00:00 a las 24:00 el día de la evaluación.', NULL, 'Machine Translation', false),
	(88182, '2026-03-24 08:40:11.045472+00', 100515, 'french', 'La plus faible saturation en oxygène SPO2 (%)', NULL, 'Machine Translation', false),
	(88183, '2026-03-24 08:40:11.045472+00', 100515, 'portuguese', 'A menor saturação de oxigênio SPO2 (%)', NULL, 'Machine Translation', false),
	(88184, '2026-03-24 08:40:11.045472+00', 100515, 'spanish', 'La saturación de oxígeno más baja SPO2 (%)', NULL, 'Machine Translation', false),
	(88185, '2026-03-24 08:40:11.045472+00', 100516, 'french', 'Cela fait référence à la saturation en oxygène, qui peut être mesurée par oxymétrie de pouls ou par analyse du gaz sanguin artériel. Il est indépendamment de la ventilation ou des besoins supplémentaires d''oxygène.', NULL, 'Machine Translation', false),
	(88186, '2026-03-24 08:40:11.045472+00', 100516, 'portuguese', 'Isso se refere à saturação de oxigênio, que pode ser medida por oximetria de pulso ou por análise de gás sanguíneo arterial. É independente da ventilação ou requisito suplementar de oxigênio.', NULL, 'Machine Translation', false),
	(88187, '2026-03-24 08:40:11.045472+00', 100516, 'spanish', 'Esto se refiere a la saturación de oxígeno, que puede medirse por oximetría de pulso o mediante análisis de gases en sangre arterial. Es independientemente de la ventilación o el requisito de oxígeno suplementario.', NULL, 'Machine Translation', false),
	(88188, '2026-03-24 08:40:11.045472+00', 100517, 'french', 'Entrez le pourcentage de saturation en oxygène. Enregistrez la valeur la plus éloignée de la plage normale entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(88189, '2026-03-24 08:40:11.045472+00', 100517, 'portuguese', 'Digite a porcentagem de saturação de oxigênio. Registre o valor mais distante do intervalo normal entre 00:00 às 24:00 no dia da avaliação.', NULL, 'Machine Translation', false),
	(88190, '2026-03-24 08:40:11.045472+00', 100517, 'spanish', 'Ingrese el porcentaje de saturación de oxígeno. Registre el valor más lejos del rango normal entre las 00:00 a las 24:00 en el día de la evaluación.', NULL, 'Machine Translation', false),
	(88191, '2026-03-24 08:40:11.045472+00', 100518, 'french', 'Oxygène supplémentaire au point de SPO2 mesuré', NULL, 'Machine Translation', false),
	(88192, '2026-03-24 08:40:11.045472+00', 100518, 'portuguese', 'Oxigênio suplementar no ponto de Spo2 medido', NULL, 'Machine Translation', false),
	(88193, '2026-03-24 08:40:11.045472+00', 100518, 'spanish', 'Oxígeno suplementario en el punto de SPO2 medido', NULL, 'Machine Translation', false),
	(88194, '2026-03-24 08:40:11.045472+00', 100519, 'french', 'Cela fait référence à la fraction mesurée de l''oxygène inspiré (FIO2) livré au moment de l''enregistrement de Spo2 (%) le plus bas (%) le plus bas.', NULL, 'Machine Translation', false),
	(88195, '2026-03-24 08:40:11.045472+00', 100519, 'portuguese', 'Isso se refere à fração medida do oxigênio inspirado (FIO2) entregue no momento do acima, o SPO2 mais baixo (%), gravação.', NULL, 'Machine Translation', false),
	(88196, '2026-03-24 08:40:11.045472+00', 100519, 'spanish', 'Esto se refiere a la fracción medida de oxígeno inspirado (FIO2) entregado en el momento de la registro anterior de SPO2 (%) más bajo.', NULL, 'Machine Translation', false),
	(88197, '2026-03-24 08:40:11.045472+00', 100520, 'french', 'Indiquez «oui», si la FIO2 a été mesurée le long de la saturation en oxygène la plus faible (SPO2) signalée ci-dessus.', NULL, 'Machine Translation', false),
	(88198, '2026-03-24 08:40:11.045472+00', 100520, 'portuguese', 'Indique ''sim'', se o FIO2 foi medido ao longo do lado, a menor saturação de oxigênio (SPO2) relatada acima.', NULL, 'Machine Translation', false),
	(88199, '2026-03-24 08:40:11.045472+00', 100520, 'spanish', 'Indique ''sí'', si el FIO2 se midió en el lado de la saturación de oxígeno más baja (SPO2) informada anteriormente.', NULL, 'Machine Translation', false),
	(88200, '2026-03-24 08:40:11.045472+00', 100521, 'french', 'FIO2 au moment de la plus basse Spo2 (unités sélectionnées)', NULL, 'Machine Translation', false),
