	(88679, '2026-03-24 08:40:11.045472+00', 100688, 'spanish', 'Conciencia / confusión alterada', NULL, 'Machine Translation', false),
	(88680, '2026-03-24 08:40:11.045472+00', 100689, 'french', 'Défini comme un niveau de conscience ou d''excitation autre que la ligne de base normale du patient.', NULL, 'Machine Translation', false),
	(88681, '2026-03-24 08:40:11.045472+00', 100689, 'portuguese', 'Definido como um nível de conscientização ou excitação diferente da linha de base normal do paciente.', NULL, 'Machine Translation', false),
