	(88865, '2026-03-24 08:40:11.045472+00', 100750, 'spanish', 'Indique ''sí'', para ingresar información relacionada con la inspección clínica de las lesiones cutáneas el día de la evaluación.', NULL, 'Machine Translation', false),
	(88866, '2026-03-24 08:40:11.045472+00', 100751, 'french', 'Éruption cutanée', NULL, 'Machine Translation', false),
