	(90018, '2026-03-24 08:40:11.045472+00', 101169, 'french', 'L''APTR est le rapport de thromboplastine partielle activé. Le résultat est un rapport et n''a donc pas d''unités.', NULL, 'Machine Translation', false),
	(90020, '2026-03-24 08:40:11.045472+00', 101169, 'spanish', 'APTR es la relación de tromboplastina parcial activada. El resultado es una relación y, por lo tanto, no tiene unidades.', NULL, 'Machine Translation', false),
