	(90297, '2026-03-24 08:40:11.045472+00', 101265, 'french', 'Test de grossesse', NULL, 'Machine Translation', false),
	(90298, '2026-03-24 08:40:11.045472+00', 101265, 'portuguese', 'Teste de gravidez', NULL, 'Machine Translation', false),
	(90299, '2026-03-24 08:40:11.045472+00', 101265, 'spanish', 'Prueba de embarazo', NULL, 'Machine Translation', false),
	(90300, '2026-03-24 08:40:11.045472+00', 101266, 'french', 'Cela fait référence aux tests pour déterminer si une personne est enceinte ou non. Ils comprennent des tests à base d''urine ou d''urine pour déterminer la présence de gonadotrophine chorionique humaine (HCG).', NULL, 'Machine Translation', false),
	(90301, '2026-03-24 08:40:11.045472+00', 101266, 'portuguese', 'Isso se refere a testes para determinar se um indivíduo está grávida ou não. Eles incluem testes baseados em soro ou urina para determinar a presença de gonadotrofina coriônica humana (HCG).', NULL, 'Machine Translation', false),
	(90302, '2026-03-24 08:40:11.045472+00', 101266, 'spanish', 'Esto se refiere a las pruebas para determinar si un individuo está embarazada o no. Incluyen pruebas basadas en suero o orina para determinar la presencia de gonadotropina coriónica humana (HCG).', NULL, 'Machine Translation', false),
	(90303, '2026-03-24 08:40:11.045472+00', 101267, 'french', 'Indiquez le résultat du test de grossesse.', NULL, 'Machine Translation', false),
	(90304, '2026-03-24 08:40:11.045472+00', 101267, 'portuguese', 'Indique o resultado do teste de gravidez.', NULL, 'Machine Translation', false),
	(90305, '2026-03-24 08:40:11.045472+00', 101267, 'spanish', 'Indique el resultado de la prueba de embarazo.', NULL, 'Machine Translation', false),
	(90306, '2026-03-24 08:40:11.045472+00', 101268, 'french', 'Sérologie du VIH (une fois seulement)', NULL, 'Machine Translation', false),
	(90307, '2026-03-24 08:40:11.045472+00', 101268, 'portuguese', 'Sorologia do HIV (apenas uma vez)', NULL, 'Machine Translation', false),
	(90308, '2026-03-24 08:40:11.045472+00', 101268, 'spanish', 'Serología del VIH (una vez solo)', NULL, 'Machine Translation', false),
	(90309, '2026-03-24 08:40:11.045472+00', 101269, 'french', 'Cela fait référence au résultat des tests de sérologie du virus de l''immunodéficience humaine.', NULL, 'Machine Translation', false),
	(90310, '2026-03-24 08:40:11.045472+00', 101269, 'portuguese', 'Isso se refere ao resultado de testes de sorologia do vírus da imunodeficiência humana.', NULL, 'Machine Translation', false),
	(90311, '2026-03-24 08:40:11.045472+00', 101269, 'spanish', 'Esto se refiere al resultado de pruebas de serología de virus de inmunodeficiencia humana.', NULL, 'Machine Translation', false),
	(90312, '2026-03-24 08:40:11.045472+00', 101270, 'french', 'Indiquez le résultat des tests de sérologie du virus de l''immunodéficience humaine.', NULL, 'Machine Translation', false),
	(90313, '2026-03-24 08:40:11.045472+00', 101270, 'portuguese', 'Indique o resultado do teste de sorologia do vírus da imunodeficiência humana.', NULL, 'Machine Translation', false),
