	(90537, '2026-03-24 08:40:11.045472+00', 101350, 'french', 'Cela fait référence à la pression partielle du dioxyde de carbone mesuré dans le sang artériel enregistré dans les MMHg.', NULL, 'Machine Translation', false),
	(90538, '2026-03-24 08:40:11.045472+00', 101350, 'portuguese', 'Isso se refere à pressão parcial do dióxido de carbono medido no sangue arterial registrado no MMHG.', NULL, 'Machine Translation', false),
	(90539, '2026-03-24 08:40:11.045472+00', 101350, 'spanish', 'Esto se refiere a la presión parcial del dióxido de carbono medido en la sangre arterial registrada en MMHG.', NULL, 'Machine Translation', false),
	(90540, '2026-03-24 08:40:11.045472+00', 101351, 'french', 'Écrivez le PACO2 (MMHG). S''il y a plusieurs, signalez les mesures du gaz sanguin avec le pH le plus bas (le plus acidotique) entre 00h00 et 24h00 le jour de l''évaluation.', NULL, 'Machine Translation', false),
	(90541, '2026-03-24 08:40:11.045472+00', 101351, 'portuguese', 'Escreva o Paco2 (MMHG). Se houver múltipla, relate as medidas do gás sanguíneo com o pH mais baixo (mais ácido) entre 00:00 e 24:00 horas no dia da avaliação.', NULL, 'Machine Translation', false),
	(90542, '2026-03-24 08:40:11.045472+00', 101351, 'spanish', 'Escribe el Paco2 (MMHG). Si hay múltiples, informe las medidas del gas en sangre con el pH más bajo (más acidótico) entre las 00:00 y las 24:00 horas el día de la evaluación.', NULL, 'Machine Translation', false),
