	(91123, '2026-03-24 08:40:11.045472+00', 101573, 'portuguese', 'Número total de dias de tratamento fornecido', NULL, 'Machine Translation', false),
	(91124, '2026-03-24 08:40:11.045472+00', 101573, 'spanish', 'Número total de días de tratamiento dado', NULL, 'Machine Translation', false),
	(91125, '2026-03-24 08:40:11.045472+00', 101574, 'french', 'Cela fait référence au nombre total de jours pour lesquels une dose a été reçue ou invitée à prendre en charge la prescription de décharge.', NULL, 'Machine Translation', false),
	(91126, '2026-03-24 08:40:11.045472+00', 101574, 'portuguese', 'Isso se refere ao número total de dias para os quais uma dose foi recebida ou instruída a assumir a prescrição de alta.', NULL, 'Machine Translation', false),
	(91127, '2026-03-24 08:40:11.045472+00', 101574, 'spanish', 'Esto se refiere al número total de días para los cuales se recibió o se le indicó a una dosis de tomar la prescripción de alta.', NULL, 'Machine Translation', false),
	(91128, '2026-03-24 08:40:11.045472+00', 101575, 'french', 'Entrez le nombre total de jours pour lesquels une dose a été reçue ou a demandé de prendre la prescription de décharge.', NULL, 'Machine Translation', false),
	(91129, '2026-03-24 08:40:11.045472+00', 101575, 'portuguese', 'Digite o número total de dias para os quais uma dose foi recebida ou instruída a assumir a prescrição de alta.', NULL, 'Machine Translation', false),
	(91130, '2026-03-24 08:40:11.045472+00', 101575, 'spanish', 'Ingrese el número total de días para los cuales se recibió o se le indicó a una dosis de tomar la prescripción de alta.', NULL, 'Machine Translation', false),
	(91131, '2026-03-24 08:40:11.045472+00', 101576, 'french', 'Fréquence', NULL, 'Machine Translation', false),
