	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_rtt_dur}', 'definition', 'This refers to the total number of days the patient received RRT or dialysis at any time during this admission.', NULL, 99309),
	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_rtt_dur}', 'completionGuide', 'Write the total number of calendar days the patient received RRT or dialysis at any time during this admission. Even if the patient received this more than once in one calendar day (i.e. between 00:00 and 24:00 hours), this counts as one to the total number of days.', NULL, 99310),
	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_inotropesv}', 'question', 'Inotropes / vasopressors', '{Yes,No,Unknown}', 99311),
	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_inotropesv}', 'definition', 'This refers to continuous use of a vasopressor or inotrope for at least one hour. Agents include norepinephrine, epinephrine, vasopressin, terlipressin and phenylephrine. Commonly used ''positive'' inotropes include dobutamine, dopamine, milrinone and adrenaline (epinephrine).', NULL, 99312),
	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_inotropesv}', 'completionGuide', 'Indicate ''Yes'', if the patient received Inotropes / vasopressors for at least one hour at any time during hospitalisation.', NULL, 99313),
	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_inotropesv_dur}', 'question', 'Total inotropes / vasopressor duration during admission (days)', NULL, 99314),
	('2026-03-24 08:18:45.374493+00', '{ARC,outcome,"CRITICAL CARE INTERVENTIONS: Record all critical care interventions given from day of presentation to day of discharge / outcome.",crito_inotropesv_dur}', 'definition', 'The refers to the total number of days during this admission that the patient received inotropic/vasoactive therapy.', NULL, 99315),
