	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_immunusupp_type}', 'definition', 'This refers to a patient who is known to have taken prescribed medications that are known to have an immunosuppressing effect (excluding steroids/corticosteroids). Topical preparations should not be recorded.', NULL, 99995),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_immunusupp_type}', 'completionGuide', 'Indicate ''Yes'', if the patient has taken an immunosuppressant agent in the 7 days prior to this most recent admission / presentation', NULL, 99996),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_antibiotic}', 'question', 'Antibiotics', '{Yes,No,Unknown}', 99997),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_antibiotic}', 'definition', 'Antibiotic'' refers to any agent(s) that selectively target bacteria.  Topical preparations should not be recorded.', NULL, 99998),
