	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_nsaid}', 'question', 'NSAIDs', '{Yes,No,Unknown}', 100003),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_nsaid}', 'definition', 'Non-steroidal anti-inflammatory drugs or NSAIDs refers to any agent that is not a corticosteroid and has potential anti-inflammatory, analgesic, antipyretic and anti-platelet activities. Topical preparations should not be recorded.', NULL, 100004),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_nsaid}', 'completionGuide', 'Indicate ''Yes'', if the patient has taken an NSAID in the 7 days prior to this most recent admission / presentation', NULL, 100005),
