	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_anticoagul}', 'question', 'Anticoagulant', '{Yes,No,Unknown}', 100009),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_anticoagul}', 'definition', 'An anticoagulant refers to any agent capable of preventing blood clot formation, or platelet aggregation. This includes agents such as heparin, warfarin, aspirin, clopidogrel, and subcutaneously administered anticoagulants, among many others. Topical preparations are not included.', NULL, 100010),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_anticoagul}', 'completionGuide', 'Indicate ''Yes'', if the patient has taken an anticoagulant in the 7 days prior to this most recent admission / presentation.', NULL, 100011),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_anticoagul_type}', 'question', 'Anticoagulant', NULL, 100012),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_anticoagul_type}', 'definition', 'An anticoagulant refers to any agent capable of preventing blood clot formation, or platelet aggregation. This includes agents such as heparin, warfarin, aspirin, clopidogrel, and subcutaneously administered anticoagulants, among many others. Topical preparations are not included.', NULL, 100013),
