	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_ivfluid_vol2}', 'question', 'Total intravenous fluid volume in the previous 24 hours (mL)', NULL, 100042),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_ivfluid_vol2}', 'definition', 'Parenteral or intravenous (IV) fluid is prescribed as a replacement of fluid, electrolytes, calories, vitamins, and other nutritional substances. Intravenous fluids may be used for rehydration, maintenance requirements or resuscitation.', NULL, 100043),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_ivfluid_vol2}', 'completionGuide', 'Specify the total volume of theadditional intravenous fluid received by the patient  (not recorded above) in the 7 days prior to this most recent admission / presentation.. Record the volume in millilitres (mL).', NULL, 100044),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_unlisted}', 'question', 'Other pathogen-targeted medications', '{Yes,No,Unknown}', 100045),
	('2026-03-24 08:40:04.3022+00', '{ARC,drug7_unlisted}', 'completionGuide', 'Indicate ''Yes'', if pathogen-targeted medications (other than those specified above) have been taken in the 7 days prior to this most recent admission / presentation.', NULL, 100046),
