	('2026-03-24 08:40:04.3022+00', '{ARC,vacci_covid19}', 'question', 'COVID 19', NULL, 100101),
	('2026-03-24 08:40:04.3022+00', '{ARC,vacci_covid19_yn}', 'question', 'Vaccinated for COVID-19 (ever)', '{Yes,No,Unknown}', 100102),
	('2026-03-24 08:40:04.3022+00', '{ARC,vacci_covid19_yn}', 'definition', 'Ever received a vaccine targeted against SARS-Cov-2. Examples include Spikevax (Moderna), Comirnaty (Pfizer/BioNTech), Nuvaxovid (Novavax), Vaxzevria (AstraZeneca/Oxford), Janssen COVID-19 Vaccine (Johnson & Johnson), Valneva (Valneva).', NULL, 100103),
	('2026-03-24 08:40:04.3022+00', '{ARC,vacci_covid19_yn}', 'completionGuide', 'Indicate ''Yes'', if the patient has ever received a vaccine targetted against SARS-Cov-2', NULL, 100104),
