	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_ageusia}', 'definition', 'This refers to patient reported and/or clinician-diagnosed loss of taste function of the tongue.', NULL, 100271),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_ageusia}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this at any time during the date of assessment.', NULL, 100272),
