	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_skinrash}', 'question', 'Skin rash', '{Yes,No,Unknown}', 100282),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_skinrash}', 'definition', 'Defined as any change in the skin which affects its appearance or texture. A rash may be localized to one part of the body or affect all the skin. Rashes may cause the skin to change colour, itch, become warm, bumpy, dry, cracked, or blistered, swell and may be painful.', NULL, 100283),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_skinrash}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced this at any time from onset of this illness to presentation. ', NULL, 100284),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_skinrash_loc}', 'question', 'Site where rash first occurred', '{Skin,Skin,Mucosa,Mucosa,Mouth,"Perianal skin",Rectum,Unknown,Other}', 100285),
