	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_pruritus}', 'question', 'Itch / pruritus', '{Yes,No,Unknown}', 100294),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_pruritus}', 'definition', 'Defined as an unpleasant or intense itching sensation that produces the urge to rub or scratch the skin to obtain relief. Itching is an irritating sensation that makes you want to scratch your skin.', NULL, 100295),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_pruritus}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced this at any time from onset of this illness to presentation. ', NULL, 100296),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_mobilchg}', 'question', 'Change in mobility from baseline', '{Yes,No,Unknown}', 100297),
