	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough}', 'question', 'Cough', '{Yes,No,Unknown}', 100303),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough}', 'definition', 'This refers to the presence of a cough and its characteristics. A productive cough refers to a cough accompanied by expectorated secretions (phlegm or mucus), while a non-productive cough refers to one which is not accompanied by expectorated secretions. Haemoptysis refers to the presence of blood or blood-streaked sputum from the respiratory tract.', NULL, 100304),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced this at any time from onset of this illness to presentation. ', NULL, 100305),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_nonprod}', 'question', 'Non-productive', '{Yes,No,Unknown}', 100306),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_nonprod}', 'definition', 'A non-productive cough refers to one which is not accompanied by expectorated secretions.', NULL, 100307),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_nonprod}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced this at any time from onset of this illness to presentation. ', NULL, 100308),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_prod}', 'question', 'Productive', '{Yes,No,Unknown}', 100309),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_prod}', 'definition', 'A productive cough refers to a cough accompanied by expectorated secretions (phlegm or mucus)', NULL, 100310),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_prod}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced this at any time from onset of this illness to presentation. ', NULL, 100311),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_hemop}', 'question', 'Hemoptysis', '{Yes,No,Unknown}', 100312),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_hemop}', 'definition', 'Haemoptysis refers to the presence of blood or blood-streaked sputum from the respiratory tract.', NULL, 100313),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_cough_hemop}', 'completionGuide', 'Indicate ''Yes'', if the patient has experienced this at any time from onset of this illness to presentation. ', NULL, 100314),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_palpitations}', 'question', 'Palpitations', '{Yes,No,Unknown}', 100315),
	('2026-03-24 08:40:04.3022+00', '{ARC,adsym_palpitations}', 'definition', 'Refers to the unpleasant awareness of one''s own heartbeat.', NULL, 100316),
