	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_retroorbit}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 100684),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_seizconv}', 'question', 'Seizures / convulsions', '{Yes,No,Unknown}', 100685),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_seizconv}', 'definition', 'Defined as an intermittent abnormality of nervous system physiology characterised by a transient occurrence of sudden, violent, irregular movement of the body, caused by involuntary contraction of muscles due to abnormal excessive or synchronous neuronal activity in the brain.', NULL, 100686),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_seizconv}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 100687),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_confusion}', 'question', 'Altered consciousness / confusion', '{Yes,No,Unknown}', 100688),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_confusion}', 'definition', 'Defined as a level of awareness or arousal other than the patient''s normal baseline.', NULL, 100689),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_confusion}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 100690),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_neurodist}', 'question', 'Psychological disturbance', '{Yes,No,Unknown}', 100691),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_neurodist}', 'definition', 'This refers to the presence of signs or symptoms that affect an individual''s thoughts, emotions, behaviours or mental well-being. The presence of psychological disturbances should be identified through a Mental Status Examination (MSE) or equivalent tool.', NULL, 100692),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_neurodist}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 100693),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_cerebesig}', 'question', 'Cerebellar signs', '{Yes,No}', 100694),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_cerebesig}', 'definition', 'Refers to the presence of a constellation of neurological signs typically indicate cerebellar dysfunction. Signs include dysdiadochokinesia, dysmetria, ataxia, nystagmus, intention tremor, slurred or scanning speech, hypotonia.', NULL, 100695),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_cerebesig}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 100696),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_tremor}', 'question', 'Tremor', '{Yes,No}', 100697),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_tremor}', 'definition', 'Refers to an unintentional, oscillating to-and-fro muscle movement about a joint axis.', NULL, 100698),
	('2026-03-24 08:40:04.3022+00', '{ARC,sympt_tremor}', 'completionGuide', 'Indicate ''Yes'', if the patient experienced this between 00:00 to 24:00 on day of assessment.', NULL, 100699),
