	('2026-03-24 08:40:04.3022+00', '{ARC,lesion_desc}', 'completionGuide', 'Describe other lesion complication(s) that occurred or were first identified between 00:00 to 24:00 on day of assessment, that have not been specified above.', NULL, 100948),
	('2026-03-24 08:40:04.3022+00', '{ARC,daily_datatreat}', 'question', 'Enter Treatments & Interventions data for this date?', '{Yes,No}', 100949),
	('2026-03-24 08:40:04.3022+00', '{ARC,daily_datatreat}', 'definition', 'This section refers to treatments or interventions that are typically conducted and recorded in the emergency room and/or the ward or acute medical unit to which the patient was admitted between 00:00 and 24:00 hours on day of assessment.', NULL, 100950),
