	('2026-03-24 08:40:04.3022+00', '{ARC,treat_fluid_yn}', 'question', 'Any fluids prescribed', '{Yes,No,Unknown}', 100953),
	('2026-03-24 08:40:04.3022+00', '{ARC,treat_fluid_yn}', 'definition', 'This refers to any prescribed fluids (oral, or parenteral/intravenous), excluding those the patient consumes in a non-prescribed dietary manner.', NULL, 100954),
	('2026-03-24 08:40:04.3022+00', '{ARC,treat_fluid_yn}', 'completionGuide', 'Indicate ''Yes'', if the patient was prescribed and received fluids between 00:00 and 24:00 hours on day of assessment.', NULL, 100955),
