	('2026-03-24 08:40:04.3022+00', '{ARC,treat_fluid_oral}', 'definition', 'This refers to enteral/oral fluids for the purposes of rehydration.', NULL, 100957),
	('2026-03-24 08:40:04.3022+00', '{ARC,treat_fluid_oral}', 'completionGuide', 'Indicate ''Yes'', if the patient received oral rehydration between 00:00 and 24:00 hours on day of assessment.', NULL, 100958),
