	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"Form Label"}', 'formLabel', 'pregnancy', NULL, 103173),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS","Section Label"}', 'sectionLabel', 'PREGNANCY DETAILS', NULL, 103174),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",preg_form}', 'question', 'Complete this form only for pregnant patients, postpartum patients (≤28 days after delivery), or neonates whose mothers are not included in the study.', NULL, 103175),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",preg_form}', 'definition', 'Calendar date (DD–MM–YYYY) on which the CRF was completed.', NULL, 103176),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",preg_date}', 'question', 'Date of form completion', NULL, 103177),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_medirep}', 'question', 'Medically assisted reproduction?', '{Yes,No,Unknown}', 103178),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_medirep}', 'definition', 'This refers to medical procedures used primarily to address infertility.', NULL, 103179),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_edd}', 'question', 'Estimated date of delivery (EDD)', NULL, 103180),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_edd}', 'definition', 'This refers to the expected date on which a pregnant woman will give birth. If not available, provide LMP below if possible', NULL, 103181),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_lmp}', 'question', 'Date of last menstrual period (LMP)', NULL, 103182),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_lmp}', 'definition', 'This refers to the date of the first day of the most recent menstrual cycle.', NULL, 103183),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_parity}', 'question', 'Parity', NULL, 103184),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_parity}', 'definition', 'This refers to the number of pregnancies that have progressed to a viable gestational age (usually ≥20 weeks), regardless of whether the infant was born alive or stillborn. Multiple births (e.g., twins) from a single pregnancy are counted as one parity event.', NULL, 103185),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_gravidity}', 'question', 'Gravidity', NULL, 103186),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_gravidity}', 'definition', 'This refer to the total number of times a woman has been pregnant, regardless of the outcome of the pregnancies. This includes current pregnancy, miscarriages, abortions, ectopic pregnancies, and stillbirths.', NULL, 103187),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_prevcs}', 'question', 'Number of previous surgical (caesarean section) deliveries.', NULL, 103188),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_prevcs}', 'definition', 'This refers to the number of previous surgical deliveries of one or more intrauterine fetuses though an abdominal incision (cesaerian section).', NULL, 103189),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_fetnum}', 'question', 'Number of embryos/foetuses in this pregnancy.', NULL, 103190),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,"PREGNANCY DETAILS",pregdet_fetnum}', 'definition', 'This refers to the number of embryos/fetuses in this pregnancy', NULL, 103191),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,"Section Label"}', 'sectionLabel', 'PREGNANCY-COMORBIDITIES', NULL, 103192),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_comor}', 'question', 'Co-morbidities during the current pregnancy', '{Yes,No,Unknown}', 103193),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_comor}', 'definition', 'Pre-existing or pregnancy-related medical conditions present at any time during the current pregnancy that may affect maternal or fetal health.', NULL, 103194),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_diabetes}', 'question', 'Diabetes', '{Yes,No,Unknown}', 103195),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_diabetes}', 'definition', 'Disordered glucose metabolism present during the current pregnancy, including pre-existing type 1 or type 2 diabetes mellitus or diabetes first diagnosed during pregnancy (gestational diabetes).', NULL, 103196),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_obesity}', 'question', 'Obesity', '{Yes,No,Unknown}', 103197),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_obesity}', 'definition', 'A maternal condition defined by a pre-pregnancy or early pregnancy body mass index (BMI) of ≥30 kg/m².', NULL, 103198),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_hypertension}', 'question', 'Hypertension', '{Yes,No,Unknown}', 103199),
	('2026-04-20 13:35:28.186514+00', '{ARC,pregnancy,PREGNANCY-COMORBIDITIES,preg_hypertension}', 'definition', 'Elevated blood pressure (≥140/90 mmHg) present during the current pregnancy, whether pre-existing or diagnosed during pregnancy', NULL, 103200),
