	(92507, '2026-03-24 08:40:11.045472+00', 102056, 'spanish', 'Esto se refiere a la fecha de primera admisión a la UCI (o unidad de nivel similar).', NULL, 'Machine Translation', false),
	(92508, '2026-03-24 08:40:11.045472+00', 102057, 'french', 'Entrez la date au format DD / mm / Yyyy.', NULL, 'Machine Translation', false),
	(92509, '2026-03-24 08:40:11.045472+00', 102057, 'portuguese', 'Digite a data no formato dd/mm/yyyy.', NULL, 'Machine Translation', false),
	(92510, '2026-03-24 08:40:11.045472+00', 102057, 'spanish', 'Ingrese la fecha en formato DD/mm/aa yyyy.', NULL, 'Machine Translation', false),
	(92511, '2026-03-24 08:40:11.045472+00', 102058, 'french', 'Durée de l''unité de soins intensifs finaux / UTU / HDU / Unité de soins intermédiaires (jours)', NULL, 'Machine Translation', false),
	(92512, '2026-03-24 08:40:11.045472+00', 102058, 'portuguese', 'Duração da UTI / ITU / HDU / ITU / HDU / HDU / Intermediário Admission (Days)', NULL, 'Machine Translation', false),
	(92513, '2026-03-24 08:40:11.045472+00', 102058, 'spanish', 'Duración de la UCI final de la UCI / ITU / HDU / Intermediate Care Unit Admission (Days)', NULL, 'Machine Translation', false),
	(92514, '2026-03-24 08:40:11.045472+00', 102059, 'french', 'Il s''agit de la durée totale de l''admission finale à l''USI (ou unité de niveau similaire).', NULL, 'Machine Translation', false),
	(92515, '2026-03-24 08:40:11.045472+00', 102059, 'portuguese', 'Isso se refere à duração total da admissão final na UTI (ou unidade de nível semelhante).', NULL, 'Machine Translation', false),
	(92516, '2026-03-24 08:40:11.045472+00', 102059, 'spanish', 'Esto se refiere a la duración total de la admisión final a la UCI (o unidad de nivel similar).', NULL, 'Machine Translation', false),
	(92517, '2026-03-24 08:40:11.045472+00', 102060, 'french', 'Écrivez le nombre total de jours civils le patient a été admis aux soins intensifs.', NULL, 'Machine Translation', false),
	(92518, '2026-03-24 08:40:11.045472+00', 102060, 'portuguese', 'Escreva o número total de dias de calendário em que o paciente foi admitido na UTI.', NULL, 'Machine Translation', false),
	(92519, '2026-03-24 08:40:11.045472+00', 102060, 'spanish', 'Escriba el número total de días calendario que el paciente fue ingresado en la UCI.', NULL, 'Machine Translation', false),
	(92520, '2026-03-24 08:40:11.045472+00', 102061, 'french', 'Agents de blocage neuromusculaires', NULL, 'Machine Translation', false),
	(92521, '2026-03-24 08:40:11.045472+00', 102061, 'portuguese', 'Agentes de bloqueio neuromuscular', NULL, 'Machine Translation', false),
	(92522, '2026-03-24 08:40:11.045472+00', 102061, 'spanish', 'Agentes de bloqueo neuromuscular', NULL, 'Machine Translation', false),
	(92523, '2026-03-24 08:40:11.045472+00', 102062, 'french', 'Cela fait référence à l''utilisation de bloqueurs neuromusculaires. Les exemples incluent l''atracurium, le cisatracurium, le nimbex, le norcuron, le pancuronium, le pavulon, le rocuronium, le tracrium, le vecuronium, le zémuron.', NULL, 'Machine Translation', false),
	(92524, '2026-03-24 08:40:11.045472+00', 102062, 'portuguese', 'Isso se refere ao uso de bloqueadores neuromusculares. Exemplos incluem Atracurium, Cisatracurium, Nimbex, Norcuron, Pancurônio, Pavulon, Rocurônio, Trácrio, Vecurônio, Zemuron.', NULL, 'Machine Translation', false),
	(92525, '2026-03-24 08:40:11.045472+00', 102062, 'spanish', 'Esto se refiere al uso de bloqueadores neuromusculares. Los ejemplos incluyen atracurium, cisatracurium, nimbex, norcurón, pancuronio, pavulón, rocuronio, tracrium, vecuronio, zemurón.', NULL, 'Machine Translation', false),
	(92526, '2026-03-24 08:40:11.045472+00', 102063, 'french', 'Indiquez «oui», si des bloqueurs neuromusculaires étaient utilisés à tout moment pendant cette admission.', NULL, 'Machine Translation', false),
	(92527, '2026-03-24 08:40:11.045472+00', 102063, 'portuguese', 'Indique ''sim'', se os bloqueadores neuromusculares foram usados ​​a qualquer momento durante essa admissão.', NULL, 'Machine Translation', false),
	(92528, '2026-03-24 08:40:11.045472+00', 102063, 'spanish', 'Indique ''sí'', si los bloqueadores neuromusculares se usaron en cualquier momento durante este ingreso.', NULL, 'Machine Translation', false),
	(92529, '2026-03-24 08:40:11.045472+00', 102064, 'french', 'Oxyde nitrique inhalé', NULL, 'Machine Translation', false),
	(92530, '2026-03-24 08:40:11.045472+00', 102064, 'portuguese', 'Óxido nítrico inalado', NULL, 'Machine Translation', false),
	(92531, '2026-03-24 08:40:11.045472+00', 102064, 'spanish', 'Óxido nítrico inhalado', NULL, 'Machine Translation', false),
	(92532, '2026-03-24 08:40:11.045472+00', 102065, 'french', 'Cela fait référence à l''oxyde nitrique comme dans l''inhalant généralement utilisé pour une insuffisance respiratoire hypoxique entre autres utilisations.', NULL, 'Machine Translation', false),
	(92533, '2026-03-24 08:40:11.045472+00', 102065, 'portuguese', 'Isso se refere ao óxido nítrico, como no inalante, normalmente usado para insuficiência respiratória hipóxica, entre outros usos.', NULL, 'Machine Translation', false),
	(92534, '2026-03-24 08:40:11.045472+00', 102065, 'spanish', 'Esto se refiere al óxido nítrico como en el inhalante típicamente utilizado para insuficiencia respiratoria hipóxica, entre otros usos.', NULL, 'Machine Translation', false),
	(92535, '2026-03-24 08:40:11.045472+00', 102066, 'french', 'Indiquez «oui» si l''oxyde nitrique inhalé a été utilisé à tout moment pendant cette admission.', NULL, 'Machine Translation', false),
	(92536, '2026-03-24 08:40:11.045472+00', 102066, 'portuguese', 'Indique ''sim'' se o óxido nítrico inalado foi usado a qualquer momento durante essa admissão.', NULL, 'Machine Translation', false),
	(92537, '2026-03-24 08:40:11.045472+00', 102066, 'spanish', 'Indique ''sí'' si se usó óxido nítrico inhalado en cualquier momento durante este ingreso.', NULL, 'Machine Translation', false),
	(92538, '2026-03-24 08:40:11.045472+00', 102067, 'french', 'Trachéotomie insérée', NULL, 'Machine Translation', false),
	(92539, '2026-03-24 08:40:11.045472+00', 102067, 'portuguese', 'Traqueostomia inserida', NULL, 'Machine Translation', false),
	(92540, '2026-03-24 08:40:11.045472+00', 102067, 'spanish', 'Traqueotomía insertada', NULL, 'Machine Translation', false),
	(92541, '2026-03-24 08:40:11.045472+00', 102068, 'french', 'Cela fait référence à la formation chirurgicale d''une ouverture dans la trachée à travers le cou, ou à l''ouverture ainsi créée.', NULL, 'Machine Translation', false),
	(92542, '2026-03-24 08:40:11.045472+00', 102068, 'portuguese', 'Isso se refere à formação cirúrgica de uma abertura na traquéia através do pescoço, ou a abertura assim criada.', NULL, 'Machine Translation', false),
	(92543, '2026-03-24 08:40:11.045472+00', 102068, 'spanish', 'Esto se refiere a la formación quirúrgica de una abertura en la tráquea a través del cuello, o la abertura creada.', NULL, 'Machine Translation', false),
	(92544, '2026-03-24 08:40:11.045472+00', 102069, 'french', 'Indiquez «oui» si une trachéotomie a été insérée sur le patient à tout moment pendant l''admission.', NULL, 'Machine Translation', false),
	(92545, '2026-03-24 08:40:11.045472+00', 102069, 'portuguese', 'Indique ''sim'' se uma traqueostomia foi inserida no paciente a qualquer momento durante a admissão.', NULL, 'Machine Translation', false),
	(92546, '2026-03-24 08:40:11.045472+00', 102069, 'spanish', 'Indique ''sí'' si se insertó una traqueotomía en el paciente en cualquier momento durante el ingreso.', NULL, 'Machine Translation', false),
	(92547, '2026-03-24 08:40:11.045472+00', 102070, 'french', 'Thérapie de remplacement rénal (RRT) ou dialyse', NULL, 'Machine Translation', false),
	(92548, '2026-03-24 08:40:11.045472+00', 102070, 'portuguese', 'Terapia de reposição renal (RRT) ou diálise', NULL, 'Machine Translation', false),
	(92549, '2026-03-24 08:40:11.045472+00', 102070, 'spanish', 'Terapia de reemplazo renal (RRT) o diálisis', NULL, 'Machine Translation', false),
	(92550, '2026-03-24 08:40:11.045472+00', 102071, 'french', 'Cela fait référence aux traitements qui se remplacent à la fonction de filtrage sanguin des reins. Il comprend la dialyse (hémodialyse ou dialyse péritonéale), l''hémofiltration et l''hémodiafiltration. La greffe de rein peut également être considérée comme une thérapie de remplacement rénale. Il peut être intermittent ou continu.', NULL, 'Machine Translation', false),
	(92551, '2026-03-24 08:40:11.045472+00', 102071, 'portuguese', 'Isso se refere a tratamentos que substituem a função de filtragem no sangue dos rins. Inclui diálise (hemodiálise ou diálise peritoneal), hemofiltração e hemodiafiltração. O transplante de rim também pode ser considerado uma terapia de reposição renal. Pode ser intermitente ou contínuo.', NULL, 'Machine Translation', false),
	(92552, '2026-03-24 08:40:11.045472+00', 102071, 'spanish', 'Esto se refiere a tratamientos que sustituyen la función de filtro de sangre de los riñones. Incluye diálisis (hemodiálisis o diálisis peritoneal), hemofiltración y hemodiafiltración. El trasplante de riñón también puede considerarse una terapia de reemplazo renal. Puede ser intermitente o continuo.', NULL, 'Machine Translation', false),
	(92553, '2026-03-24 08:40:11.045472+00', 102072, 'french', 'Indiquez «oui», si le patient a reçu un traitement de remplacement rénal continu ou une hémodialyse intermittente à tout moment pendant l''hospitalisation.', NULL, 'Machine Translation', false),
	(92554, '2026-03-24 08:40:11.045472+00', 102072, 'portuguese', 'Indique ''sim'', se o paciente recebeu terapia de reposição renal contínua ou hemodiálise intermitente a qualquer momento durante a hospitalização.', NULL, 'Machine Translation', false),
	(92555, '2026-03-24 08:40:11.045472+00', 102072, 'spanish', 'Indique ''sí'', si el paciente recibió terapia de reemplazo renal continuo o hemodiálisis intermitente en cualquier momento durante la hospitalización.', NULL, 'Machine Translation', false),
	(92556, '2026-03-24 08:40:11.045472+00', 102073, 'french', 'Nombre de jours civils sur la durée du RRT ou de la dialyse pendant l''admission', NULL, 'Machine Translation', false),
	(92557, '2026-03-24 08:40:11.045472+00', 102073, 'portuguese', 'Número de dias de calendário no RRT ou duração da diálise durante a admissão', NULL, 'Machine Translation', false),
	(92558, '2026-03-24 08:40:11.045472+00', 102073, 'spanish', 'Número de días calendario en RRT o duración de diálisis durante la admisión', NULL, 'Machine Translation', false),
	(92559, '2026-03-24 08:40:11.045472+00', 102074, 'french', 'Cela fait référence au nombre total de jours que le patient a reçu du RRT ou de la dialyse à tout moment lors de cette admission.', NULL, 'Machine Translation', false),
	(92560, '2026-03-24 08:40:11.045472+00', 102074, 'portuguese', 'Isso se refere ao número total de dias em que o paciente recebeu RRT ou diálise a qualquer momento durante essa admissão.', NULL, 'Machine Translation', false),
	(92561, '2026-03-24 08:40:11.045472+00', 102074, 'spanish', 'Esto se refiere al número total de días que el paciente recibió RRT o diálisis en cualquier momento durante este ingreso.', NULL, 'Machine Translation', false),
	(92562, '2026-03-24 08:40:11.045472+00', 102075, 'french', 'Écrivez le nombre total de jours civils que le patient a reçu le RRT ou la dialyse à tout moment pendant cette admission. Même si le patient a reçu cela plus d''une fois dans un jour civil (c''est-à-dire entre 00h00 et 24h00), cela compte comme un pour le nombre total de jours.', NULL, 'Machine Translation', false),
	(92563, '2026-03-24 08:40:11.045472+00', 102075, 'portuguese', 'Escreva o número total de dias de calendário que o paciente recebeu RRT ou diálise a qualquer momento durante essa admissão. Mesmo que o paciente tenha recebido isso mais de uma vez em um dia do calendário (ou seja, entre 00:00 e 24:00 horas), isso conta como um para o número total de dias.', NULL, 'Machine Translation', false),
	(92564, '2026-03-24 08:40:11.045472+00', 102075, 'spanish', 'Escriba el número total de días calendario que el paciente recibió RRT o diálisis en cualquier momento durante este ingreso. Incluso si el paciente recibió esto más de una vez en un día calendario (es decir, entre las 00:00 y las 24:00 horas), esto cuenta como uno al número total de días.', NULL, 'Machine Translation', false),
	(92565, '2026-03-24 08:40:11.045472+00', 102076, 'french', 'Inotropes / vasopresseurs', NULL, 'Machine Translation', false),
	(92566, '2026-03-24 08:40:11.045472+00', 102076, 'portuguese', 'Inotropes / Vasopressors', NULL, 'Machine Translation', false),
	(92567, '2026-03-24 08:40:11.045472+00', 102076, 'spanish', 'Inotropes / vasopresores', NULL, 'Machine Translation', false),
	(92568, '2026-03-24 08:40:11.045472+00', 102077, 'french', 'Cela fait référence à l''utilisation continue d''un vasopresseur ou d''un inotrope pendant au moins une heure. Les agents comprennent la noradrénaline, l''épinéphrine, la vasopressine, la terlipressine et la phényléphrine. Les inotropes «positifs» couramment utilisés comprennent la dobutamine, la dopamine, la milrinone et l''adrénaline (épinéphrine).', NULL, 'Machine Translation', false),
	(92569, '2026-03-24 08:40:11.045472+00', 102077, 'portuguese', 'Isso se refere ao uso contínuo de um vasopressor ou inotrope por pelo menos uma hora. Os agentes incluem noradrenalina, epinefrina, vasopressina, terlipressina e fenilefrina. Os inotropos "positivos" comumente usados ​​incluem dobutamina, dopamina, milrinona e adrenalina (epinefrina).', NULL, 'Machine Translation', false),
	(92570, '2026-03-24 08:40:11.045472+00', 102077, 'spanish', 'Esto se refiere al uso continuo de un vasopresor o inotropeo durante al menos una hora. Los agentes incluyen noradrenalina, epinefrina, vasopresina, terlipresina y fenilefrina. Los inotropos ''positivos'' comúnmente utilizados incluyen dobutamina, dopamina, milrinona y adrenalina (epinefrina).', NULL, 'Machine Translation', false),
	(92571, '2026-03-24 08:40:11.045472+00', 102078, 'french', 'Indiquez «oui», si le patient a reçu des inotropes / vasopresseurs pendant au moins une heure à tout moment pendant l''hospitalisation.', NULL, 'Machine Translation', false),
	(92572, '2026-03-24 08:40:11.045472+00', 102078, 'portuguese', 'Indique ''sim'', se o paciente recebeu inotropes / vasopressores por pelo menos uma hora a qualquer momento durante a hospitalização.', NULL, 'Machine Translation', false),
	(92573, '2026-03-24 08:40:11.045472+00', 102078, 'spanish', 'Indique ''sí'', si el paciente recibió inotropas / vasopresores durante al menos una hora en cualquier momento durante la hospitalización.', NULL, 'Machine Translation', false),
	(92574, '2026-03-24 08:40:11.045472+00', 102079, 'french', 'Durée totale des inotropes / vasopresseurs pendant l''admission (jours)', NULL, 'Machine Translation', false),
	(92575, '2026-03-24 08:40:11.045472+00', 102079, 'portuguese', 'Inotropes totais / duração do vasopressor durante a admissão (dias)', NULL, 'Machine Translation', false),
	(92576, '2026-03-24 08:40:11.045472+00', 102079, 'spanish', 'Duración total de inotropas / vasopresores durante la admisión (días)', NULL, 'Machine Translation', false),
	(92577, '2026-03-24 08:40:11.045472+00', 102080, 'french', 'Il se réfère au nombre total de jours au cours de cette admission que le patient a reçu une thérapie inotrope / vasoactive.', NULL, 'Machine Translation', false),
	(92578, '2026-03-24 08:40:11.045472+00', 102080, 'portuguese', 'Refere -se ao número total de dias durante essa admissão de que o paciente recebeu terapia inotrópica/vasoativa.', NULL, 'Machine Translation', false),
	(92579, '2026-03-24 08:40:11.045472+00', 102080, 'spanish', 'Se refiere al número total de días durante este ingreso de que el paciente recibió terapia inotrópica/vasoactiva.', NULL, 'Machine Translation', false),
	(92580, '2026-03-24 08:40:11.045472+00', 102081, 'french', 'Écrivez le nombre total de jours civils Le patient a reçu un traitement inotrope ou vasoactif à tout moment de cette admission.', NULL, 'Machine Translation', false),
	(92581, '2026-03-24 08:40:11.045472+00', 102081, 'portuguese', 'Escreva o número total de dias de calendário que o paciente recebeu terapia inotrópica ou vasoativa a qualquer momento durante essa admissão.', NULL, 'Machine Translation', false),
	(92582, '2026-03-24 08:40:11.045472+00', 102081, 'spanish', 'Escriba el número total de días calendario que el paciente recibió terapia inotrópica o vasoactiva en cualquier momento durante este ingreso.', NULL, 'Machine Translation', false),
	(92583, '2026-03-24 08:40:11.045472+00', 102082, 'french', 'Autres interventions ou procédures de soins intensifs', NULL, 'Machine Translation', false),
	(92584, '2026-03-24 08:40:11.045472+00', 102082, 'portuguese', 'Outras intervenções de cuidados intensivos ou procedimentos (s) ou procedimentos', NULL, 'Machine Translation', false),
	(92585, '2026-03-24 08:40:11.045472+00', 102082, 'spanish', 'Otras intervención o procedimientos de cuidados críticos', NULL, 'Machine Translation', false),
	(92586, '2026-03-24 08:40:11.045472+00', 102083, 'french', 'Cela fait référence à toute autre intervention thérapeutique ou procédure non caractéristique spécifique qui n''est pas caractérisée par ailleurs qui, selon vous, peut être pertinente.', NULL, 'Machine Translation', false),
	(92587, '2026-03-24 08:40:11.045472+00', 102083, 'portuguese', 'Isso refere -se a qualquer outra intervenção terapêutica (s) ou procedimento (s) ou procedimento (s) específica (s) que você acredita que possa ser relevante.', NULL, 'Machine Translation', false),
	(92588, '2026-03-24 08:40:11.045472+00', 102083, 'spanish', 'Esto se refiere a cualquier otra intervención terapéutica de cuidados críticos específicos (s) o procedimientos que no se caractericen de otra manera que cree que puede ser relevante.', NULL, 'Machine Translation', false),
	(92589, '2026-03-24 08:40:11.045472+00', 102084, 'french', 'Indiquez «oui» si d''autres interventions ou procédures de soins intensifs étaient utilisées à tout moment pendant l''hospitalisation.', NULL, 'Machine Translation', false),
	(92590, '2026-03-24 08:40:11.045472+00', 102084, 'portuguese', 'Indique ''sim'' se outras intervenções ou procedimentos de cuidados intensivos foram usados ​​a qualquer momento durante a hospitalização.', NULL, 'Machine Translation', false),
	(92591, '2026-03-24 08:40:11.045472+00', 102084, 'spanish', 'Indique ''sí'' si se usaron otras intervención o procedimientos de cuidados críticos en cualquier momento durante la hospitalización.', NULL, 'Machine Translation', false),
	(92592, '2026-03-24 08:40:11.045472+00', 102085, 'french', 'Si autre: veuillez spécifier d''autres interventions ou procédures de soins intensifs ou procédures', NULL, 'Machine Translation', false),
	(92593, '2026-03-24 08:40:11.045472+00', 102085, 'portuguese', 'Se o outro: especifique outras intervenções de cuidados intensivos ou procedimentos (s) ou procedimentos (s)', NULL, 'Machine Translation', false),
	(92594, '2026-03-24 08:40:11.045472+00', 102085, 'spanish', 'Si es otros: especifique otras intervención o procedimientos de cuidados críticos', NULL, 'Machine Translation', false),
	(92595, '2026-03-24 08:40:11.045472+00', 102086, 'french', 'Cela fait référence à toute autre intervention thérapeutique ou procédure non caractéristique spécifique qui n''est pas caractérisée par ailleurs qui, selon vous, peut être pertinente.', NULL, 'Machine Translation', false),
	(92596, '2026-03-24 08:40:11.045472+00', 102086, 'portuguese', 'Isso refere -se a qualquer outra intervenção terapêutica (s) ou procedimento (s) ou procedimento (s) específica (s) que você acredita que possa ser relevante.', NULL, 'Machine Translation', false),
	(92597, '2026-03-24 08:40:11.045472+00', 102086, 'spanish', 'Esto se refiere a cualquier otra intervención terapéutica de cuidados críticos específicos (s) o procedimientos que no se caractericen de otra manera que cree que puede ser relevante.', NULL, 'Machine Translation', false),
	(92598, '2026-03-24 08:40:11.045472+00', 102087, 'french', 'Si «oui», veuillez spécifier la ou les interventions thérapeutiques de soins intensifs ou les procédures non caractérisées par ailleurs que vous pensez être pertinentes.', NULL, 'Machine Translation', false),
	(92599, '2026-03-24 08:40:11.045472+00', 102087, 'portuguese', 'Se ''sim'', especifique a intervenção terapêutica (s) ou procedimento (s) ou procedimento (s) que você acredita que pode ser relevante.', NULL, 'Machine Translation', false),
	(92600, '2026-03-24 08:40:11.045472+00', 102087, 'spanish', 'Si ''sí'', especifique la intervención terapéutica o procedimientos terapéuticos de cuidados críticos que no se caracterizan de otra manera que cree que puede ser relevante.', NULL, 'Machine Translation', false),
	(92601, '2026-03-24 08:40:11.045472+00', 102088, 'french', 'Résultat de la dengue', NULL, 'Machine Translation', false),
	(92602, '2026-03-24 08:40:11.045472+00', 102088, 'portuguese', 'Resultado da dengue', NULL, 'Machine Translation', false),
	(92603, '2026-03-24 08:40:11.045472+00', 102088, 'spanish', 'Resultado del dengue', NULL, 'Machine Translation', false),
	(92604, '2026-03-24 08:40:11.045472+00', 102089, 'french', 'Le principal diagnostic du patient était-il de la dengue?', NULL, 'Machine Translation', false),
	(92605, '2026-03-24 08:40:11.045472+00', 102089, 'portuguese', 'O principal diagnóstico do paciente foi dengue?', NULL, 'Machine Translation', false),
	(92606, '2026-03-24 08:40:11.045472+00', 102089, 'spanish', '¿Fue el diagnóstico principal del paciente dengue?', NULL, 'Machine Translation', false),
	(92607, '2026-03-24 08:40:11.045472+00', 102090, 'french', 'Se référant à cette présentation ou à cette admission, a-t-il été le principal diagnostic de ce patient?', NULL, 'Machine Translation', false),
	(92608, '2026-03-24 08:40:11.045472+00', 102090, 'portuguese', 'Referindo -se a esta apresentação ou admissão, foi a dengue principal ou primária do paciente?', NULL, 'Machine Translation', false),
	(92609, '2026-03-24 08:40:11.045472+00', 102090, 'spanish', 'Refiriéndose a esta presentación o admisión, ¿fue el dengue de diagnóstico principal o primario de este paciente?', NULL, 'Machine Translation', false),
	(92610, '2026-03-24 08:40:11.045472+00', 102091, 'french', 'Indiquez «oui» si le diagnostic principal ou primaire de ce patient à la présentation ou à l''admission.', NULL, 'Machine Translation', false),
	(92611, '2026-03-24 08:40:11.045472+00', 102091, 'portuguese', 'Indique ''sim'' se a dengue principal ou primária deste paciente na apresentação ou admissão.', NULL, 'Machine Translation', false),
