	(92615, '2026-03-24 08:40:11.045472+00', 102092, 'spanish', 'Si no fue el diagnóstico principal del paciente: ¿cuál fue el diagnóstico principal?', NULL, 'Machine Translation', false),
	(92616, '2026-03-24 08:40:11.045472+00', 102093, 'french', 'Se référant à cette présentation ou à cette admission, sinon de la dengue, quel a été le diagnostic principal ou principal du patient?', NULL, 'Machine Translation', false),
	(92617, '2026-03-24 08:40:11.045472+00', 102093, 'portuguese', 'Referindo -se a esta apresentação ou admissão, se não dengue, qual foi o diagnóstico principal ou primário do paciente?', NULL, 'Machine Translation', false),
	(92618, '2026-03-24 08:40:11.045472+00', 102093, 'spanish', 'Refiriéndose a esta presentación o admisión, si no al dengue, ¿cuál fue el diagnóstico principal o primario del paciente?', NULL, 'Machine Translation', false),
	(92619, '2026-03-24 08:40:11.045472+00', 102094, 'french', 'Si ce n''est pas la dengue, rédigez le diagnostic principal ou primaire du patient lors de la présentation ou de l''admission.', NULL, 'Machine Translation', false),
	(92620, '2026-03-24 08:40:11.045472+00', 102094, 'portuguese', 'Se não for dengue, escreva o diagnóstico principal ou primário do paciente durante a apresentação ou admissão.', NULL, 'Machine Translation', false),
	(92621, '2026-03-24 08:40:11.045472+00', 102094, 'spanish', 'Si no es un dengue, escriba el diagnóstico principal o primario del paciente durante la presentación o el ingreso.', NULL, 'Machine Translation', false),
	(92622, '2026-03-24 08:40:11.045472+00', 102095, 'french', 'Si oui, était le principal diagnostic du patient dengue: quelle a été la classification finale de la dengue?', NULL, 'Machine Translation', false),
	(92623, '2026-03-24 08:40:11.045472+00', 102095, 'portuguese', 'Se sim, foi a principal dengue do diagnóstico do paciente: qual foi a classificação final da dengue?', NULL, 'Machine Translation', false),
	(92624, '2026-03-24 08:40:11.045472+00', 102095, 'spanish', 'En caso afirmativo, fue el diagnóstico principal del paciente: ¿Cuál fue la clasificación final del dengue?', NULL, 'Machine Translation', false),
	(92625, '2026-03-24 08:40:11.045472+00', 102097, 'french', 'Sélectionnez l''option la plus appropriée correspondant à la classification finale de la dengue (sur la base de la classification de la dengue de l''Organisation mondiale de la santé 2009).', NULL, 'Machine Translation', false),
	(92626, '2026-03-24 08:40:11.045472+00', 102097, 'portuguese', 'Selecione a opção mais apropriada correspondente à classificação final da dengue (com base na classificação da dengue da Organização Mundial da Saúde de 2009).', NULL, 'Machine Translation', false),
	(92627, '2026-03-24 08:40:11.045472+00', 102097, 'spanish', 'Seleccione la opción más apropiada correspondiente a la clasificación final del dengue (basado en la clasificación de dengue de la Organización Mundial de la Salud de 2009).', NULL, 'Machine Translation', false),
	(92628, '2026-03-24 08:40:11.045472+00', 102098, 'french', 'Syndrome de choc de la dengue', NULL, 'Machine Translation', false),
	(92629, '2026-03-24 08:40:11.045472+00', 102098, 'portuguese', 'Síndrome do choque da dengue', NULL, 'Machine Translation', false),
	(92630, '2026-03-24 08:40:11.045472+00', 102098, 'spanish', 'Síndrome de choque de dengue', NULL, 'Machine Translation', false),
	(92631, '2026-03-24 08:40:11.045472+00', 102099, 'french', 'Le syndrome de choc de la dengue (DSS) fait référence à une fuite de plasma sévère conduisant à un choc et / ou à une accumulation de liquide avec une détresse respiratoire.', NULL, 'Machine Translation', false),
	(92632, '2026-03-24 08:40:11.045472+00', 102099, 'portuguese', 'A síndrome de choque de dengue (DSS) refere -se a vazamentos graves de plasma, levando ao acúmulo de choque e/ou fluido com desconforto respiratório.', NULL, 'Machine Translation', false),
	(92633, '2026-03-24 08:40:11.045472+00', 102099, 'spanish', 'El síndrome de choque de dengue (DSS) se refiere a una fuga de plasma severa que conduce a shock y/o acumulación de líquidos con dificultad respiratoria.', NULL, 'Machine Translation', false),
	(92634, '2026-03-24 08:40:11.045472+00', 102100, 'french', 'Indiquez «oui» si le patient subit cette complication de la dengue sévère que le patient a connu lors de cette admission.', NULL, 'Machine Translation', false),
	(92635, '2026-03-24 08:40:11.045472+00', 102100, 'portuguese', 'Indique ''sim'' se o paciente experimentar essa complicação de dengue grave que o paciente experimentou durante essa admissão.', NULL, 'Machine Translation', false),
	(92636, '2026-03-24 08:40:11.045472+00', 102100, 'spanish', 'Indique ''sí'' si el paciente experimenta esta complicación del dengue severo que el paciente experimentó durante este ingreso.', NULL, 'Machine Translation', false),
