	(93268, '2026-06-22 13:22:39.541557+00', 103688, 'french', 'Il s''agit de la date du contact avec toute personne présentant des symptômes similaires ou avec un cas confirmé connu, ou avec du matériel contaminé provenant d''un cas suspecté ou confirmé (par exemple des fluides corporels, des objets, de la literie, etc.).', NULL, 'Machine Translation', false),
	(93269, '2026-06-22 13:22:39.541557+00', 103688, 'portuguese', 'Refere-se à data do contato com qualquer pessoa que apresente sintomas semelhantes ou com caso confirmado conhecido, ou com material contaminado de um caso suspeito ou confirmado (por exemplo, fluidos corporais, objetos, roupas de cama, etc.).', NULL, 'Machine Translation', false),
	(93270, '2026-06-22 13:22:39.541557+00', 103688, 'spanish', 'Esto se refiere a la fecha de contacto con cualquier persona que presente síntomas similares o con un caso confirmado conocido, o con material contaminado de un caso sospechoso o confirmado (por ejemplo, fluidos corporales, objetos, ropa de cama, etc.).', NULL, 'Machine Translation', false),
	(93271, '2026-06-22 13:22:39.541557+00', 103689, 'french', 'Entrez la date du contact avec un cas humain suspecté ou confirmé. (Utilisez le format JJ/MM/AAAA)', NULL, 'Machine Translation', false),
	(93272, '2026-06-22 13:22:39.541557+00', 103689, 'portuguese', 'Insira a data do contato com caso humano suspeito ou confirmado. (Use o formato DD/MM/AAAA)', NULL, 'Machine Translation', false),
	(93273, '2026-06-22 13:22:39.541557+00', 103689, 'spanish', 'Ingrese la fecha del contacto con el caso humano sospechoso o confirmado. (Utilice el formato DD/MM/AAAA)', NULL, 'Machine Translation', false),
	(93274, '2026-06-22 13:22:39.541557+00', 103690, 'french', 'Il s''agit du contact avec des oiseaux vivants (par exemple, poulets, dindes, canards) au cours des 14 derniers jours.', NULL, 'Machine Translation', false),
	(93275, '2026-06-22 13:22:39.541557+00', 103690, 'portuguese', 'Refere-se ao contato com aves vivas (por exemplo, galinhas, perus, patos) ocorrido nos últimos 14 dias.', NULL, 'Machine Translation', false),
	(93276, '2026-06-22 13:22:39.541557+00', 103690, 'spanish', 'Se refiere al contacto con aves vivas (por ejemplo, pollos, pavos, patos) que haya tenido lugar en los últimos 14 días.', NULL, 'Machine Translation', false),
	(93277, '2026-06-22 13:22:39.541557+00', 103691, 'french', 'Il s''agit d''un contact avec des oiseaux vivants (par exemple poulets, dindes, canards) survenu au cours des 14 derniers jours.', NULL, 'Machine Translation', false),
	(93278, '2026-06-22 13:22:39.541557+00', 103691, 'portuguese', 'Refere-se ao contacto com aves vivas (por exemplo, galinhas, perus, patos) que ocorreu nos últimos 14 dias.', NULL, 'Machine Translation', false),
	(93279, '2026-06-22 13:22:39.541557+00', 103691, 'spanish', 'Se refiere al contacto con aves vivas (por ejemplo, pollos, pavos, patos) que se produjo en los últimos 14 días.', NULL, 'Machine Translation', false),
	(93280, '2026-06-22 13:22:39.541557+00', 103693, 'french', 'Inconnu', NULL, 'Machine Translation', false),
