	(93470, '2026-06-22 13:22:39.541557+00', 103757, 'portuguese', 'Plaquetas refere-se à transferência de plaquetas sanguíneas de um doador para um receptor ou reinfusão ao doador.', NULL, 'Machine Translation', false),
	(93471, '2026-06-22 13:22:39.541557+00', 103757, 'spanish', 'Plaquetas se refiere a la transferencia de plaquetas sanguíneas de un donante a un receptor o la reinfusión al donante.', NULL, 'Machine Translation', false),
	(93472, '2026-06-22 13:22:39.541557+00', 103758, 'french', 'Enregistrez le nombre d''unités que le patient a reçues dans les 24 heures précédant cette admission/présentation en millilitres (mL).', NULL, 'Machine Translation', false),
	(93473, '2026-06-22 13:22:39.541557+00', 103758, 'portuguese', 'Registrar o número de unidades que o paciente recebeu nas 24 horas anteriores a esta internação/apresentação em mililitros (mL).', NULL, 'Machine Translation', false),
	(93474, '2026-06-22 13:22:39.541557+00', 103758, 'spanish', 'Registre la cantidad de unidades que recibió el paciente en las 24 horas previas a este ingreso/presentación en mililitros (mL).', NULL, 'Machine Translation', false),
