	(93512, '2026-06-22 13:22:39.541557+00', 103771, 'portuguese', 'Concentrado de glóbulos vermelhos (concentrado de glóbulos vermelhos) (unidades/24 horas)', NULL, 'Machine Translation', false),
	(93513, '2026-06-22 13:22:39.541557+00', 103771, 'spanish', 'Envasados ​​de glóbulos rojos (concentrado de glóbulos rojos) (unidades/24 horas)', NULL, 'Machine Translation', false),
	(93514, '2026-06-22 13:22:39.541557+00', 103772, 'french', 'Les globules rouges concentrés font référence aux globules rouges provenant d''une unité de sang total après élimination de la majeure partie du plasma, laissant une unité avec un hématocrite d''environ 6 %.', NULL, 'Machine Translation', false),
	(93515, '2026-06-22 13:22:39.541557+00', 103772, 'portuguese', 'RBC concentrado refere-se a glóbulos vermelhos de uma unidade de sangue total após a remoção da maior parte do plasma, deixando uma unidade com hematócrito de cerca de 6%.', NULL, 'Machine Translation', false),
	(93516, '2026-06-22 13:22:39.541557+00', 103772, 'spanish', 'Los glóbulos rojos empaquetados se refieren a los glóbulos rojos de una unidad de sangre completa después de la eliminación de la mayor parte del plasma, dejando una unidad con un hematocrito de aproximadamente el 6%.', NULL, 'Machine Translation', false),
