	(94077, '2026-06-22 13:22:39.541557+00', 103966, 'french', 'Sélectionner le ou les agents antifibrinolytiques administrés à tout moment lors de l''admission du patient dans l''établissement clinique (hôpital), y compris aux urgences, et prescrits à la sortie.', NULL, 'Machine Translation', false),
	(94078, '2026-06-22 13:22:39.541557+00', 103966, 'portuguese', 'Selecionar o(s) agente(s) antifibrinolítico(s) administrado(s) a qualquer momento durante a admissão do paciente no centro clínico (hospital), inclusive no pronto-socorro, e prescrito(s) na alta.', NULL, 'Machine Translation', false),
	(94079, '2026-06-22 13:22:39.541557+00', 103966, 'spanish', 'Seleccionar el o los agentes antifibrinolíticos administrados en cualquier momento durante el ingreso del paciente en el centro clínico (hospital), incluido el departamento de urgencias, y prescritos al alta.', NULL, 'Machine Translation', false),
